/// Продвижение от исходного положения вдоль оси наступления, км (нет исходного — 0).
pub fn advance(start: Option<XY>, pos: XY, axis: &[XY]) -> f64 {
    let (Some(s), [a, .., b]) = (start, axis) else { return 0.0 };
    let l = a.dist(*b);
    if l < 1e-6 { return 0.0; }
    ((pos.x - s.x) * (b.x - a.x) + (pos.y - s.y) * (b.y - a.y)) / l
}

/// Действующая полоса штаба `h` по его замыслу: полоса (назад — до тылов его войск), начало оси и направление;
/// замысла нет — `None`.
pub fn current_band(sim: &Sim, h: u32) -> Option<(Band, XY, XY)> {
    let intent = sim.command.intent.get(h as usize)?.as_ref()?;
    let subs = subs_of(sim, h);
    let f = frame(sim, h, intent, &subs);
    let base = f.axis.first().copied().or_else(|| mid(&subs.iter().map(|&t| place(sim, t)).collect::<Vec<_>>())).unwrap_or_default();
    let rear = subtree_divs(sim, h).iter().map(|&i| along(sim.world.divisions[i].vars.pos, base, f.dir)).fold(0.0, f64::min);
    Some((extend_back(&f.band, base, f.dir, rear - 2.0), base, f.dir))
}

/// Цель задачи дивизии: середина ближайшей задачи, после выхода на неё — последующей; без рубежей — на месте.
fn div_target(d: &Directive, pos: XY) -> XY {
    d.immediate.as_ref().and_then(|l| mid(&l.pts)).or_else(|| d.subsequent.as_ref().and_then(|l| mid(&l.pts))).unwrap_or(pos)
}

/// Продление полос армий (пункт 9 спецификации пакета команд; режимы `follow_bands`): армия — агент или штаб игрока
/// (полоса по его директиве; штаб держит её впереди войск, очертание прежнее) — наступает, а её передний край по оси дальше
/// конца полосы без половины глубины полосы (или рубеж ближайшей задачи за концом полосы) — границы замысла
/// продлеваются вперёд по оси до переднего края плюс глубина ближайшей задачи (нет — 20 км); документ — распоряжение
/// в штабе армии. Новый замысел (директива) границы задаёт заново.
pub fn extend_bands(sim: &mut Sim, tick: u32) {
    if !sim.command.follow_bands { return; }
    for h in 0..sim.world.hqs.len() {
        if sim.world.hqs[h].echelon != Echelon::Army || !matches!(sim.command.control[h], Control::Agent | Control::Player) { continue; }
        let Some(intent) = sim.command.intent[h].as_ref() else { continue };
        if !matches!(intent.task, Task::Attack | Task::Move) || intent.axis.len() < 2 { continue; }
        let subs = subs_of(sim, h as u32);
        if subs.is_empty() { continue; }
        let f = frame(sim, h as u32, intent, &subs);
        let base = f.axis[0];
        let divs = subtree_divs(sim, h as u32);
        if divs.is_empty() { continue; }
        let front = divs.iter().map(|&i| along(sim.world.divisions[i].vars.pos, base, f.dir)).fold(f64::NEG_INFINITY, f64::max);
        let task = intent.immediate.as_ref().map(|l| l.pts.iter().map(|&p| along(p, base, f.dir)).fold(f64::NEG_INFINITY, f64::max)).unwrap_or(f64::NEG_INFINITY);
        let depth = if task - front >= 5.0 { task - front } else { BAND_DEPTH_KM };
        let reach = reach_km(&f.band, base, f.dir);
        if front <= reach - 0.5 * depth && task <= reach + 0.5 { continue; }
        let to = (front + depth).max(task);
        let band = extend_band(&f.band, base, f.dir, to);
        let i = sim.command.intent[h].as_mut().unwrap();
        i.boundaries = vec![(None, band.left), (None, band.right)];
        // документ — по штабу армии (старший её полосу задал замыслом; директивы старшего — только его замыслы)
        sim.documents.push(Document { tick, hq: h as u32, kind: DocKind::Instruction, to: Vec::new(),
            text: format!("продлить полосу до {:.0} км по оси (передний край — {:.0} км)", to, front.max(0.0)),
            rule: Some("полоса армии — до переднего края и на глубину ближайшей задачи".into()) });
    }
}

/// Полоса штаба `h` по замыслу для подчинённых `subs`: ось — из замысла, иначе от центра подчинённых к середине
/// ближайшей задачи; ширина без разграничительных линий — по крайним дивизиям всего поддерева.
pub fn frame(sim: &Sim, h: u32, intent: &Directive, subs: &[Target]) -> Frame {
    let pos: Vec<XY> = subs.iter().map(|&t| place(sim, t)).collect();
    let axis = if intent.axis.len() >= 2 { intent.axis.clone() } else {
        match (mid(&pos), intent.immediate.as_ref().and_then(|l| mid(&l.pts))) { (Some(a), Some(b)) => vec![a, b], _ => Vec::new() }
    };
    let extent: Vec<XY> = { let w = &sim.world; let under = |mut k: usize| { for _ in 0..8 { if k == h as usize { return true; } match w.hqs[k].parent { Some(p) => k = p as usize, None => return false } } false };
        w.divisions.iter().filter(|d| !d.state.out() && under(d.hq as usize)).map(|d| d.vars.pos).collect() };
    let band = band_of(&axis, &intent.boundaries, if extent.is_empty() { &pos } else { &extent }, 2.0 * subs.len() as f64);
    let dir = match axis.as_slice() { [a, .., b] if a.dist(*b) > 1e-6 => XY::new((b.x - a.x) / a.dist(*b), (b.y - a.y) / a.dist(*b)), _ => XY::new(-1.0, 0.0) };
    Frame { band, axis, dir }
}

/// Общий раздел полосы: подчинённым `subs` — полосы по весам (`weights` по порядку `subs`; нет — главный удар уже),
/// ближайшая и последующая задачи — части рубежей старшего. `replan` — по циклу (распоряжением).
pub fn generic(sim: &Sim, h: u32, intent: &Directive, replan: bool, subs: &[Target], weights: Option<&[f64]>) -> Vec<Directive> {
    let mut subs: Vec<Target> = subs.to_vec();
    if subs.is_empty() { return Vec::new(); }
    let given: Option<Vec<f64>> = weights.map(|w| w.to_vec());
    let pos: Vec<XY> = subs.iter().map(|&t| place(sim, t)).collect();
    let Frame { band, axis, dir } = frame(sim, h, intent, &subs);
    let base = axis.first().copied().or_else(|| mid(&pos)).unwrap_or_default();
    let side = |p: XY| -dir.y * (p.x - base.x) + dir.x * (p.y - base.y);
    let mut order: Vec<usize> = (0..subs.len()).collect();
    order.sort_by(|&a, &b| side(pos[b]).total_cmp(&side(pos[a])));
    subs = order.iter().map(|&k| subs[k]).collect();
    let pos: Vec<XY> = order.iter().map(|&k| pos[k]).collect();
    // главный удар — названные в замысле или ближайший к оси; там полоса уже
    let nearest = (0..pos.len()).min_by(|&a, &b| side(pos[a]).abs().total_cmp(&side(pos[b]).abs()));
    let weights: Vec<f64> = match &given {
        Some(w) => order.iter().map(|&k| w[k]).collect(),
        None => subs.iter().enumerate().map(|(k, t)| {
            let main = matches!(t, Target::Hq(x) if intent.main_blow.contains(x)) || (intent.main_blow.is_empty() && Some(k) == nearest);
            if main { 1.0 } else { 1.5 }
        }).collect(),
    };
    let form = if replan || intent.form == Form::Instruction { Form::Instruction } else { Form::Order };
    // главный удар назван в замысле — задача-точка подчинённому вне него на её глубине в своей полосе (вспомогательный
    // удар — в своей полосе; директива № 11059: 61 А и 69 А — в обход Берлина); не назван — к точке все
    let on_main: Vec<bool> = subs.iter().map(|t| intent.main_blow.is_empty() || matches!(t, Target::Hq(x) if intent.main_blow.contains(x))).collect();
    let part = |l: &Line, b: &crate::command::band::Band, main: bool| Line { pts: if l.pts.len() == 1 && !main && intent.task == Task::Attack { vec![point_in_band(l.pts[0], b)] } else { clip_line(&l.pts, b) }, by: l.by };
    split(&band, &weights).into_iter().zip(subs).zip(on_main).map(|((b, to), main)| {
        let ax = center(&b);
        Directive {
            id: format!("{}>{}", intent.id, target_id(sim, to)), from: h, to, form, task: intent.task,
            axis: vec![ax[0], *ax.last().unwrap()],
            immediate: intent.immediate.as_ref().map(|l| part(l, &b, main)),
            subsequent: intent.subsequent.as_ref().map(|l| part(l, &b, main)),
            boundaries: vec![(None, b.left.clone()), (None, b.right.clone())],
            main_blow: Vec::new(), reserve: Vec::new(), junction: None, hasty: intent.hasty, ready: intent.ready && !replan, rule: None, issued: 0, note: intent.note.clone(),
        }
    }).collect()
}

fn kind_of(t: Task) -> OrderKind {
    match t { Task::Attack => OrderKind::Attack, Task::Defend | Task::Delay => OrderKind::Defend, Task::Withdraw => OrderKind::Withdraw, Task::Move | Task::Reserve => OrderKind::Move }
}

pub fn mid(ps: &[XY]) -> Option<XY> {
    if ps.is_empty() { return None; }
    let n = ps.len() as f64;
    Some(XY::new(ps.iter().map(|p| p.x).sum::<f64>() / n, ps.iter().map(|p| p.y).sum::<f64>() / n))
}

/// Фаза командования шага: доставка директив, переход дивизий к последующей задаче, решения штабов-агентов.
pub fn phase(sim: &mut Sim, next: &mut World, tick: u32, journal: &mut Vec<Event>) {
    // история как замысел: задачи цепочек — до командующих и штабов (там, где история кончилась, решают они)
    if sim.intent.any() { crate::intent::step(sim, tick); }
    // полосы наступающих армий-агентов — до переднего края и на глубину ближайшей задачи
    extend_bands(sim, tick);
    // командующие решают до штабов: их директивы и роли штабы разбирают в этом же часе
    crate::commander::cycle(sim, tick);
    // готовые к началу директивы доходят до дивизий в тот же час — по ступеням, не больше пяти проходов
    for _ in 0..5 {
        phase_once(sim, next, tick, journal);
        if !sim.command.in_transit.iter().any(|(at, _)| *at <= tick) { break; }
    }
    record_bands(sim, tick);
}

fn phase_once(sim: &mut Sim, next: &mut World, tick: u32, journal: &mut Vec<Event>) {
    // директивы, дошедшие к этому часу
    let mut arrived = Vec::new();
    sim.command.in_transit.retain(|(at, d)| if *at <= tick { arrived.push(d.clone()); false } else { true });
    for d in arrived {
        match d.to {
            Target::Hq(h) => {
                let hu = h as usize;
                // отданная раньше уже действующей директивы того же штаба — устарела
                if sim.command.intent[hu].as_ref().is_some_and(|o| o.from == d.from && o.issued > d.issued) { continue; }
                // изъятый через голову штаб директива старшего больше не задаёт (кроме директивы игрока)
                if sim.command.led_hq[hu] && sim.command.control[d.from as usize] != Control::Player { continue; }
                // частное распоряжение (не директива: устное указание): при замысле штаба называет подчинённых на главном
                // ударе — доводится только до них
                if d.form == Form::Instruction && sim.command.intent[hu].is_some() && !d.main_blow.is_empty() && d.main_blow.iter().all(|&m| sim.world.hqs[m as usize].parent == Some(h)) {
                    for &m in &d.main_blow {
                        let mut x = d.clone();
                        x.id = format!("{}>{}", d.id, sim.world.hqs[m as usize].id);
                        x.from = h;
                        x.to = Target::Hq(m);
                        x.main_blow = Vec::new();
                        if x.axis.is_empty() { x.axis = sim.command.intent[hu].as_ref().map(|i| i.axis.clone()).unwrap_or_default(); }
                        x.rule = Some("частная директива: доводится до названных армий".into());
                        sim.command.named_hq[m as usize] = true;
                        issue(sim, x, tick);
                    }
                    continue;
                }
                // директива без оси не заменяет замысел с осью: без геометрии — только документ, с границами — новые границы
                let geo = !d.axis.is_empty() || d.immediate.is_some() || d.subsequent.is_some() || !d.boundaries.is_empty();
                if let Some(old) = sim.command.intent[hu].as_mut() {
                    if !geo { continue; }
                    if d.axis.is_empty() && !old.axis.is_empty() {
                        if !d.boundaries.is_empty() { old.boundaries = d.boundaries; }
                        continue;
                    }
                }
                // новая ось (сдвиг конца больше 10 км) — построение подчинённых заново
                let turned = match (sim.command.intent[hu].as_ref().and_then(|o| o.axis.last().copied()), d.axis.last().copied()) { (Some(a), Some(b)) => a.dist(b) > 10.0, _ => false };
                // роли эшелонов и время ожидания остаются (введённый второй эшелон не ждёт снова); продвижение — от нынешнего
                // положения, сменённые снова в строю
                if turned {
                    let (hs, ds) = crate::command::control::active_subs(sim, h);
                    for k in hs { let p = place(sim, Target::Hq(k)); sim.command.start_hq[k as usize] = Some(p); sim.command.replaced_hq[k as usize] = false; }
                    for i in ds { let p = place(sim, Target::Division(i)); sim.command.start_div[i as usize] = Some(p); sim.command.replaced[i as usize] = false; }
                }
                // новый замысел — названные через голову снова в разделе полосы
                for k in 0..sim.world.hqs.len() { if sim.world.hqs[k].parent == Some(h) { sim.command.named_hq[k] = false; } }
                sim.command.intent[hu] = Some(d);
                sim.command.fresh[hu] = true;
            }
            Target::Division(i) => {
                let iu = i as usize;
                // изъятую через голову дивизию директива старшего больше не задаёт (кроме директивы игрока ей самой)
                if sim.command.led_div.get(iu).copied().unwrap_or(false) && sim.command.control[d.from as usize] != Control::Player { continue; }
                if sim.command.div_task[iu].as_ref().is_some_and(|o| o.from == d.from && o.issued > d.issued) { continue; }
                // уже у последующей задачи, а она та же — к ближайшей не возвращаться
                let mut d = d;
                let same_sub = |a: &Option<Line>, b: &Option<Line>| match (a.as_ref().and_then(|l| mid(&l.pts)), b.as_ref().and_then(|l| mid(&l.pts))) { (Some(x), Some(y)) => x.dist(y) <= REACHED_KM, _ => false };
                if sim.command.div_task[iu].as_ref().is_some_and(|o| o.immediate.is_none() && same_sub(&o.subsequent, &d.subsequent)) { d.immediate = None; }
                let div = &mut next.divisions[iu];
                if d.hasty { div.vars.coord = div.vars.coord.min(sim.rules.command.hasty_coord); }
                let target = div_target(&d, div.vars.pos);
                next.in_transit.push((i, Order { kind: kind_of(d.task), target, forced: false, issued: tick, arrives: tick, from: d.from, note: d.note.clone() }));
                sim.command.div_task[iu] = Some(d);
            }
        }
    }
    // дивизия вышла на ближайшую задачу — к последующей; задача выполнена, когда рубеж занят: у него нет противника
    // (ПУ-39 ст. 89: ближайшая задача — овладеть рубежом; в городе, пока гарнизон держится, — не выполнена)
    let clear = sim.rules.contact_km + 4.0;
    for i in 0..sim.command.div_task.len() {
        let Some(d) = sim.command.div_task[i].as_ref() else { continue };
        let (Some(im), Some(sub)) = (d.immediate.as_ref().and_then(|l| mid(&l.pts)), d.subsequent.as_ref().and_then(|l| mid(&l.pts))) else { continue };
        if next.divisions[i].vars.pos.dist(im) > REACHED_KM { continue; }
        if crate::command::su::enemy_km_at(sim, im, next.divisions[i].side) <= clear { continue; }
        let mut d = d.clone();
        d.immediate = None;
        next.in_transit.push((i as u32, Order { kind: kind_of(d.task), target: sub, forced: false, issued: tick, arrives: tick, from: d.from, note: format!("{} — последующая задача", d.note) }));
        journal.push(Event { tick, agent: i as u32, text: "ближайшая задача выполнена — к последующей".into() });
  // … строки 296–349

/// Положение подчинённого: дивизия — её место, штаб — центр его действующих дивизий (с подчинёнными штабами).
pub fn place(sim: &Sim, t: Target) -> XY {
    let w = &sim.world;
    match t {
        Target::Division(i) => w.divisions[i as usize].vars.pos,
        Target::Hq(h) => {
            let under = |mut k: usize| { for _ in 0..8 { if k == h as usize { return true; } match w.hqs[k].parent { Some(p) => k = p as usize, None => return false } } false };
            mid(&w.divisions.iter().filter(|d| !d.state.out() && under(d.hq as usize)).map(|d| d.vars.pos).collect::<Vec<_>>()).unwrap_or(w.hqs[h as usize].pos)
        }
    }
}

/// Решение штаба по замыслу старшего: по стороне и ступени — логика ступени (command/su.rs, command/de.rs).
pub fn plan(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    match sim.world.hqs[h as usize].side {
        crate::model::Side::Su => crate::command::su::plan(sim, h, intent, replan),
        crate::model::Side::De => crate::command::de::plan(sim, h, intent, replan),
    }
}

/// Запись полос армий для следа: при смене замысла или его границ и когда войска армии вышли больше чем на 3 км за
/// последнюю записанную полосу (полоса без границ растёт вширь по войскам).
pub fn record_bands(sim: &mut Sim, tick: u32) {
    if !sim.command.follow_bands { return; }
    for h in 0..sim.world.hqs.len() {
        if sim.world.hqs[h].echelon != Echelon::Army || !matches!(sim.command.control[h], Control::Agent | Control::Player) { continue; }
        let Some(intent) = sim.command.intent[h].as_ref() else { continue };
        let sig = (intent.id.clone(), intent.issued, intent.boundaries.len(), intent.boundaries.iter().map(|(_, l)| l.len()).sum::<usize>());
        let same = sim.command.band_sig.get(&(h as u32)) == Some(&sig);
        let Some((band, _, _)) = current_band(sim, h as u32) else { continue };
        if same {
            // тот же замысел: новая запись, только если войска вышли за записанную полосу, а в нынешней они есть
            let last = sim.command.bands.iter().rev().find(|(k, _, _)| *k == h as u32).map(|(_, _, b)| b);
            let strayed = last.is_some_and(|b| subtree_divs(sim, h as u32).iter().any(|&i| { let p = sim.world.divisions[i].vars.pos; outside_km(p, b) > 3.0 && outside_km(p, &band) <= 1.0 }));
            if !strayed { continue; }
        }
        sim.command.band_sig.insert(h as u32, sig);
        sim.command.bands.push((h as u32, tick, band));
    }
}

/// Действующие подчинённые штаба целями директив: штабы, затем дивизии.
pub fn subs_of(sim: &Sim, h: u32) -> Vec<Target> {
    let (hqs, divs) = active_subs(sim, h);
    hqs.into_iter().map(Target::Hq).chain(divs.into_iter().map(Target::Division)).collect()
}

/// Живые дивизии поддерева штаба `h`.
fn subtree_divs(sim: &Sim, h: u32) -> Vec<usize> {
    let w = &sim.world;
    let under = |mut k: usize| { for _ in 0..8 { if k == h as usize { return true; } match w.hqs[k].parent { Some(p) => k = p as usize, None => return false } } false };
    (0..w.divisions.len()).filter(|&i| !w.divisions[i].state.out() && under(w.divisions[i].hq as usize)).collect()
}

/// Полоса штаба: границы — разграничительные линии слева и справа от оси (по знаку векторного произведения; из
/// нескольких на одной стороне — ближайшая к оси); недостающая граница — параллельно оси на расстоянии крайнего
/// подчинённого + 2 км, но не ближе половины `min_width_km`. Оси нет — от центра подчинённых на запад.
pub fn band_of(axis: &[XY], boundaries: &[(Option<u32>, Vec<XY>)], subs_pos: &[XY], min_width_km: f64) -> Band {
    let base = if axis.is_empty() { mean(subs_pos) } else { axis[0] };
    let (dir, len) = match axis {
        [a, .., b] if a.dist(*b) > 1e-6 => (mul(sub(*b, *a), 1.0 / a.dist(*b)), a.dist(*b)),
        _ => (XY::new(-1.0, 0.0), 30.0),
    };
    let n = XY::new(-dir.y, dir.x); // влево от направления
    let side = |l: &Vec<XY>| cross(dir, sub(mean(l), base));
    // граница точно на оси — левая
    let near = |left: bool| boundaries.iter().map(|(_, l)| l).filter(|l| l.len() >= 2 && (side(l) >= 0.0) == left)
        .min_by(|a, b| side(a).abs().total_cmp(&side(b).abs())).cloned();
    let reach = |s: f64| subs_pos.iter().map(|p| s * dot(sub(*p, base), n)).fold(0.0, f64::max);
    let parallel = |s: f64| {
        let off = (reach(s) + 2.0).max(min_width_km / 2.0);
        let a = add(base, mul(n, s * off));
        vec![a, add(a, mul(dir, len))]
    };
    Band { left: near(true).unwrap_or_else(|| parallel(1.0)), right: near(false).unwrap_or_else(|| parallel(-1.0)) }
}

/// Ось полосы: середины между границами.
pub fn center(band: &Band) -> Vec<XY> {
    let (l, r) = (sample(&band.left, SAMPLES), sample(&band.right, SAMPLES));
    (0..SAMPLES).map(|i| lerp(l[i], r[i], 0.5)).collect()
}

/// Часть рубежа внутри полосы. Рубеж из одной точки — она; рубеж не заходит в полосу — точка пересечения оси полосы
/// с рубежом, иначе центр рубежа.
pub fn clip_line(line: &[XY], band: &Band) -> Vec<XY> {
    if line.len() < 2 { return line.to_vec(); }
    let mut poly = band.left.clone();
    poly.extend(band.right.iter().rev());
    // рубеж сгущается до точек через 0,5 км, в полосе остаются лежащие внутри
    let dense: Vec<XY> = line.windows(2).flat_map(|w| {
        let n = (w[0].dist(w[1]) / 0.5).ceil().max(1.0) as usize;
        (0..n).map(move |i| lerp(w[0], w[1], i as f64 / n as f64))
    }).chain(std::iter::once(*line.last().unwrap())).collect();
    let kept: Vec<XY> = dense.into_iter().filter(|p| inside(*p, &poly)).collect();
    if !kept.is_empty() { return kept; }
    let axis = center(band);
    for a in axis.windows(2) { for s in line.windows(2) { if let Some(p) = intersect(a[0], a[1], s[0], s[1]) { return vec![p]; } } }
    // рубеж короче полосы: пересечение продолжений оси полосы и рубежа (у соседних полос — разные точки)
    let (a, b) = (axis[0], *axis.last().unwrap());
    let (c, d) = (line[0], *line.last().unwrap());
    let (r, q) = (sub(b, a), sub(d, c));
    let den = cross(r, q);
    // ближайшая точка рубежа к точке p
    let nearest = |p: XY| line.windows(2).map(|w| {
        let (d, l2) = (sub(w[1], w[0]), dot(sub(w[1], w[0]), sub(w[1], w[0])));
        let t = if l2 > 1e-12 { (dot(sub(p, w[0]), d) / l2).clamp(0.0, 1.0) } else { 0.0 };
        add(w[0], mul(d, t))
    }).min_by(|x, y| x.dist(p).total_cmp(&y.dist(p))).unwrap();
    if den.abs() > 1e-9 {
        let p = add(a, mul(r, cross(sub(c, a), q) / den));
        // продолжения пересекаются дальше 60 км за краем рубежа — ближайшая к середине полосы точка рубежа
        if nearest(p).dist(p) <= 60.0 { return vec![p]; }
    }
    vec![nearest(lerp(a, b, 0.5))]
}

/// Полоса, продлённая назад: каждая граница, начинающаяся по оси дальше `from_km`, продлена против `dir` до этой
/// проекции (тылы армии позади начала оси — в её полосе).
pub fn extend_back(band: &Band, base: XY, dir: XY, from_km: f64) -> Band {
    let ext = |l: &[XY]| {
        let Some(&first) = l.first() else { return l.to_vec() };
        let have = dot(sub(first, base), dir);
        if have <= from_km { return l.to_vec(); }
        let mut v = vec![add(first, mul(dir, from_km - have))];
        v.extend_from_slice(l);
        v
    };
    Band { left: ext(&band.left), right: ext(&band.right) }
}

/// Полоса, продлённая вперёд: каждая граница, не доходящая по оси до `to_km` (проекция на `dir` от `base`), продлена
/// по направлению своего последнего отрезка (уходит от оси назад или вбок — по оси) до этой проекции.
pub fn extend_band(band: &Band, base: XY, dir: XY, to_km: f64) -> Band {
    let ext = |l: &[XY]| {
        let mut l = l.to_vec();
        let Some(&last) = l.last() else { return l };
        let have = dot(sub(last, base), dir);
        if have >= to_km { return l; }
        let u = match l.as_slice() { [.., a, b] if a.dist(*b) > 1e-6 => mul(sub(*b, *a), 1.0 / a.dist(*b)), _ => dir };
        let u = if dot(u, dir) < 0.5 { dir } else { u };
        l.push(add(last, mul(u, (to_km - have) / dot(u, dir))));
        l
    };
    Band { left: ext(&band.left), right: ext(&band.right) }
}

fn inside(p: XY, poly: &[XY]) -> bool {
    let mut c = false;
    for i in 0..poly.len() {
        let (a, b) = (poly[i], poly[(i + 1) % poly.len()]);
        if (a.y > p.y) != (b.y > p.y) && p.x < a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y) { c = !c; }
    }
    c
}

fn intersect(a: XY, b: XY, c: XY, d: XY) -> Option<XY> {
    let (r, s) = (sub(b, a), sub(d, c));
    let den = cross(r, s);
    if den.abs() < 1e-12 { return None; }
    let t = cross(sub(c, a), s) / den;
    let u = cross(sub(c, a), r) / den;
    ((0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u)).then(|| add(a, mul(r, t)))
}

/// Насколько точка за полосой, км: внутри — 0, иначе расстояние до ближайшего края полосы (границы или их концов).
pub fn outside_km(p: XY, band: &Band) -> f64 {
    let mut poly = band.left.clone();
    poly.extend(band.right.iter().rev());
    if poly.len() < 3 || inside(p, &poly) { return 0.0; }
    (0..poly.len()).map(|i| seg_dist(p, poly[i], poly[(i + 1) % poly.len()])).fold(f64::INFINITY, f64::min)
}

/// Цель-точка в полосе подчинённого вне главного удара: лежит в полосе — она, иначе точка оси полосы на её глубине
/// (ближайшая к ней) — вспомогательные направления наступают в своих полосах, а не сходятся к точке главного удара.
pub fn point_in_band(p: XY, band: &Band) -> XY {
    let mut poly = band.left.clone();
    poly.extend(band.right.iter().rev());
    if inside(p, &poly) { return p; }
    let axis = center(band);
    axis.windows(2).map(|w| {
        let (d, l2) = (sub(w[1], w[0]), dot(sub(w[1], w[0]), sub(w[1], w[0])));
        let t = if l2 > 1e-12 { (dot(sub(p, w[0]), d) / l2).clamp(0.0, 1.0) } else { 0.0 };
        add(w[0], mul(d, t))
    }).min_by(|x, y| x.dist(p).total_cmp(&y.dist(p))).unwrap_or(p)
}

/// Докуда по оси доходит полоса, км: проекция на направление `dir` от `base` дальней точки каждой границы, меньшая из двух.
pub fn reach_km(band: &Band, base: XY, dir: XY) -> f64 {
    let far = |l: &[XY]| l.iter().map(|p| dot(sub(*p, base), dir)).fold(f64::NEG_INFINITY, f64::max);
    far(&band.left).min(far(&band.right))
}

/// Точки ломаной, равномерно по длине (`k` точек).
fn sample(line: &[XY], k: usize) -> Vec<XY> {
    if line.len() < 2 { return vec![line.first().copied().unwrap_or_default(); k]; }
    let segs: Vec<f64> = line.windows(2).map(|w| w[0].dist(w[1])).collect();
    let total: f64 = segs.iter().sum::<f64>().max(1e-9);
    (0..k).map(|i| {
        let mut s = total * i as f64 / (k - 1) as f64;
        for (j, &l) in segs.iter().enumerate() {
            if s <= l || j == segs.len() - 1 { return lerp(line[j], line[j + 1], if l > 1e-9 { (s / l).min(1.0) } else { 0.0 }); }
            s -= l;
        }
        *line.last().unwrap()
    }).collect()
}

fn seg_dist(p: XY, a: XY, b: XY) -> f64 {
    let (d, l2) = (sub(b, a), dot(sub(b, a), sub(b, a)));
    let t = if l2 > 1e-12 { (dot(sub(p, a), d) / l2).clamp(0.0, 1.0) } else { 0.0 };
    p.dist(add(a, mul(d, t)))
}

/// Деление полосы поперёк между подчинёнными по весам (слева направо).
pub fn split(band: &Band, weights: &[f64]) -> Vec<Band> {
    let (l, r) = (sample(&band.left, SAMPLES), sample(&band.right, SAMPLES));
    let total: f64 = weights.iter().sum::<f64>().max(1e-9);
    let mut acc = 0.0;
    weights.iter().map(|w| {
        let (a, b) = (acc / total, (acc + w) / total);
        acc += w;
        Band { left: (0..SAMPLES).map(|i| lerp(l[i], r[i], a)).collect(), right: (0..SAMPLES).map(|i| lerp(l[i], r[i], b)).collect() }
    }).collect()
}

/// Состояние управления по штабам и дивизиям мира.
pub struct CommandState {
    pub control: Vec<Control>,
    /// Штаб изъят из замысла старшего приказом через голову (ведёт игрок).
    pub led_hq: Vec<bool>,
    /// Дивизия изъята из замысла старшего приказом через голову.
    pub led_div: Vec<bool>,
    /// Штаб на задаче частной директивы старшей инстанции через голову своего (ПУ-39: устное указание Ставки армиям
    /// фронта) — свой штаб его в раздел полосы не берёт, пока не получит новый замысел.
    pub named_hq: Vec<bool>,
    /// Замысел старшего: последняя полученная директива штаба.
    pub intent: Vec<Option<Directive>>,
    /// Час последнего решения штаба-агента.
    pub last_cycle: Vec<u32>,
    /// Директивы в пути: (час прибытия, директива).
    pub in_transit: Vec<(u32, Directive)>,
    /// Замысел пришёл и ещё не разобран штабом.
    pub fresh: Vec<bool>,
    /// Задача дивизии по директиве: после выхода на ближайшую задачу — последующая.
    pub div_task: Vec<Option<Directive>>,
    /// Последняя задача, отданная подчинённому: (штаб, получатель) → (цель, задача).
    pub sent: std::collections::HashMap<(u32, crate::command::directive::Target), (crate::geo::XY, crate::command::directive::Task)>,
    /// Эшелоны: место штабов и дивизий в построении старшего, исходное положение, с какого часа в роли, сменена ли.
    pub role_hq: Vec<Role>,
    pub role_div: Vec<Role>,
    pub start_hq: Vec<Option<crate::geo::XY>>,
    pub start_div: Vec<Option<crate::geo::XY>>,
    pub since_hq: Vec<u32>,
    pub since_div: Vec<u32>,
    pub replaced_hq: Vec<bool>,
    pub replaced: Vec<bool>,
    /// Запросы на отход к верхней инстанции (немецкая сторона, приказ от 21.01.1945).
    pub requests: Vec<Request>,
    /// Час оттяжки армии перед артподготовкой (по штабам; один раз на угрозу).
    pub pulled: Vec<Option<u32>>,
    /// Последний час, когда у полосы армии развёртывался противник (оттяжка снова — после затишья 48 ч).
    pub pull_seen: Vec<u32>,
    /// До какого часа действует решение доктрины по дивизии (общий приказ по полосе её не перебивает).
    pub doc_until: Vec<u32>,
    /// Введённые подвижные группы, ещё не получившие задачи на глубину: (получатель, правило) — до ближайшего
    /// распределения полосы фронта (su.rs::commit_mobile).
    pub commits: Vec<(crate::command::directive::Target, String)>,
    /// Полосы армий для следа: (штаб, час, полоса) — при каждой смене (новый замысел, продление, войска вышли за
    /// нарисованную полосу); подпись последней записи по штабу — замысел и его границы.
    pub bands: Vec<(u32, u32, crate::command::band::Band)>,
    pub band_sig: std::collections::HashMap<u32, (String, u32, usize, usize)>,
    /// Полосы армий следуют за войсками (продление и запись в след) — режимы `intent`, `agents`, `commanders` и игра в
    /// них; прочие режимы (сценарий, фронты и журналы по истории, гибрид) — эталоны мерила, их полосы не трогаются.
    pub follow_bands: bool,
}

/// Все штабы — по приказам сценария (как без командования по ступеням).
pub fn new(hqs: usize, divisions: usize) -> CommandState {
    CommandState { control: vec![Control::Script; hqs], led_hq: vec![false; hqs], led_div: vec![false; divisions], named_hq: vec![false; hqs], intent: vec![None; hqs], last_cycle: vec![0; hqs], in_transit: Vec::new(), fresh: vec![false; hqs], div_task: vec![None; divisions], sent: Default::default(),
        role_hq: vec![Role::Unset; hqs], role_div: vec![Role::Unset; divisions], start_hq: vec![None; hqs], start_div: vec![None; divisions],
        since_hq: vec![0; hqs], since_div: vec![0; divisions], replaced_hq: vec![false; hqs], replaced: vec![false; divisions], requests: Vec::new(), pulled: vec![None; hqs], pull_seen: vec![0; hqs], doc_until: vec![0; divisions], commits: Vec::new(), bands: Vec::new(), band_sig: Default::default(), follow_bands: false }
}

/// Документ штаба: директива, боевой приказ, распоряжение, извещение, донесение — с обоснованием.
pub struct Document {
    pub tick: u32,
    /// Штаб, отдавший документ.
    pub hq: u32,
    pub kind: DocKind,
    /// Кому: id штабов и дивизий.
    pub to: Vec<String>,
    pub text: String,
    /// Правило (id норматива или статья устава), по которому принято решение.
    pub rule: Option<String>,
}

/// Запрос корпуса на отход дивизии: ответ — да, нет или ещё нет.
pub struct Request { pub hq: u32, pub tick: u32, pub division: u32, /// Рубеж отхода, который назвала доктрина при запросе.
    pub at: crate::geo::XY, pub answer: Option<bool>, /// Час ответа: ответ действует permissionHours.
    pub answered_at: u32 }

/// Действующие прямые подчинённые штаба: штабы и дивизии, кроме изъятых через голову, выбывших, ещё не введённых и
/// остатков.
pub fn active_subs(sim: &Sim, h: u32) -> (Vec<u32>, Vec<u32>) {
    let w = &sim.world;
    let c = &sim.command;
    // штаб без действующих дивизий в поддереве — не подчинённый для задачи
    let alive = |k: u32| w.divisions.iter().any(|d| !d.state.out() && d.state != State::Remnant && { let mut x = d.hq; let mut ok = false; for _ in 0..8 { if x == k { ok = true; break; } match w.hqs[x as usize].parent { Some(p) => x = p, None => break } } ok });
    let hqs = (0..w.hqs.len() as u32).filter(|&k| w.hqs[k as usize].parent == Some(h) && !c.led_hq.get(k as usize).copied().unwrap_or(false) && !c.named_hq.get(k as usize).copied().unwrap_or(false) && alive(k)).collect();
    let divs = (0..w.divisions.len() as u32).filter(|&i| {
        let d = &w.divisions[i as usize];
        d.hq == h && !c.led_div.get(i as usize).copied().unwrap_or(false) && !d.state.out() && d.state != State::Remnant
    }).collect();
    (hqs, divs)
}

/// Сторона `side` под командованием по ступеням: верхняя инстанция — игрок, ниже — штабы-агенты.
pub fn agents_side(sim: &mut Sim, side: crate::model::Side) {
    for (k, h) in sim.world.hqs.iter().enumerate() {
        if h.side != side { continue; }
        sim.command.control[k] = if h.echelon == crate::model::Echelon::HighCommand { Control::Player } else { Control::Agent };
    }
}

/// Режим командования прогона стороны `side`: `script` — приказы сценария; `agents` — штабы-агенты под историческими
/// директивами Ставки (верхняя инстанция — агент: отвечает на запросы отхода); `hybrid` — поддеревья получателей
/// директив по приказам сценария; `fronts` — Ставка и фронты по истории, армии и ниже — штабы-агенты; `journals` — то же
/// и задачи армий по журналам между распоряжениями фронта (подсказка: проверка армейских агентов и ядра);
/// `commanders` — как `agents` плюс командующие (`commander::enable`); `intent` — история как замысел (`intent::enable`,
/// подаёт сам — список пуст). Возвращает
/// директивы к подаче по часам (`feed`).
pub fn command_mode(sim: &mut Sim, mode: &str, side: crate::model::Side) -> Result<Vec<(u32, Directive)>, String> {
    match mode {
        "script" => Ok(Vec::new()),
        "agents" | "hybrid" => {
            if mode == "agents" { sim.command.follow_bands = true; }
            agents_side(sim, side);
            for (k, h) in sim.world.hqs.iter().enumerate() { if h.side == side && h.echelon == crate::model::Echelon::HighCommand { sim.command.control[k] = Control::Agent; } }
            Ok(historical_for(sim, side, None, mode == "hybrid"))
        }
        "fronts" | "journals" => Ok(front_historical(sim, side, mode == "journals")),
        // командующие: путь «агенты» плюс командующие у штабов с профилем; Гитлер — агент, его исторические
        // директивы после начала не подаются (остаются только готовые к началу)
        "commanders" => {
            sim.command.follow_bands = true;
            agents_side(sim, side);
            for (k, h) in sim.world.hqs.iter().enumerate() { if h.side == side && h.echelon == crate::model::Echelon::HighCommand { sim.command.control[k] = Control::Agent; } }
            crate::commander::enable(sim, side);
            let ds = historical_for(sim, side, None, false);
            Ok(if side == crate::model::Side::De { ds.into_iter().filter(|(_, d)| d.ready).collect() } else { ds })
        }
        // история как замысел: советская сторона — как «фронты по истории» (Ставка и фронты по приказам сценария, армии
        // и ниже — штабы-агенты), немецкие штабы — по приказам сценария; исторические директивы и приказы подаёт
        // цепочками intent::step (по часу или выполнению, пока имеют смысл); командующие — у обеих сторон
        "intent" => {
            sim.command.follow_bands = true;
            if side == crate::model::Side::Su { let _ = front_historical(sim, side, false); }
            crate::commander::enable(sim, side);
            crate::intent::enable(sim, side);
            Ok(Vec::new())
        }
        x => Err(format!("режим командования: script | agents | hybrid | fronts | journals | commanders | intent, а не {x}")),
    }
}

/// Подать директивы, срок которых наступил (до шага этого часа); в режиме `fronts` — с осью от места получателя.
pub fn feed(sim: &mut Sim, pending: &mut Vec<(u32, Directive)>, fronts: bool) {
    let now = sim.world.tick;
    let (due, rest): (Vec<_>, Vec<_>) = std::mem::take(pending).into_iter().partition(|(at, _)| *at <= now);
    *pending = rest;
    for (_, d) in due {
        let d = if fronts { with_axis(sim, d) } else { d };
        crate::command::passing::issue(sim, d, now);
    }
}

/// Прогон «фронты по истории»: верхняя инстанция и фронты стороны ведутся по приказам сценария (их собственные приказы
/// дивизиям — резервам фронта — исполняются), армии и ниже — штабы-агенты; подавать — исторические распоряжения фронтов
/// армиям: (час, директива), до начала операции — `ready`; `journals` — и задачи армий по журналам между ними.
pub fn front_historical(sim: &mut Sim, side: crate::model::Side, journals: bool) -> Vec<(u32, Directive)> {
    use crate::model::Echelon;
    for (k, h) in sim.world.hqs.iter().enumerate() {
        if h.side != side { continue; }
        sim.command.control[k] = if matches!(h.echelon, Echelon::HighCommand | Echelon::Front) { Control::Script } else { Control::Agent };
    }
    let start = sim.world.tick == 0;
    let w = &sim.world;
    // задачи армий по журналам (id «…:journal») — только в режиме «армии по журналам»
    sim.historical.iter().filter(|(_, d)| w.hqs[d.from as usize].side == side && w.hqs[d.from as usize].echelon == Echelon::Front && (journals || !d.id.ends_with(":journal")))
        .cloned().map(|(at, mut d)| { d.ready = at == 0 && start; (at, d) }).collect()
}

/// Исторические директивы верхней инстанции стороны (все или с id `only`): (час, директива) к подаче; до начала
/// операции — `ready`. В «гибриде» (`hybrid`) поддерево получателя переходит на приказы сценария, подавать нечего.
pub fn historical_for(sim: &mut Sim, side: crate::model::Side, only: Option<&str>, hybrid: bool) -> Vec<(u32, Directive)> {
    use crate::command::directive::Target;
    let Some(top) = sim.world.hqs.iter().position(|h| h.side == side && h.echelon == crate::model::Echelon::HighCommand) else { return Vec::new() };
    let ds: Vec<(u32, Directive)> = sim.historical.iter().filter(|(_, d)| d.from == top as u32 && only.is_none_or(|id| d.id == id)).cloned().collect();
    let start = sim.world.tick == 0;
    if !hybrid { return ds.into_iter().map(|(at, mut d)| { d.ready = at == 0 && start; (at, d) }).collect(); }
    for (_, d) in ds {
        let Target::Hq(h) = d.to else { continue };
        let w = &sim.world;
        let under = |mut k: usize| { for _ in 0..8 { if k == h as usize { return true; } match w.hqs[k].parent { Some(p) => k = p as usize, None => return false } } false };
        let sub: Vec<usize> = (0..w.hqs.len()).filter(|&k| under(k)).collect();
        for k in sub { sim.command.control[k] = Control::Script; }
    }
    Vec::new()
}

/// Распоряжение фронта без оси («армии — к такому-то району»): ось — от нынешнего места получателя к середине ближайшей
/// задачи, в час подачи (иначе оно не сменило бы прежний замысел армии с осью).
pub fn with_axis(sim: &Sim, mut d: Directive) -> Directive {
    if d.axis.is_empty() {
        if let Some(goal) = d.immediate.as_ref().and_then(|l| crate::command::agent::mid(&l.pts)) {
            let from = crate::command::agent::place(sim, d.to);
            if from.dist(goal) > 1.0 { d.axis = vec![from, goal]; }
        }
    }
    d
}

/// Корпус: полосы дивизиям (оборона), решения доктрины; отход — запрос наверх, до ответа — держаться.
pub fn corps(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    let subs = subs_of(sim, h);
    let divs: Vec<usize> = subs.iter().filter_map(|t| match t { Target::Division(i) => Some(*i as usize), _ => None }).collect();
    let tick = sim.world.tick;
    // общий приказ по полосе — только дивизиям без действующего решения доктрины (иначе приказы чередуются)
    let free: Vec<Target> = subs.iter().copied().filter(|t| match t { Target::Division(i) => tick >= sim.command.doc_until[*i as usize], _ => true }).collect();
    let mut out = generic(sim, h, intent, replan, &free, None);
    let dec = sim.doctrine_hq(&sim.world, tick, h as usize, &divs);
    let hold_h = sim.rules.command.de.permission_hours as u32;
    for o in dec.orders {
        let Some(&i) = o.to.first() else { continue };
        // действующее решение доктрины (сутки после него, до ответа на запрос об отходе — срок ответа) не перевыдаётся
        // тем же «держать / оборонять / выдвинуться» на каждые 2–3 км, на которые противник оттеснил дивизию;
        // контратака, прорыв и отход по разрешению — сразу
        if tick < sim.command.doc_until[i as usize] && matches!(o.kind, OrderKind::Defend | OrderKind::Hold | OrderKind::Move) { continue; }
        let active = tick < sim.command.doc_until[i as usize];
        if o.kind == OrderKind::Withdraw && active && sim.command.requests.iter().any(|r| r.hq == h && r.division == i && r.answer != Some(true)) { continue; }
        out.retain(|d| d.to != Target::Division(i));
        sim.command.doc_until[i as usize] = tick + 24;
        let at = o.target.unwrap_or(sim.world.divisions[i as usize].vars.pos);
        let here = sim.world.divisions[i as usize].vars.pos;
        if o.kind == OrderKind::Withdraw {
            match sim.command.requests.iter().find(|r| r.hq == h && r.division == i).map(|r| r.answer) {
                Some(Some(true)) => out.push(to_div(h, i, Task::Withdraw, sim.command.requests.iter().find(|r| r.hq == h && r.division == i).map_or(at, |r| r.at), Form::Instruction, "разрешение верхней инстанции на отход", &o.note, &format!("отход:{i}"))),
                // ждёт ответа или отказано — держаться на месте
                Some(_) => out.push(to_div(h, i, Task::Defend, here, Form::Instruction, "приказ от 21.01.1945: до разрешения — держать", &o.note, &format!("держать:{i}"))),
                None => {
                    out.push(to_div(h, i, Task::Defend, here, Form::Instruction, "приказ от 21.01.1945: до разрешения — держать", &o.note, &format!("держать:{i}")));
                    sim.command.doc_until[i as usize] = tick + hold_h;
                    sim.command.requests.push(Request { hq: h, tick, division: i, at, answer: None, answered_at: 0 });
                    let name = sim.world.divisions[i as usize].name.clone();
                    sim.documents.push(Document { tick, hq: h, kind: DocKind::Report, to: Vec::new(), text: format!("запрос на отход: {name} — {}; до ответа — держаться", o.note), rule: Some("приказ от 21.01.1945: о каждом отходе — доклад заранее".into()) });
                }
            }
            continue;
        }
        let task = match o.kind { OrderKind::Attack => Task::Attack, OrderKind::Move => Task::Move, _ => Task::Defend };
        out.push(to_div(h, i, task, at, Form::Instruction, "доктрина обороны (TM-E 30-451, DA Pam 20-233)", &o.note, &format!("доктрина:{i}")));
    }
    out
}

/// Решение немецкого штаба по замыслу старшего.
pub fn plan(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    match sim.world.hqs[h as usize].echelon {
        Echelon::Corps => corps(sim, h, intent, replan),
        _ => generic(sim, h, intent, replan, &subs_of(sim, h), None),
    }
}

fn to_div(h: u32, i: u32, task: Task, at: crate::geo::XY, form: Form, rule: &str, note: &str, id: &str) -> Directive {
    Directive {
        id: id.into(), from: h, to: Target::Division(i), form, task, axis: Vec::new(), immediate: Some(Line { pts: vec![at], by: None }), subsequent: None,
        boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(), junction: None, hasty: form == Form::Instruction, ready: false,
        rule: Some(rule.into()), issued: 0, note: note.into(),
    }
}

/// Ход часа немецкой армии: оттяжка перед артподготовкой — противник развёртывается у её полосы; один раз на угрозу.
pub fn watch(sim: &mut Sim, h: u32) -> Vec<Directive> {
    let tick = sim.world.tick;
    let r = sim.rules.command.de.clone();
    let near = sim.rules.contact_km + 6.0;
    let w = &sim.world;
    let under = |mut k: u32| { for _ in 0..8 { if k == h { return true; } match w.hqs[k as usize].parent { Some(p) => k = p, None => return false } } false };
    let own: Vec<usize> = (0..w.divisions.len()).filter(|&i| { let d = &w.divisions[i]; under(d.hq) && !d.state.out() && d.state != State::Remnant }).collect();
    let deploying: Vec<usize> = (0..w.divisions.len()).filter(|&j| { let e = &w.divisions[j]; e.side != w.hqs[h as usize].side && matches!(e.state, State::Deploy { .. }) && own.iter().any(|&i| w.divisions[i].vars.pos.dist(e.vars.pos) <= near) }).collect();
    if !deploying.is_empty() { sim.command.pull_seen[h as usize] = tick; }
    // снова — только после затишья 48 ч подряд (иначе в ходе наступления отход каждые сутки)
    if let Some(t) = sim.command.pulled[h as usize] { if tick >= t + 48 && tick >= sim.command.pull_seen[h as usize] + 48 { sim.command.pulled[h as usize] = None; } return Vec::new(); }
    if (deploying.len() as f64) < r.attack_sign_divisions { return Vec::new(); }
    sim.command.pulled[h as usize] = Some(tick);
    let first: Vec<usize> = own.iter().copied().filter(|&i| deploying.iter().any(|&j| w.divisions[i].vars.pos.dist(w.divisions[j].vars.pos) <= near)).collect();
    let out: Vec<Directive> = first.iter().map(|&i| {
        let at = sim.behind(&sim.world, i, r.pullback_km);
        to_div(h, i as u32, Task::Withdraw, at, Form::Instruction, "DA Pam 20-201: оттяжка с первой позиции перед артподготовкой", &format!("противник развёртывается для атаки ({} дивизий) — передний край к главной позиции", deploying.len()), &format!("оттяжка:{i}"))
    }).collect();
    out
}

pub struct Directive {
    pub id: String,
    /// Отдающий штаб.
    pub from: u32,
    pub to: Target,
    pub form: Form,
    pub task: Task,
    /// Ось главного удара (может быть пустой).
    pub axis: Vec<XY>,
    pub immediate: Option<Line>,
    pub subsequent: Option<Line>,
    /// Разграничительные линии: сосед (штаб) и ломаная.
    pub boundaries: Vec<(Option<u32>, Vec<XY>)>,
    /// Подчинённые на главном ударе.
    pub main_blow: Vec<u32>,
    pub reserve: Vec<u32>,
    /// Кто отвечает за стык.
    pub junction: Option<u32>,
    /// По пути хотя бы одна ступень прошла распоряжением.
    pub hasty: bool,
    /// Отдана до начала операции: доходит и доводится до дивизий сразу (как приказы сценария на начало).
    pub ready: bool,
    /// Правило, по которому штаб принял решение (статья устава или id норматива) — в документ.
    pub rule: Option<String>,
    /// Час отдачи (ставит passing::issue): пришедшая позже, но отданная раньше директива того же штаба не действует.
    pub issued: u32,
    pub note: String,
}

/// Директивы по получателям, с часом вступления: `hour` — час операции по дате, `xy` — проекция театра.
pub fn resolve(&self, hqs: &HashMap<&str, u32>, hour: &dyn Fn(&str) -> Option<u32>, xy: &dyn Fn(LngLat) -> XY) -> Result<Vec<(u32, Directive)>, String> {
    let h = |id: &str| hqs.get(id).copied().ok_or_else(|| format!("директива {}: нет штаба {id}", self.id));
    let at = hour(&self.at).ok_or_else(|| format!("директива {}: неверная дата {}", self.id, self.at))?;
    let line = |l: &Option<LineIn>| l.as_ref().filter(|l| !l.line.is_empty()).map(|l| Line { pts: l.line.iter().map(|&p| xy(p)).collect(), by: l.by.as_deref().and_then(hour) });
    let from = h(&self.from)?;
    let boundaries = self.boundaries.iter().map(|b| Ok((match &b.with { Some(w) => Some(h(w)?), None => None }, b.line.iter().map(|&p| xy(p)).collect()))).collect::<Result<Vec<_>, String>>()?;
    let main_blow = self.main_blow.iter().map(|x| h(x)).collect::<Result<Vec<_>, _>>()?;
    let reserve = self.reserves.iter().map(|x| h(x)).collect::<Result<Vec<_>, _>>()?;
    self.to.iter().map(|t| Ok((at, Directive {
        id: self.id.clone(), from, to: Target::Hq(h(t)?), form: self.form, task: self.task,
        axis: self.axis.iter().map(|&p| xy(p)).collect(), immediate: line(&self.immediate), subsequent: line(&self.subsequent),
        boundaries: boundaries.clone(), main_blow: main_blow.clone(), reserve: reserve.clone(), junction: None, hasty: false, ready: false, rule: None, issued: 0, note: self.note.clone(),
    }))).collect()
}

/// Форма документа: подготовленный приказ (директива, боевой приказ) или боевое распоряжение — быстрее, но со
/// штрафом слаженности.
pub enum Form { Order, #[default] Instruction }

/// Текст документа: задача и рубежи.
pub fn describe(sim: &Sim, d: &Directive) -> String {
    let task = match d.task {
        crate::command::directive::Task::Attack => "наступать", crate::command::directive::Task::Defend => "оборонять",
        crate::command::directive::Task::Delay => "сдерживать", crate::command::directive::Task::Withdraw => "отходить",
        crate::command::directive::Task::Move => "выдвигаться", crate::command::directive::Task::Reserve => "в резерв",
    };
    let at = |l: &Option<crate::command::directive::Line>| l.as_ref().and_then(|l| l.pts.first()).map(|p| {
        let q = sim.theatre.proj.to_lnglat(*p);
        format!("{:.2}, {:.2}", q[1], q[0])
    });
    let mut s = format!("{task}");
    if let Some(p) = at(&d.immediate) { s += &format!("; ближайшая задача — рубеж у {p}"); }
    if let Some(p) = at(&d.subsequent) { s += &format!("; последующая — у {p}"); }
    if !d.note.is_empty() { s += &format!(" ({})", d.note); }
    s
}

/// Отдать директиву: в пути до часа прибытия; документ — директива (верхняя инстанция, фронт), боевой приказ (армия,
/// корпус) или распоряжение.
pub fn issue(sim: &mut Sim, mut d: Directive, tick: u32) {
    let to = match d.to { Target::Hq(h) => Some(sim.world.hqs[h as usize].echelon), Target::Division(_) => None };
    d.hasty |= d.form == Form::Instruction;
    d.issued = tick;
    let arrives = if d.ready { tick } else { tick + passing_hours(&sim.rules.command, to, d.form).round() as u32 };
    let kind = match (d.form, sim.world.hqs[d.from as usize].echelon) {
        (Form::Instruction, _) => DocKind::Instruction,
        (_, Echelon::HighCommand | Echelon::Front) => DocKind::Directive,
        _ => DocKind::Order,
    };
    let text = describe(sim, &d);
    sim.documents.push(Document { tick, hq: d.from, kind, to: vec![target_id(sim, d.to)], text, rule: d.rule.clone() });
    sim.command.in_transit.push((arrives, d));
}

/// Часы на ступень получателя: штаб (по ступени) или дивизия (`None`).
pub fn passing_hours(c: &Command, to: Option<Echelon>, form: Form) -> f64 {
    let i = match to { Some(Echelon::HighCommand | Echelon::Front) => 0, Some(Echelon::Army) => 1, Some(Echelon::Corps) => 2, None => 3 };
    match form { Form::Order => c.prepared_h[i], Form::Instruction => c.instruction_h[i] }
}

/// Название получателя (id штаба или дивизии).
pub fn target_id(sim: &Sim, t: Target) -> String {
    match t { Target::Hq(h) => sim.world.hqs[h as usize].id.clone(), Target::Division(i) => sim.world.divisions[i as usize].id.clone() }
}

/// Армия: эшелоны корпусов; дивизии и бригады прямо под армией — с ближайшим корпусом первого эшелона.
pub fn army(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    let subs = subs_of(sim, h);
    let corps: Vec<Target> = subs.iter().copied().filter(|t| matches!(t, Target::Hq(_))).collect();
    let direct: Vec<Target> = subs.iter().copied().filter(|t| matches!(t, Target::Division(_))).collect();
    if corps.is_empty() { return echelons(sim, h, intent, replan, &direct, true, "дивизия"); }
    let mut out = echelons(sim, h, intent, replan, &corps, false, "корпус");
    // приданные: директива ближайшего корпуса линии боя
    let line: Vec<(XY, Directive)> = out.iter().filter(|d| d.task != Task::Move).filter_map(|d| match d.to { Target::Hq(_) => Some((place(sim, d.to), d.clone())), _ => None }).collect();
    for t in direct {
        let p = place(sim, t);
        if let Some((_, d)) = line.iter().min_by(|a, b| a.0.dist(p).total_cmp(&b.0.dist(p))) {
            let mut d = d.clone();
            d.to = t;
            d.rule = Some("приказ НКО №306: танки и части усиления — дивизиям первого эшелона".into());
            out.push(d);
        }
    }
    out
}

/// Фронт: стрелковые армии — главный удар уже, вспомогательные шире; танковые армии — подвижная группа до прорыва.
/// Ввод подвижной группы `t`: роль «введена»; в ближайшем распределении полосы фронта ей — задача на глубину
/// (ближайшая задача — последующая задача фронта) с правилом `rule`. Общий путь штаба фронта и командующего.
pub fn commit_mobile(sim: &mut Sim, t: Target, rule: String) {
    sim.command.set_role(t, Role::Committed);
    sim.command.commits.retain(|c| c.0 != t);
    sim.command.commits.push((t, rule));
}

/// Корпус: эшелоны дивизий.
pub fn corps(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    let units = subs_of(sim, h);
    if units.is_empty() { return Vec::new(); }
    echelons(sim, h, intent, replan, &units, true, "дивизия")
}

/// Дивизии поддерева штаба (действующие).
fn divs_under(sim: &Sim, h: u32) -> Vec<usize> {
    let w = &sim.world;
    (0..w.divisions.len()).filter(|&i| {
        let d = &w.divisions[i];
        if d.state.out() || d.state == State::Remnant { return false; }
        let mut k = d.hq;
        for _ in 0..8 { if k == h { return true; } match w.hqs[k as usize].parent { Some(p) => k = p, None => return false } }
        false
    }).collect()
}

/// Два эшелона из подчинённых `units`: распределение (один раз), ввод второго эшелона, полосы линии боя, направление
/// второму эшелону. `cap_by_band` — первый эшелон не шире участка прорыва на подчинённого (корпус).
fn echelons(sim: &mut Sim, h: u32, intent: &Directive, replan: bool, units: &[Target], cap_by_band: bool, unit_name: &str) -> Vec<Directive> {
    let all = subs_of(sim, h);
    let fr = frame(sim, h, intent, &all);
    let width = fr.band.left[0].dist(fr.band.right[0]);
    let tick = sim.world.tick;
    let side = sim.world.hqs[h as usize].side;
    let (share, depth, fallback) = (sim.rules.doctrine_su.first_echelon_share, sim.rules.doctrine_su.commit_depth_km, sim.rules.doctrine_su.second_echelon_fallback_hours);
    let su = sim.rules.command.su.clone();
    let unset: Vec<Target> = units.iter().copied().filter(|&t| sim.command.role(t) == Role::Unset).collect();
    if !unset.is_empty() {
        // танки непосредственной поддержки — с первым эшелоном; остальные — ближние к противнику в первый
        let (npp, mut rest): (Vec<Target>, Vec<Target>) = unset.iter().partition(|&&t| matches!(t, Target::Division(_)) && is_mobile(sim, t));
        rest.sort_by(|&a, &b| enemy_km_at(sim, place(sim, a), side).total_cmp(&enemy_km_at(sim, place(sim, b), side)));
        // «две трети» записаны 0,667: 3 · 0,667 = 2,001 — округление с допуском
        let by_share = ((rest.len() as f64) * share - 1e-2).ceil() as usize;
        let by_band = if cap_by_band { ((width / su.division_band_km).floor() as usize).max(1) } else { usize::MAX };
        let n1 = by_share.min(by_band).max(1).min(rest.len().max(1));
        for &t in &npp { sim.command.set_role(t, Role::First); }
        for (k, &t) in rest.iter().enumerate() { sim.command.set_role(t, if k < n1 { Role::First } else { Role::Second }); }
        for &t in &unset { let p = place(sim, t); sim.command.mark(t, p, tick); }
    }
    let first: Vec<Target> = units.iter().copied().filter(|&t| sim.command.role(t) == Role::First).collect();
    let mut second: Vec<Target> = units.iter().copied().filter(|&t| sim.command.role(t) == Role::Second).collect();
    let mut why: Option<String> = None;
    if !second.is_empty() {
        let mean = if first.is_empty() { depth } else { first.iter().map(|&t| advance(sim.command.start(t), place(sim, t), &fr.axis)).sum::<f64>() / first.len() as f64 };
        let waited = second.iter().map(|&t| tick.saturating_sub(sim.command.since(t))).min().unwrap_or(0) as f64;
        if mean >= depth || waited >= fallback {
            for &t in &second { sim.command.set_role(t, Role::Committed); }
            why = Some(if first.is_empty() { format!("первый эшелон {unit_name} выбыл — ввод второго эшелона") }
                else if mean >= depth { format!("первый эшелон продвинулся на {mean:.1} км — главная полоса прорвана, ввод второго эшелона (depth-objectives-1944-norm)") }
                else { format!("{waited:.0} ч в ожидании — ввод второго эшелона на 2–3-й день (stop-second-echelon-commit-day2)") });
            second.clear();
        } else {
            for &t in &first {
                if !stalled(sim, t) || sim.command.replaced_of(t) || second.is_empty() { continue; }
                let p = place(sim, t);
                let k = (0..second.len()).min_by(|&a, &b| place(sim, second[a]).dist(p).total_cmp(&place(sim, second[b]).dist(p))).unwrap();
                let j = second.remove(k);
                sim.command.set_replaced(t);
                sim.command.set_role(j, Role::Committed);
                why = Some(format!("{unit_name} первого эшелона остановился — смена вторым эшелоном (приказ НКО №306: на смену, а не на усиление)"));
            }
        }
    }
    let line: Vec<Target> = units.iter().copied().filter(|&t| matches!(sim.command.role(t), Role::First | Role::Committed) && !sim.command.replaced_of(t)).collect();
    let mut out = generic(sim, h, intent, replan, &line, None);
    if let Some(r) = why { for d in out.iter_mut() { d.rule = Some(r.clone()); } }
    // второй эшелон и сменённые — за центром линии боя по оси, через 1 км поперёк
    let rest: Vec<Target> = units.iter().copied().filter(|&t| sim.command.role(t) == Role::Second || sim.command.replaced_of(t)).collect();
    if let Some(c) = mid(&line.iter().map(|&t| place(sim, t)).collect::<Vec<_>>()) {
        let n = XY::new(-fr.dir.y, fr.dir.x);
        for (k, &t) in rest.iter().enumerate() {
            let off = k as f64 - (rest.len() as f64 - 1.0) / 2.0;
            let at = XY::new(c.x - fr.dir.x * su.second_echelon_behind_km + n.x * off, c.y - fr.dir.y * su.second_echelon_behind_km + n.y * off);
            out.push(follow(sim, h, intent, replan, t, at, "ПУ-39 ст. 103: второму эшелону — только направление", &format!("второй эшелон: за первым ({unit_name})")));
        }
    }
    out
}

pub fn enemy_km_at(sim: &Sim, p: XY, side: crate::model::Side) -> f64 {
    sim.world.divisions.iter().filter(|e| e.side != side && !e.state.out()).map(|e| e.vars.pos.dist(p)).fold(f64::INFINITY, f64::min)
}

/// Директива «выдвигаться к точке» без полосы — второму эшелону и подвижной группе.
fn follow(sim: &Sim, h: u32, intent: &Directive, replan: bool, to: Target, at: XY, rule: &str, note: &str) -> Directive {
    let id = match to { Target::Hq(k) => sim.world.hqs[k as usize].id.clone(), Target::Division(i) => sim.world.divisions[i as usize].id.clone() };
    Directive {
        id: format!("{}>{id}:за", intent.id), from: h, to, form: intent.form, task: Task::Move, axis: intent.axis.clone(),
        immediate: Some(Line { pts: vec![at], by: None }), subsequent: None, boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(),
        junction: None, hasty: intent.hasty, ready: intent.ready && !replan, rule: Some(rule.into()), issued: 0, note: note.into(),
    }
}

pub fn front(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    let subs = subs_of(sim, h);
    let tick = sim.world.tick;
    let (tank_depth, tank_fallback) = (sim.rules.doctrine_su.tank_commit_depth_km, sim.rules.doctrine_su.tank_commit_fallback_hours);
    let share = sim.rules.command.su.main_blow_share;
    let fr = frame(sim, h, intent, &subs);
    for &t in &subs {
        if sim.command.role(t) == Role::Unset {
            let r = if matches!(t, Target::Hq(_)) && is_mobile(sim, t) { Role::Mobile } else { Role::First };
            sim.command.set_role(t, r);
            let p = place(sim, t);
            sim.command.mark(t, p, tick);
        }
    }
    let rifle: Vec<Target> = subs.iter().copied().filter(|&t| sim.command.role(t) != Role::Mobile && sim.command.role(t) != Role::Committed).collect();
    // главный удар: названные в замысле, иначе ближайшие к оси
    let base = fr.axis.first().copied().unwrap_or_default();
    let off = |p: XY| (-fr.dir.y * (p.x - base.x) + fr.dir.x * (p.y - base.y)).abs();
    let mut by_axis = rifle.clone();
    by_axis.sort_by(|&a, &b| off(place(sim, a)).total_cmp(&off(place(sim, b))));
    let named: Vec<Target> = rifle.iter().copied().filter(|t| matches!(t, Target::Hq(x) if intent.main_blow.contains(x))).collect();
    let main: Vec<Target> = if named.is_empty() { by_axis.iter().copied().take(((rifle.len() as f64) * share).ceil() as usize).collect() } else { named };
    // ввод подвижной группы: армии главного удара продвинулись на глубину тактической зоны или срок
    let mean = if main.is_empty() { tank_depth } else { main.iter().map(|&t| advance(sim.command.start(t), place(sim, t), &fr.axis)).sum::<f64>() / main.len() as f64 };
    let mobiles: Vec<Target> = subs.iter().copied().filter(|&t| sim.command.role(t) == Role::Mobile).collect();
    // у фронта с командующим ввод — его решение (по глубине и сроку штаб не вводит)
    if !crate::commander::active(sim, h) {
        for &t in &mobiles {
            let waited = tick.saturating_sub(sim.command.since(t)) as f64;
            if mean >= tank_depth || waited >= tank_fallback {
                let rule = if mean >= tank_depth { format!("армии главного удара продвинулись на {mean:.1} км — тактическая зона прорвана, ввод подвижной группы (приказ НКО №325)") }
                    else { format!("за {waited:.0} ч тактическая зона не прорвана — ввод подвижной группы для завершения прорыва (приказ НКО №325)") };
                commit_mobile(sim, t, rule);
            }
        }
    }
    let line: Vec<Target> = subs.iter().copied().filter(|&t| sim.command.role(t) != Role::Mobile).collect();
    let weights: Vec<f64> = line.iter().map(|t| if main.contains(t) || sim.command.role(*t) == Role::Committed { 1.0 } else { 2.0 }).collect();
    let mut out = generic(sim, h, intent, replan, &line, Some(&weights));
    for d in out.iter_mut() {
        if let Some(k) = sim.command.commits.iter().position(|c| c.0 == d.to) {
            // введённой подвижной группе — на глубину: ближайшая задача — последующая задача фронта
            let (_, rule) = sim.command.commits.remove(k);
            if let Some(s) = d.subsequent.clone() { d.immediate = Some(s); }
            d.rule = Some(rule);
        }
    }
    sim.command.commits.retain(|c| !subs.contains(&c.0));
    // подвижные группы до ввода — за главным ударом в 10 км
    if let Some(c) = mid(&main.iter().map(|&t| place(sim, t)).collect::<Vec<_>>()) {
        let at = XY::new(c.x - fr.dir.x * 10.0, c.y - fr.dir.y * 10.0);
        for t in subs.iter().copied().filter(|&t| sim.command.role(t) == Role::Mobile) {
            out.push(follow(sim, h, intent, replan, t, at, "приказ НКО №325: танковые и механизированные корпуса — эшелон развития успеха, ввод после прорыва главной полосы", "подвижная группа фронта: ждёт прорыва тактической зоны"));
        }
    }
    out
}

/// Подвижна ли часть или штаб (больше половины дивизий поддерева подвижные).
fn is_mobile(sim: &Sim, t: Target) -> bool {
    match t {
        Target::Division(i) => mobile(&sim.world.divisions[i as usize].params.kind),
        Target::Hq(h) => { let ds = divs_under(sim, h); !ds.is_empty() && ds.iter().filter(|&&i| mobile(&sim.world.divisions[i].params.kind)).count() * 2 > ds.len() }
    }
}

/// Решение советского штаба по замыслу старшего.
pub fn plan(sim: &mut Sim, h: u32, intent: &Directive, replan: bool) -> Vec<Directive> {
    match (sim.world.hqs[h as usize].echelon, intent.task) {
        (Echelon::Corps, Task::Attack) => corps(sim, h, intent, replan),
        (Echelon::Army, Task::Attack) => army(sim, h, intent, replan),
        (Echelon::Front, Task::Attack) => front(sim, h, intent, replan),
        _ => generic(sim, h, intent, replan, &subs_of(sim, h), None),
    }
}

/// Остановился: все его дивизии в обороне рядом с противником.
fn stalled(sim: &Sim, t: Target) -> bool {
    let ds = match t { Target::Division(i) => vec![i as usize], Target::Hq(h) => divs_under(sim, h) };
    let contact = sim.rules.contact_km + 4.0;
    !ds.is_empty() && ds.iter().all(|&i| { let d = &sim.world.divisions[i]; matches!(d.state, State::Defense(_)) && enemy_km_at(sim, d.vars.pos, d.side) <= contact })
}

/// Исполнить решение `k` командующего `c` (последнее в `c.decisions`).
pub fn apply(sim: &mut Sim, c: &Commander, k: &Kind, tick: u32) {
    let mut to: Vec<String> = Vec::new();
    match k {
        Kind::Continue | Kind::WaitMobile | Kind::Hold | Kind::ShiftForces { .. } => {}
        Kind::CommitMobile { hq } => {
            // тот же путь, что у штаба фронта: задача на глубину в ближайшем распределении полосы
            let d = c.decisions.last().expect("решение");
            let rule = format!("{}; {}", d.options[d.chosen].choice.label, d.options[d.chosen].choice.rule);
            crate::command::su::commit_mobile(sim, Target::Hq(*hq), rule);
            // штаб фронта распределяет полосу заново в этот же час — с введённой группой
            sim.command.fresh[c.hq as usize] = true;
            to.push(sim.world.hqs[*hq as usize].id.clone());
        }
        Kind::ShiftMainBlow { to: armies } => {
            // своему штабу: прежний замысел с новым главным ударом
            if let Some(mut d) = sim.command.intent[c.hq as usize].clone() {
                let dec = c.decisions.last().expect("решение");
                let ch = &dec.options[dec.chosen].choice;
                d.id = format!("командующий:{}:{tick}", sim.world.hqs[c.hq as usize].id);
                d.from = c.hq;
                d.to = Target::Hq(c.hq);
                d.form = Form::Order;
                d.main_blow = armies.clone();
                d.ready = true;
                d.rule = Some(ch.rule.to_string());
                d.note = ch.label.clone();
                issue(sim, d, tick);
                to.extend(armies.iter().map(|&a| sim.world.hqs[a as usize].id.clone()));
            }
        }
        Kind::TurnToRival { hq, at } => to_army(sim, c, *hq, Task::Attack, *at, tick, &mut to),
        Kind::Encircle { pocket } => {
            if let Some(p) = c.picture.as_ref().and_then(|pic| pic.pockets.get(*pocket)).cloned() {
                // в «истории как замысле» — только армии вне истории (прочие идут по своим цепочкам)
                let mine = |h: u32| !super::decide::for_strayed(sim, c.hq) || crate::intent::off_history(sim, h);
                let own: Vec<u32> = c.picture.as_ref().map(|pic| pic.armies.iter().map(|a| a.hq).filter(|&h| p.by.contains(&h) && mine(h)).collect()).unwrap_or_default();
                for a in own { to_army(sim, c, a, Task::Attack, p.center, tick, &mut to); }
            }
        }
        Kind::CommitSecond { hq } => {
            sim.command.role_hq[*hq as usize] = crate::command::control::Role::Committed;
            match intent_goal(sim, c.hq) {
                Some(goal) => to_army(sim, c, *hq, Task::Attack, goal, tick, &mut to),
                None => sim.command.fresh[c.hq as usize] = true,
            }
        }
        Kind::Withdraw { hq } => {
            if let Some(&(_, at)) = c.withdraw_at.iter().find(|x| x.0 == *hq) {
                let ds = front_line(sim, *hq);
                raise(sim, &ds, Task::Withdraw, at, tick, &mut to);
            }
        }
        Kind::Breakout { toward } => {
            // отрезанные дивизии командующего (армии или группы армий) — прорываться по разрешению
            let ds: Vec<usize> = divisions_of(sim, c.hq).into_iter().filter(|&i| sim.world.divisions[i].cut_since.is_some()).collect();
            raise(sim, &ds, Task::Attack, *toward, tick, &mut to);
        }
        Kind::Counterattack { from, at } => to_reserve(sim, c, *from, Task::Attack, *at, tick, &mut to),
        Kind::MoveReserve { hq, to: at } => to_reserve(sim, c, *hq, Task::Move, *at, tick, &mut to),
        // армии вне истории — частная директива фронта: наступать к точке (ось — от места армии, как `with_axis`)
        Kind::Assign { army, at, defend: true, .. } => {
            // оборона на месте (точка — у самой армии): ось — прежняя ось армии (фронт обороны), иначе директива без
            // оси не сменила бы её замысел с осью (agent.rs)
            let mut d = directive(sim, c, Target::Hq(*army), Task::Defend, *at, tick);
            if d.axis.is_empty() { d.axis = sim.command.intent[*army as usize].as_ref().map(|i| i.axis.clone()).unwrap_or_default(); }
            if *army != c.hq { sim.command.named_hq[*army as usize] = true; }
            to.push(target_id(sim, d.to));
            issue(sim, d, tick);
        }
        Kind::Assign { army, at, .. } => to_army(sim, c, *army, Task::Attack, *at, tick, &mut to),
        Kind::Relief { army, by, toward } => {
            if by != army { to_army(sim, c, *by, Task::Attack, *toward, tick, &mut to); }
        }
        Kind::Permit { request } | Kind::Forbid { request } => {
            if let Some(r) = sim.command.requests.get_mut(*request) {
                r.answer = Some(matches!(k, Kind::Permit { .. }));
                r.answered_at = tick;
                let h = r.hq;
                to.push(sim.world.hqs[h as usize].id.clone());
            }
  // … строки 202–205

/// Директива командующего получателю `to`: задача к точке `goal` (ось — от нынешнего места получателя).
/// Себе — сразу (решение в своём штабе), подчинённым — боевым распоряжением со временем прохождения.
fn directive(sim: &Sim, c: &Commander, to: Target, task: Task, goal: XY, tick: u32) -> Directive {
    let d = c.decisions.last().expect("решение");
    let ch = &d.options[d.chosen].choice;
    let from = place(sim, to);
    Directive {
        id: format!("командующий:{}:{tick}", sim.world.hqs[c.hq as usize].id), from: c.hq, to, form: Form::Instruction, task,
        axis: if from.dist(goal) > 1.0 { vec![from, goal] } else { Vec::new() },
        immediate: Some(Line { pts: vec![goal], by: None }), subsequent: None, boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(),
        junction: None, hasty: false, ready: to == Target::Hq(c.hq), rule: Some(ch.rule.to_string()), issued: 0, note: ch.label.clone(),
    }
}

/// Исполнить разрешённые запросы командующих: распоряжение дивизии от её штаба (отход или прорыв к точке запроса);
/// запрещённые и снятые — забыть, ждущие — оставить.
pub fn execute_permitted(sim: &mut Sim, tick: u32) {
    let raised = std::mem::take(&mut sim.commanders.raised);
    for r in raised {
        let answer = sim.command.requests.iter().find(|q| q.hq == r.hq && q.division == r.division && q.tick == r.tick).map(|q| q.answer);
        match answer {
            Some(None) => sim.commanders.raised.push(r),
            Some(Some(true)) => {
                let i = r.division as usize;
                let from = sim.world.divisions[i].vars.pos;
                let note = if r.task == Task::Withdraw { "отход по разрешению верхней инстанции" } else { "прорыв из окружения по разрешению верхней инстанции" };
                let d = Directive {
                    id: format!("разрешено:{i}:{}", r.tick), from: r.hq, to: Target::Division(r.division), form: Form::Instruction, task: r.task,
                    axis: if from.dist(r.at) > 1.0 { vec![from, r.at] } else { Vec::new() }, immediate: Some(Line { pts: vec![r.at], by: None }), subsequent: None,
                    boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(), junction: None, hasty: true, ready: false,
                    rule: Some("разрешение верхней инстанции на отход".into()), issued: 0, note: note.into(),
                };
                // решение доктрины корпуса сутки его не перебивает
                if let Some(u) = sim.command.doc_until.get_mut(i) { *u = tick + 24; }
                issue(sim, d, tick);
            }
            _ => {}
        }
    }
}

/// Дивизии первой линии армии: в бою или с противником в пределах соприкосновения; нет таких — все.
fn front_line(sim: &Sim, army: u32) -> Vec<usize> {
    let all = divisions_of(sim, army);
    let side = sim.world.hqs[army as usize].side;
    let contact = sim.rules.contact_km;
    let near = |i: usize| sim.world.engaged.get(i).copied().unwrap_or(false)
        || sim.world.divisions.iter().any(|e| e.side != side && !e.state.out() && e.vars.pos.dist(sim.world.divisions[i].vars.pos) <= contact);
    let first: Vec<usize> = all.iter().copied().filter(|&i| near(i)).collect();
    if first.is_empty() { all } else { first }
}

/// Цель задачи штаба по замыслу старшего: середина ближайшей задачи, иначе конец оси.
fn intent_goal(sim: &Sim, hq: u32) -> Option<XY> {
    let d = sim.command.intent.get(hq as usize)?.as_ref()?;
    d.immediate.as_ref().and_then(|l| crate::command::agent::mid(&l.pts)).or_else(|| d.axis.last().copied())
}

/// Запросы верхней инстанции за дивизии `ds`: задача `task` к точке `at`, исполнение — по разрешению. Дивизия,
/// за которую запрос уже есть, второй раз не запрашивается.
fn raise(sim: &mut Sim, ds: &[usize], task: Task, at: XY, tick: u32, to: &mut Vec<String>) {
    for &i in ds {
        if sim.command.requests.iter().any(|r| r.division == i as u32) { continue; }
        let hq = sim.world.divisions[i].hq;
        sim.command.requests.push(Request { hq, tick, division: i as u32, at, answer: None, answered_at: 0 });
        sim.commanders.raised.push(Raised { hq, division: i as u32, tick, task, at });
        let id = sim.world.hqs[hq as usize].id.clone();
        if !to.contains(&id) { to.push(id); }
    }
}

/// Рубеж в глубине: от центра войск армии прочь от ближайшего противника.
pub fn rear_of(sim: &Sim, army: u32) -> Option<XY> {
    let c = place(sim, Target::Hq(army));
    let side = sim.world.hqs[army as usize].side;
    let e = sim.world.divisions.iter().filter(|d| d.side != side && !d.state.out()).map(|d| d.vars.pos).min_by(|a, b| a.dist(c).total_cmp(&b.dist(c)))?;
    let d = c.dist(e);
    if d < 1e-9 { return None; }
    Some(XY::new(c.x - (e.x - c.x) / d * WITHDRAW_KM, c.y - (e.y - c.y) / d * WITHDRAW_KM))
}

/// Документ последнего решения командующего `c` (извещение получателям `to`) с обоснованием и правилом.
pub fn record(sim: &mut Sim, c: &Commander, tick: u32, to: Vec<String>) {
    let d = c.decisions.last().expect("решение");
    let ch = &d.options[d.chosen].choice;
    let text = format!("{DOC_PREFIX}: {}. Повод: {}. {}", ch.label, d.trigger, d.why);
    sim.documents.push(Document { tick, hq: c.hq, kind: DocKind::Notice, to, text, rule: Some(ch.rule.to_string()) });
}

/// Частная директива армии через голову своего штаба (или себе).
fn to_army(sim: &mut Sim, c: &Commander, army: u32, task: Task, goal: XY, tick: u32, to: &mut Vec<String>) {
    let d = directive(sim, c, Target::Hq(army), task, goal, tick);
    if army != c.hq { sim.command.named_hq[army as usize] = true; }
    to.push(target_id(sim, d.to));
    issue(sim, d, tick);
}

/// Распоряжения дивизиям резерва штаба `h` (не отрезанным): задача к точке `goal`.
fn to_reserve(sim: &mut Sim, c: &Commander, h: u32, task: Task, goal: XY, tick: u32, to: &mut Vec<String>) {
    let ds: Vec<usize> = divisions_of(sim, h).into_iter().filter(|&i| sim.world.divisions[i].state == State::Reserve && sim.world.divisions[i].cut_since.is_none()).collect();
    for i in ds {
        let d = directive(sim, c, Target::Division(i as u32), task, goal, tick);
        to.push(target_id(sim, d.to));
        issue(sim, d, tick);
    }
}

pub struct Commander {
    pub hq: u32,
    /// Номер профиля в `rules.commanders.profiles`.
    pub profile: usize,
    /// Мотивы по последней картине.
    pub motives: Motives,
    pub mood: Mood,
    /// Действующее решение.
    pub intent: Option<Kind>,
    /// Подпись действующего решения.
    pub intent_label: Option<String>,
    /// Час последнего решения (или включения).
    pub last: u32,
    pub snapshots: Vec<Snapshot>,
    pub decisions: Vec<Decision>,
    /// Картина последнего часа: в этом часе — текущая; в следующем — прежняя для шага состояния (ровно на час старше).
    pub picture: Option<Picture>,
    pub seen: Seen,
    /// Рубеж отхода армии, пока действующее решение — её отход (не пересчитывается на каждом решении).
    pub withdraw_at: Vec<(u32, crate::geo::XY)>,
    /// Центр котла, который замыкает действующее решение «замкнуть кольцо» (котёл опознаётся по месту, не по номеру).
    pub encircle_at: Option<crate::geo::XY>,
}

/// Решение: когда, по какому поводу, все варианты с оценками, выбранный и обоснование.
pub struct Decision {
    pub tick: u32,
    pub trigger: String,
    pub options: Vec<Scored>,
    pub chosen: usize,
    pub why: String,
}

/// Вариант с оценкой: слагаемые по мотивам (мотив × вклад), штраф (неопределённость и потери), прибавка
/// (продолжение и послушание), итог, результат проигрыша «в уме» (если был).
pub struct Scored {
    pub choice: Choice,
    pub parts: Motives,
    pub penalty: f64,
    pub bonus: f64,
    pub total: f64,
    pub mind: Option<MindResult>,
}

/// Что командующий уже видел: директива старшего, число отрезанных своих дивизий, запросы на отход.
pub struct Seen {
    pub intent: Option<(String, u32)>,
    pub cut: usize,
    /// Запросы, дождавшиеся срока ответа: (штаб, дивизия, час).
    pub requests: Vec<(u32, u32, u32)>,
    /// Армии, прорвавшие оборону: (штаб, последний час с прорывом) — повод «прорвала оборону» один раз на армию.
    pub broke: Vec<(u32, u32)>,
    /// Задачи, поставленные штабом армиям вне истории: (армия, час, точка) — та же точка той же армии в пределах цикла
    /// не ставится снова.
    pub tasked: Vec<(u32, u32, crate::geo::XY)>,
}

pub struct Snapshot {
    pub tick: u32,
    pub motives: Motives,
    pub mood: Mood,
    pub picture: Picture,
    /// Действующее решение (подпись варианта).
    pub intent: Option<String>,
}

/// Командующие прогона: по сторонам включены ли, список, ведомость расстояний до объектов.
pub struct State {
    pub enabled: [bool; 2],
    pub list: Vec<Commander>,
    pub log: DistLog,
    /// Запросы, поднятые командующими, ждущие ответа или исполнения.
    pub raised: Vec<Raised>,
    /// Сколько раз строился базовый проигрыш «в уме» (на командующего в час; для проверки).
    pub baselines: u32,
}

/// У штаба действующий командующий: сторона включена, профиль есть, штаб ведёт агент (не игрок). Тогда штаб не
/// вводит подвижные группы сам, а верхняя инстанция отвечает на запросы своим решением, а не прежним «держать».
///
/// В «истории как замысле» советский фронт идёт по приказам сценария, а его командующий решает только за армии вне
/// истории (`for_strayed`).
pub fn active(sim: &Sim, hq: u32) -> bool {
    (sim.command.control.get(hq as usize) == Some(&Control::Agent) || for_strayed(sim, hq))
        && sim.commanders.enabled[side_idx(sim.world.hqs[hq as usize].side)]
        && sim.commanders.list.iter().any(|c| c.hq == hq)
}

/// Принять выбранный вариант: замысел, разбор, исполнение. «Продолжать по плану» действующий замысел не сбрасывает;
/// повтор действующего решения с той же целью директив заново не отдаёт — пишется только документ решения.
pub fn adopt(sim: &mut Sim, c: &mut Commander, options: Vec<Scored>, chosen: usize, tick: u32, trigger: String) {
    c.last = tick;
    let why = why(&options, chosen);
    let kind = options[chosen].choice.kind.clone();
    let repeat = c.picture.as_ref().is_some_and(|pic| repeats(c, pic, &kind));
    // рубеж отхода держится, пока решение — отход той же армии
    match &kind {
        Kind::Withdraw { hq } if c.intent.as_ref() == Some(&kind) && c.withdraw_at.iter().any(|x| x.0 == *hq) => {}
        Kind::Withdraw { hq } => { c.withdraw_at.clear(); if let Some(at) = super::apply::rear_of(sim, *hq) { c.withdraw_at.push((*hq, at)); } }
        Kind::Continue => {}
        _ => c.withdraw_at.clear(),
    }
    if let Kind::Encircle { pocket } = &kind { c.encircle_at = c.picture.as_ref().and_then(|p| p.pockets.get(*pocket)).map(|p| p.center); }
    let keep = matches!(kind, Kind::Continue) && c.intent.is_some();
    if !keep {
        if !matches!(kind, Kind::Encircle { .. }) { c.encircle_at = None; }
        c.intent = Some(kind.clone());
        c.intent_label = Some(options[chosen].choice.label.clone());
    }
    c.decisions.push(Decision { tick, trigger, options, chosen, why });
    if repeat { super::apply::record(sim, c, tick, Vec::new()); } else { super::apply::apply(sim, c, &kind, tick); }
}

/// Вариант продолжает действующее решение командующего `c` по картине `pic`: как `same_line`, но котёл «замкнуть
/// кольцо» опознаётся по месту (ближайший к прежнему центру в пределах `SAME_TARGET_KM`), а не по номеру в картине.
pub fn continues(c: &Commander, pic: &Picture, k: &Kind) -> bool {
    same_line(k, c.intent.as_ref()) || same_target(c, pic, k)
}

/// Командующие в фазе командования шага (до решений штабов): раз в час каждому; выключены — ничего.
pub fn cycle(sim: &mut Sim, tick: u32) {
    if !sim.commanders.enabled.iter().any(|&e| e) { return; }
    let mut log = std::mem::take(&mut sim.commanders.log);
    log.record(sim);
    sim.commanders.log = log;
    let mut list = std::mem::take(&mut sim.commanders.list);
    let mut hourly = super::mind::Hourly::default();
    for c in list.iter_mut() { hour(sim, c, tick, &mut hourly); }
    sim.commanders.baselines += hourly.count;
    sim.commanders.list = list;
    super::apply::execute_permitted(sim, tick);
}

/// Цикл решения ступени, ч.
fn cycle_hours(sim: &Sim, hq: u32) -> u32 {
    let c = &sim.rules.commanders.cycle;
    match sim.world.hqs[hq as usize].echelon { Echelon::HighCommand => c.high, Echelon::Front => c.front, Echelon::Army | Echelon::Corps => c.army }.max(1)
}

/// Решение командующего: варианты, оценка, выбор, разбор, исполнение.
/// Решение командующего; `answers` — только ответы на запросы (`Some(true)`), только прочее (`Some(false)`), всё (`None`).
fn decide(sim: &mut Sim, c: &mut Commander, tick: u32, trigger: String, hourly: &mut super::mind::Hourly, answers: Option<bool>) {
    c.last = tick;
    let p = sim.rules.commanders.profiles[c.profile].clone();
    let Some(pic) = c.picture.as_ref() else { return };
    let opts = match (sim.world.hqs[c.hq as usize].side, sim.world.hqs[c.hq as usize].echelon) {
        (Side::Su, _) => options_su(sim, c.hq, &p, pic),
        (Side::De, Echelon::HighCommand) => options_high(sim, c.hq, &p),
        (Side::De, _) => options_de(sim, c.hq, &p, pic),
    };
    let answer = |k: &Kind| matches!(k, Kind::Permit { .. } | Kind::Forbid { .. });
    let opts: Vec<Choice> = opts.into_iter().filter(|ch| answers.is_none_or(|a| answer(&ch.kind) == a)).collect();
    if opts.is_empty() { return; }
    let t = effective(&p.traits, &c.mood, &sim.rules.commanders.mood);
    let w = &sim.rules.commanders.weights;
    let mut options: Vec<Scored> = opts.iter().map(|ch| score(ch, &c.motives, &t, w, continues(c, pic, &ch.kind))).collect();
    // «в уме»: лучшие варианты проигрываются на копии мира, польза пересчитывается
    let ahead = sim.rules.commanders.lookahead_hours;
    if ahead > 0 { super::mind::look(sim, c, pic, &mut options, &t, w, ahead, hourly, |k| continues(c, pic, k)); }
    let chosen = pick_for(&options, |k| continues(c, pic, k));
    adopt(sim, c, options, chosen, tick, trigger);
}

/// Включить командующих стороны: на каждый её штаб, у которого есть профиль; штаб без профиля решает по правилам штаба.
pub fn enable(sim: &mut Sim, side: Side) {
    let i = side_idx(side);
    if sim.commanders.enabled[i] { return; }
    sim.commanders.enabled[i] = true;
    let start = sim.rules.commanders.mood.start;
    let tick = sim.world.tick;
    for (h, x) in sim.world.hqs.iter().enumerate() {
        if x.side != side { continue; }
        let Some(profile) = sim.rules.commanders.profiles.iter().position(|p| p.hqs.contains(&x.id)) else { continue };
        sim.commanders.list.push(Commander {
            hq: h as u32, profile, motives: sim.rules.commanders.profiles[profile].motives, mood: start, intent: None, intent_label: None,
            last: tick, snapshots: Vec::new(), decisions: Vec::new(), picture: None, seen: Seen::default(), withdraw_at: Vec::new(), encircle_at: None,
        });
    }
}

/// Командующий советского фронта по приказам сценария при включённом `intent` стороны: решает за подчинённые армии
/// вне истории (варианты — только для них; таких нет — решения нет).
pub fn for_strayed(sim: &Sim, hq: u32) -> bool {
    let h = &sim.world.hqs[hq as usize];
    h.side == Side::Su && h.echelon == Echelon::Front && sim.intent.enabled[side_idx(h.side)]
        && sim.command.control.get(hq as usize) == Some(&Control::Script)
}

/// Час командующего: состояние и мотивы по картине, решение по циклу или по перемене обстановки, снимок.
fn hour(sim: &mut Sim, c: &mut Commander, tick: u32, hourly: &mut super::mind::Hourly) {
    if !sim.commanders.enabled[side_idx(sim.world.hqs[c.hq as usize].side)] { return; }
    let pic = picture(sim, c.hq, &sim.commanders.log);
    let behind = task_behind(sim, c.hq, tick);
    // наступающий меряет успех продвижением, обороняющийся — удержанной землёй
    let attacking = sim.world.hqs[c.hq as usize].side == Side::Su || matches!(c.intent, Some(Kind::Counterattack { .. }));
    c.mood = mood_step(&c.mood, &pic, c.picture.as_ref(), behind, attacking, &sim.rules.commanders.mood);
    c.motives = current(&sim.rules.commanders.profiles[c.profile].motives, &pic, &sim.rules.commanders.gains);
    let trig = trigger(sim, c, &pic, tick);
    c.picture = Some(pic);
    let before = c.decisions.len();
    if for_strayed(sim, c.hq) { staff(sim, c, tick); }
    // игрок или приказы сценария на месте штаба — командующий не решает (кроме армий вне истории в `intent`)
    let agent = sim.command.control.get(c.hq as usize) == Some(&Control::Agent) || for_strayed(sim, c.hq);
    let cycle = cycle_hours(sim, c.hq);
    if agent && (trig.is_some() || tick >= c.last + cycle) {
        let reason = trig.clone().unwrap_or_else(|| format!("цикл решения {cycle} ч"));
        if sim.world.hqs[c.hq as usize].echelon == Echelon::HighCommand {
            // верхняя инстанция сначала отвечает на все ждущие запросы — каждый ответ отдельным решением, потом прочее
            let due = tick >= c.last + cycle;
            let side = sim.world.hqs[c.hq as usize].side;
            let wait = sim.rules.command.de.permission_hours as u32;
            let waiting = |sim: &Sim| sim.command.requests.iter().filter(|r| r.answer.is_none() && tick >= r.tick + wait && sim.world.hqs[r.hq as usize].side == side).count();
            let mut left = waiting(sim);
            let mut answered = 0;
            while left > 0 {
                decide(sim, c, tick, if answered == 0 { reason.clone() } else { format!("ещё запросы на отход: {left}") }, hourly, Some(true));
                answered += 1;
                let now = waiting(sim);
                if now >= left { break; }
                left = now;
            }
            // прочее — по циклу, по иной перемене обстановки, чем запросы, или когда отвечать было не на что
            let other = trig.as_deref().is_some_and(|t| t.split("; ").any(|p| !p.starts_with(REQUESTS_DUE)));
            if answered == 0 || due || other { decide(sim, c, tick, reason, hourly, Some(false)); }
        } else {
            decide(sim, c, tick, reason, hourly, None);
        }
    }
    if c.decisions.len() > before || tick.is_multiple_of(SNAPSHOT_HOURS) {
        let picture = c.picture.clone().expect("картина часа");
        c.snapshots.push(Snapshot { tick, motives: c.motives, mood: c.mood, picture, intent: c.intent_label.clone() });
    }
}

/// Выбор: наибольшая польза; ничья — продолжение действующего решения, затем «продолжать» / «держаться», затем первый.
pub fn pick(v: &[Scored], intent: Option<&Kind>) -> usize {
    let top = v.iter().map(|s| s.total).fold(f64::NEG_INFINITY, f64::max);
    let tied: Vec<usize> = (0..v.len()).filter(|&i| v[i].total >= top - TIE).collect();
    tied.iter().copied().find(|&i| same_line(&v[i].choice.kind, intent))
        .or_else(|| tied.iter().copied().find(|&i| matches!(v[i].choice.kind, Kind::Continue | Kind::Hold)))
        .unwrap_or(tied[0])
}

/// `pick` с проверкой продолжения по картине (`continues`).
fn pick_for(v: &[Scored], cont: impl Fn(&Kind) -> bool) -> usize {
    let top = v.iter().map(|s| s.total).fold(f64::NEG_INFINITY, f64::max);
    let tied: Vec<usize> = (0..v.len()).filter(|&i| v[i].total >= top - TIE).collect();
    tied.iter().copied().find(|&i| cont(&v[i].choice.kind))
        .or_else(|| tied.iter().copied().find(|&i| matches!(v[i].choice.kind, Kind::Continue | Kind::Hold)))
        .unwrap_or(tied[0])
}

/// Решение повторяет действующее с той же целью: директивы заново не отдаются. Запросы (отход, прорыв из кольца)
/// поднимаются заново — за дивизии, за которые их ещё нет; ответы на запросы — каждый свой.
fn repeats(c: &Commander, pic: &Picture, k: &Kind) -> bool {
    match (k, c.intent.as_ref()) {
        (_, None) => false,
        (Kind::Withdraw { .. } | Kind::Breakout { .. } | Kind::Permit { .. } | Kind::Forbid { .. }, _) => false,
        (Kind::Encircle { .. } | Kind::Counterattack { .. } | Kind::MoveReserve { .. } | Kind::Relief { .. }, _) => same_target(c, pic, k),
        (k, Some(i)) => k == i,
    }
}

/// Вариант продолжает действующее решение: тот же вариант; ответ на запрос — тот же ответ (номер запроса не важен:
/// запросы разные, линия та же); «продолжать по плану» — продолжение любого действующего решения.
pub fn same_line(a: &Kind, intent: Option<&Kind>) -> bool {
    match (a, intent) {
        (_, None) => false,
        (Kind::Continue, Some(_)) => true,
        (Kind::Permit { .. }, Some(Kind::Permit { .. })) | (Kind::Forbid { .. }, Some(Kind::Forbid { .. })) => true,
        (a, Some(b)) => a == b,
    }
}

fn same_pocket(c: &Commander, pic: &Picture, pocket: usize) -> bool {
    match (c.encircle_at, pic.pockets.get(pocket)) { (Some(at), Some(p)) => at.dist(p.center) <= SAME_TARGET_KM, _ => false }
}

/// Тот же вид решения, что действующее, и та же цель: котёл — по месту; контратака, резерв, деблокирование — тот же
/// исполнитель и точка в пределах `SAME_TARGET_KM` (центр выручаемой армии и вклинение смещаются от часа к часу).
fn same_target(c: &Commander, pic: &Picture, k: &Kind) -> bool {
    let near = |a: crate::geo::XY, b: crate::geo::XY| a.dist(b) <= SAME_TARGET_KM;
    match (k, c.intent.as_ref()) {
        (Kind::Encircle { pocket }, Some(Kind::Encircle { .. })) => same_pocket(c, pic, *pocket),
        (Kind::Counterattack { from, at }, Some(Kind::Counterattack { from: f0, at: a0 })) => from == f0 && near(*at, *a0),
        (Kind::MoveReserve { hq, to }, Some(Kind::MoveReserve { hq: h0, to: t0 })) => hq == h0 && near(*to, *t0),
        (Kind::Relief { army, by, toward }, Some(Kind::Relief { army: a0, by: b0, toward: t0 })) => army == a0 && by == b0 && near(*toward, *t0),
        _ => false,
    }
}

/// Польза варианта (см. начало модуля). `t` — черты с поправкой на состояние; `continuing` — вариант повторяет
/// действующее решение.
pub fn score(c: &Choice, m: &Motives, t: &Traits, w: &Weights, continuing: bool) -> Scored {
    let amb = 0.5 + t.get(Trait::Ambition);
    let mut parts = [0.0; 7];
    for (i, p) in parts.iter_mut().enumerate() {
        let k = if i == Motive::Rival as usize || i == Motive::Destroy as usize { amb } else { 1.0 };
        *p = m.0[i] * k * c.contrib.0[i];
    }
    let penalty = (1.0 - t.get(Trait::Risk)) * w.uncertainty * c.uncertainty + (1.0 - t.get(Trait::LossTolerance)) * w.losses * c.losses;
    let bonus = if continuing { t.get(Trait::Persistence) * w.persistence } else { 0.0 } + t.get(Trait::Obedience) * w.obedience * c.contrib.get(Motive::Task);
    let total = parts.iter().sum::<f64>() - penalty + bonus;
    Scored { choice: c.clone(), parts: Motives(parts), penalty, bonus, total, mind: None }
}

/// Штаб фронта ставит задачу каждой армии вне истории, которой она нужна: лучший вариант «поставить задачу» —
/// отдельным решением с документом «задача армии вне истории», замысел командующего не меняется.
fn staff(sim: &mut Sim, c: &mut Commander, tick: u32) {
    let Some(pic) = c.picture.clone() else { return };
    let p = sim.rules.commanders.profiles[c.profile].clone();
    let cycle = cycle_hours(sim, c.hq);
    c.seen.tasked.retain(|x| tick < x.1 + cycle.max(1));
    for a in super::options_su::strayed(sim, &pic) {
        if !super::options_su::needs_task(sim, a) { continue; }
        let Some(ch) = super::options_su::assign(sim, &p, a) else { continue };
        let Kind::Assign { at, .. } = ch.kind else { continue };
        if c.seen.tasked.iter().any(|x| x.0 == a && x.2.dist(at) <= 1.0) { continue; }
        c.seen.tasked.push((a, tick, at));
        let t = effective(&p.traits, &c.mood, &sim.rules.commanders.mood);
        let options = vec![score(&ch, &c.motives, &t, &sim.rules.commanders.weights, false)];
        let why = format!("задача армии вне истории — обязанность штаба фронта. {}", why(&options, 0));
        let name = sim.world.hqs[a as usize].name.clone();
        let kind = ch.kind.clone();
        c.decisions.push(Decision { tick, trigger: format!("армия без задачи: {name}"), options, chosen: 0, why });
        super::apply::apply(sim, c, &kind, tick);
    }
}

/// Отставание от срока ближайшей задачи старшего: доля срока, прошедшая после него, пока рубеж не достигнут (0…1);
/// срок задачи — от отдачи директивы до часа рубежа, не меньше `BEHIND_MIN_H`. Нет срока — 0.
fn task_behind(sim: &Sim, hq: u32, tick: u32) -> f64 {
    let Some(d) = sim.command.intent.get(hq as usize).and_then(Option::as_ref) else { return 0.0 };
    let Some(line) = d.immediate.as_ref() else { return 0.0 };
    let (Some(by), Some(mid)) = (line.by, crate::command::agent::mid(&line.pts)) else { return 0.0 };
    if tick <= by { return 0.0; }
    let reached = divisions_of(sim, hq).into_iter().any(|i| sim.world.divisions[i].vars.pos.dist(mid) <= LINE_REACHED_KM);
    if reached { return 0.0; }
    let span = (by.saturating_sub(d.issued) as f64).max(BEHIND_MIN_H);
    ((tick - by) as f64 / span).min(1.0)
}

/// Перемены обстановки с прошлого часа (повод решить вне цикла); заодно обновляет увиденное. Прорыв армии — повод
/// один раз, снова — только после потери прорыва не меньше чем на `BROKE_LOST_H` ч.
pub fn trigger(sim: &Sim, c: &mut Commander, pic: &Picture, tick: u32) -> Option<String> {
    let name = |h: u32| sim.world.hqs[h as usize].name.clone();
    let mut why: Vec<String> = Vec::new();
    if let Some(prev) = &c.picture {
        for a in pic.armies.iter().filter(|a| a.broke_through) {
            let fresh = match c.seen.broke.iter_mut().find(|x| x.0 == a.hq) {
                Some(x) => { let lost = tick.saturating_sub(x.1) > BROKE_LOST_H; x.1 = tick; lost }
                None => { c.seen.broke.push((a.hq, tick)); true }
            };
            if fresh && !prev.armies.iter().any(|b| b.hq == a.hq && b.broke_through) { why.push(format!("{} прорвала оборону", name(a.hq))); }
        }
        for &f in &pic.open_flanks { if !prev.open_flanks.contains(&f) { why.push(format!("открыт фланг: {}", name(f))); } }
        if pic.pockets.len() > prev.pockets.len() { why.push("новый котёл противника".into()); }
    }
    let cut = divisions_of(sim, c.hq).into_iter().filter(|&i| sim.world.divisions[i].cut_since.is_some()).count();
    if cut > c.seen.cut { why.push(format!("отрезаны свои дивизии: {cut}")); }
    c.seen.cut = cut;
    if let Some(d) = sim.command.intent.get(c.hq as usize).and_then(Option::as_ref).filter(|d| d.from != c.hq) {
        let key = (d.id.clone(), d.issued);
        if c.seen.intent.as_ref() != Some(&key) {
            why.push(format!("новая директива старшего ({})", name(d.from)));
            c.seen.intent = Some(key);
        }
    }
    if sim.world.hqs[c.hq as usize].echelon == Echelon::HighCommand {
        // повод — только запрос, впервые дождавшийся срока ответа (а не каждый час, пока он ждёт)
        let wait = sim.rules.command.de.permission_hours as u32;
        let side = sim.world.hqs[c.hq as usize].side;
        let mut fresh = 0;
        for r in sim.command.requests.iter().filter(|r| r.answer.is_none() && tick >= r.tick + wait && sim.world.hqs[r.hq as usize].side == side) {
            let key = (r.hq, r.division, r.tick);
            if !c.seen.requests.contains(&key) { fresh += 1; c.seen.requests.push(key); }
        }
        c.seen.requests.retain(|k| sim.command.requests.iter().any(|r| (r.hq, r.division, r.tick) == *k));
        if fresh > 0 { why.push(format!("{REQUESTS_DUE}: {fresh}")); }
    }
    if why.is_empty() { None } else { Some(why.join("; ")) }
}

/// Обоснование словами: два крупнейших по величине слагаемых выбранного варианта и перевес над следующим.
pub fn why(v: &[Scored], chosen: usize) -> String {
    let s = &v[chosen];
    let mut terms: Vec<(&str, f64)> = MOTIVE_NAMES.iter().zip(s.parts.0).map(|(n, x)| (*n, x)).collect();
    terms.push(("неопределённость и потери", -s.penalty));
    terms.push(("настойчивость и послушание", s.bonus));
    terms.retain(|t| t.1.abs() > TIE);
    terms.sort_by(|a, b| b.1.abs().total_cmp(&a.1.abs()));
    let main: Vec<String> = terms.iter().take(2).map(|(n, x)| format!("{n} {}", num(*x))).collect();
    let mut out = format!("«{}»: польза {}", s.choice.label, num(s.total));
    if !main.is_empty() { out += &format!("; главное — {}", main.join(", ")); }
    let runner = (0..v.len()).filter(|&i| i != chosen).max_by(|&a, &b| v[a].total.total_cmp(&v[b].total));
    match runner {
        Some(r) => out += &format!("; перевес над «{}» — {}", v[r].choice.label, format!("{:.2}", s.total - v[r].total).replace('.', ",")),
        None => out += "; другого варианта не было",
    }
    out
}

/// Общее на час: базовый проигрыш «продолжать» каждого командующего (строится при его первом близком выборе
/// часа, с той же поправкой силы противника, что и у его вариантов) и сколько раз строился.
pub struct Hourly { pub base: Vec<(u32, MindResult)>, pub count: u32 }

fn baseline(sim: &Sim, c: &Commander, pic: &Picture, shared: &mut Hourly, hours: u32) -> MindResult {
    if let Some(x) = shared.base.iter().find(|x| x.0 == c.hq) { return x.1.clone(); }
    let cont = Choice { kind: Kind::Continue, label: String::new(), contrib: Motives([0.0; 7]), uncertainty: 0.0, losses: 0.0, rule: "" };
    let m = imagine(sim, c, pic, &cont, hours);
    shared.base.push((c.hq, m.clone()));
    shared.count += 1;
    m
}

fn gauge(sim: &Sim, c: &Commander, own: &[usize]) -> Gauge {
    let w = &sim.world;
    let own_s: f64 = own.iter().map(|&i| sim.material_strength(&w.divisions[i])).sum();
    let (mut all, mut cut) = (0.0, 0.0);
    let side = w.hqs[c.hq as usize].side;
    for d in w.divisions.iter().filter(|d| d.side != side && !d.state.out()) {
        let s = sim.strength(d);
        all += s;
        if d.cut_since.is_some() { cut += s; }
    }
    Gauge { to_objective: dist_to_objective(sim, c.hq), own: own_s, encircled: if all > 0.0 { cut / all } else { 0.0 } }
}

/// Проиграть `choice` на `hours` часов вперёд.
pub fn imagine(sim: &Sim, c: &Commander, pic: &Picture, choice: &Choice, hours: u32) -> MindResult {
    let mut fork = sim.fork();
    scale_enemy(&mut fork, pic);
    let own = divisions_of(&fork, c.hq);
    let before = gauge(&fork, c, &own);
    // применение берёт решение из последнего документа командующего
    let scored = Scored { choice: choice.clone(), parts: Motives([0.0; 7]), penalty: 0.0, bonus: 0.0, total: 0.0, mind: None };
    let mut withdraw_at = c.withdraw_at.clone();
    if let Kind::Withdraw { hq } = &choice.kind {
        if !withdraw_at.iter().any(|x| x.0 == *hq) { withdraw_at = super::apply::rear_of(&fork, *hq).map(|at| (*hq, at)).into_iter().collect(); }
    }
    let tick = fork.world.tick;
    let temp = Commander {
        hq: c.hq, profile: c.profile, motives: c.motives, mood: c.mood, intent: Some(choice.kind.clone()), intent_label: Some(choice.label.clone()),
        last: tick, snapshots: Vec::new(), decisions: vec![Decision { tick, trigger: String::new(), options: vec![scored], chosen: 0, why: String::new() }],
        picture: c.picture.clone(), seen: c.seen.clone(), withdraw_at, encircle_at: None,
    };
    let n0 = fork.command.requests.len();
    super::apply::apply(&mut fork, &temp, &choice.kind, tick);
    // командующий проигрывает исход своего варианта: поднятые запросы на отход и прорыв считаются разрешёнными
    for r in fork.command.requests[n0..].iter_mut() { r.answer = Some(true); r.answered_at = tick; }
    super::apply::execute_permitted(&mut fork, tick);
    for _ in 0..hours { fork.step(); }
    let after = gauge(&fork, c, &own);
    let advance_km = match (before.to_objective, after.to_objective) { (Some(a), Some(b)) => a - b, _ => 0.0 };
    let losses = if before.own > 0.0 { ((before.own - after.own) / before.own).max(0.0) } else { 0.0 };
    MindResult { hours, advance_km, losses, encircled: after.encircled - before.encircled }
}

/// Два лучших по пользе варианта (один при суженном обзоре) проигрываются «в уме», польза пересчитывается.
/// `shared` — базовые проигрыши часа по командующим.
pub fn look(sim: &Sim, c: &Commander, pic: &Picture, options: &mut [Scored], t: &Traits, w: &Weights, hours: u32, shared: &mut Hourly, continuing: impl Fn(&Kind) -> bool) {
    if !wanted(sim, c, options) { return; }
    // суженный обзор (напряжение выше порога) оставляет один вариант: заглядывание вперёд ему достаётся реже
    let n = if narrowed(&c.mood, &sim.rules.commanders.mood) { 1 } else { TOP };
    let mut order: Vec<usize> = (0..options.len()).collect();
    order.sort_by(|&a, &b| options[b].total.total_cmp(&options[a].total));
    order.truncate(n);
    let base = baseline(sim, c, pic, shared, hours);
    for i in order {
        let ch = options[i].choice.clone();
        // «продолжать» — сам базовый проигрыш; варианты без действия — его же (поправка нулевая), вклад прежний
        let (refined, m) = if idle(&ch.kind) { (ch, base.clone()) } else {
            let m = imagine(sim, c, pic, &ch, hours);
            (Choice { contrib: refine(&ch.contrib, &m, &base), ..ch }, m)
        };
        let mut s = score(&refined, &c.motives, t, w, continuing(&refined.kind));
        s.mind = Some(m);
        options[i] = s;
    }
}

/// Вклад варианта, уточнённый проигрышем: к прежнему вкладу прибавляется `BLEND`·измеренное (разница с «продолжать»,
/// нормированная к −1…1; при равном исходе — 0, вклад прежний), итог в −1…1. Задача и соперник — по продвижению, сохранение армий — по потерям, разгром — по охвату.
pub fn refine(contrib: &Motives, m: &MindResult, base: &MindResult) -> Motives {
    let adv = ((m.advance_km - base.advance_km) / (ADVANCE_KM_PER_H * m.hours.max(1) as f64)).clamp(-1.0, 1.0);
    let loss = ((base.losses - m.losses) / LOSSES_SCALE).clamp(-1.0, 1.0);
    let enc = ((m.encircled - base.encircled) / ENCIRCLED_SCALE).clamp(-1.0, 1.0);
    let mut out = *contrib;
    for (k, x) in [(Motive::Task, adv), (Motive::Rival, adv), (Motive::Preserve, loss), (Motive::Destroy, enc)] {
        out.0[k as usize] = (contrib.get(k) + BLEND * x).clamp(-1.0, 1.0);
    }
    out
}

/// Сила противника в зоне разведки каждой армии — к оценке командующего (люди, танки, орудия).
pub fn scale_enemy(fork: &mut Sim, pic: &Picture) {
    let recon = fork.rules.contact_km * RECON_X;
    let mut done: Vec<usize> = Vec::new();
    for a in pic.armies.iter().filter(|a| a.enemy_true > 0.0) {
        let k = a.enemy_est / a.enemy_true;
        let side = fork.world.hqs[a.hq as usize].side;
        let mine: Vec<_> = divisions_of(fork, a.hq).into_iter().map(|i| fork.world.divisions[i].vars.pos).collect();
        for e in 0..fork.world.divisions.len() {
            let d = &mut fork.world.divisions[e];
            if d.side == side || d.state.out() || done.contains(&e) || !mine.iter().any(|p| p.dist(d.vars.pos) <= recon) { continue; }
            d.vars.personnel *= k;
            d.vars.tanks *= k;
            d.vars.guns *= k;
            done.push(e);
        }
    }
}

/// Проигрывание «в уме» ведут только фронты и группы армий, и только когда выбор близок.
pub fn wanted(sim: &Sim, c: &Commander, options: &[Scored]) -> bool {
    if sim.world.hqs[c.hq as usize].echelon != Echelon::Front || options.len() < 2 { return false; }
    let mut v: Vec<f64> = options.iter().map(|s| s.total).collect();
    v.sort_by(|a, b| b.total_cmp(a));
    v[0] - v[1] < sim.rules.commanders.mind_margin
}

/// Веса мотивов по картине: соперник ближе — растёт `Rival` (без соперника — 0), потери — `Preserve`,
/// открытые фланги — `NoEncircle`; остальные — как на начало.
pub fn current(base: &Motives, pic: &Picture, g: &Gains) -> Motives {
    let mut m = *base;
    let n = pic.armies.len() as f64;
    m.0[Motive::Rival as usize] = match (&pic.rival, pic.to_objective_km) {
        (Some(r), Some(own)) if own > 0.0 => base.get(Motive::Rival) + g.rival * ((own - r.to_objective_km) / own).max(0.0),
        (Some(_), _) => base.get(Motive::Rival),
        (None, _) => 0.0,
    };
    if n > 0.0 {
        let mean = pic.armies.iter().map(|a| a.strength).sum::<f64>() / n;
        m.0[Motive::Preserve as usize] += g.losses * (1.0 - mean).max(0.0);
        m.0[Motive::NoEncircle as usize] += g.flank * pic.open_flanks.len() as f64 / n;
    }
    m
}

/// Черты с поправкой на состояние: уверенность сдвигает риск и честолюбие; под напряжением послушный и
/// настойчивый костенеет (настойчивее, осторожнее в риске), прочие тянутся спасать армию (меньше терпят потерь).
pub fn effective(t: &Traits, mood: &Mood, m: &MoodRules) -> Traits {
    let mut e = *t;
    let c = mood.confidence - 0.5;
    e.0[Trait::Risk as usize] += m.risk_shift * c;
    e.0[Trait::Ambition as usize] += m.ambition_shift * c;
    if mood.stress > 0.5 {
        let s = m.rigid_shift * (mood.stress - 0.5);
        if t.get(Trait::Obedience) + t.get(Trait::Persistence) > 1.0 {
            e.0[Trait::Persistence as usize] += s;
            e.0[Trait::Risk as usize] -= s;
        } else {
            e.0[Trait::LossTolerance as usize] -= s;
        }
    }
    Traits(e.0.map(clamp01))
}

/// Шаг состояния за час. `task_behind` — отставание от срока задачи старшего, доля (0…1): оно давит долей в сутки,
/// то есть в час — его двадцать четвёртая часть. `attacking` — наступающий: успех и застревание меряются темпом
/// продвижения против ожидаемого; обороняющийся: успех — удержанная земля (смещение войск за час не больше
/// `HOLD_KM_H`), неудача — отданная сверх того. Без прежней картины действует только возврат к состоянию на начало.
pub fn mood_step(prev: &Mood, pic: &Picture, prev_pic: Option<&Picture>, task_behind: f64, attacking: bool, m: &MoodRules) -> Mood {
    let behind = clamp01(task_behind) / 24.0;
    let n = pic.armies.len() as f64;
    let (mut confidence, mut stress) = (prev.confidence, prev.stress);
    if let Some(pp) = prev_pic {
        if n > 0.0 {
            // смещение за час, среднее по армиям, имеющимся в обеих картинах
            let steps: Vec<(f64, f64)> = pic.armies.iter().filter_map(|a| pp.armies.iter().find(|b| b.hq == a.hq).map(|b| (a.advance_km - b.advance_km, b.strength - a.strength))).collect();
            if !steps.is_empty() {
                let k = steps.len() as f64;
                let rate = steps.iter().map(|s| s.0).sum::<f64>() / k;
                let loss = steps.iter().map(|s| s.1).sum::<f64>() / k;
                let (success, stall) = if attacking {
                    let pace = m.expected_km_day / 24.0;
                    let ratio = if pace > 0.0 { rate / pace } else { 1.0 };
                    ((ratio - 1.0).clamp(0.0, 1.0), (1.0 - ratio).clamp(0.0, 1.0))
                } else {
                    let lost = rate.max(0.0);
                    ((1.0 - lost / HOLD_KM_H).clamp(0.0, 1.0), ((lost - HOLD_KM_H) / HOLD_KM_H).clamp(0.0, 1.0))
                };
                let norm_loss = m.normal_loss_day / 24.0;
                let excess = if norm_loss > 0.0 { ((loss - norm_loss) / norm_loss).clamp(0.0, 1.0) } else { 0.0 };
                let encircling = (pic.pockets.len() as f64 / n).min(1.0);
                confidence += m.success_gain * (success + encircling) - m.setback_gain * (stall + excess);
            }
        }
    }
    confidence -= m.setback_gain * behind;
    if n > 0.0 {
        let flanks = (pic.open_flanks.len() as f64 / n).min(1.0);
        // охвата своих в картине нет: вместо него доля ослабевших армий
        let weak = pic.armies.iter().filter(|a| a.strength < 0.5).count() as f64 / n;
        stress += m.threat_gain * (flanks + weak);
    }
    stress += m.pressure_gain * behind;
    confidence += m.decay * (m.start.confidence - confidence);
    stress += m.decay * (m.start.stress - stress);
    Mood { confidence: clamp01(confidence), stress: clamp01(stress) }
}

/// Вариант, оцениваемый командующим.
pub struct Choice {
    pub kind: Kind,
    /// Подпись для документа и интерфейса.
    pub label: String,
    /// Вклад варианта в каждый мотив, −1…1.
    pub contrib: Motives,
    /// Неопределённость исхода, 0…1.
    pub uncertainty: f64,
    /// Ожидаемые потери, 0…1.
    pub losses: f64,
    /// Статья ПУ-43 или положение опыта, на которое опирается вариант.
    pub rule: &'static str,
}

/// Что именно командующий решает сделать.
pub enum Kind {
    /// Идти по плану, ничего не менять.
    Continue,
    /// Ввести подвижную группу (штаб армии) в прорыв.
    CommitMobile { hq: u32 },
    /// Подождать с вводом подвижной группы.
    WaitMobile,
    /// Перенести главный удар на армии `to`.
    ShiftMainBlow { to: Vec<u32> },
    /// Повернуть армию `hq` к точке `at` (объект соперника).
    TurnToRival { hq: u32, at: XY },
    /// Замкнуть котёл с номером `pocket` в картине обстановки решения (тот же котёл в следующих картинах — по месту).
    Encircle { pocket: usize },
    /// Ввести армию второго эшелона.
    CommitSecond { hq: u32 },
    /// Держаться на месте.
    Hold,
    /// Отвести армию.
    Withdraw { hq: u32 },
    /// Контратаковать армией `from` по точке `at`.
    Counterattack { from: u32, at: XY },
    /// Передать силы от армии `from` армии `to`.
    ShiftForces { from: u32, to: u32 },
    /// Прорываться к точке `toward`.
    Breakout { toward: XY },
    /// Разрешить запрос подчинённого с номером `request`.
    Permit { request: usize },
    /// Отклонить запрос подчинённого с номером `request`.
    Forbid { request: usize },
    /// Выручить армию `army` ударом армии `by` к точке `toward`.
    Relief { army: u32, by: u32, toward: XY },
    /// Переместить резерв `hq` в точку `to`.
    MoveReserve { hq: u32, to: XY },
    /// Поставить армии вне истории задачу: точка `at` — объект плана фронта (`from_plan`) или пункт по местности;
    /// `defend` — в районе операции фронта задачи нет: оборона у пункта.
    Assign { army: u32, at: XY, from_plan: bool, defend: bool },
}

fn centroid(sim: &Sim, ds: &[usize]) -> Option<XY> {
    if ds.is_empty() { return None; }
    let n = ds.len() as f64;
    Some(XY::new(ds.iter().map(|&i| sim.world.divisions[i].vars.pos.x).sum::<f64>() / n, ds.iter().map(|&i| sim.world.divisions[i].vars.pos.y).sum::<f64>() / n))
}

fn contrib(parts: &[(Motive, f64)]) -> Motives {
    let mut m = [0.0; 7];
    for &(k, v) in parts { m[k as usize] = v.clamp(-1.0, 1.0); }
    Motives(m)
}

/// Доля живых дивизий штаба, отрезанных от своих (`None` — дивизий нет).
fn cut_share(sim: &Sim, hq: u32) -> Option<f64> {
    let ds = divisions_of(sim, hq);
    if ds.is_empty() { return None; }
    Some(ds.iter().filter(|&&i| sim.world.divisions[i].cut_since.is_some()).count() as f64 / ds.len() as f64)
}

/// Дивизия в бою: была в бою на предыдущем шаге (`World.engaged` — его итог) или наступает (кроме закрепления).
fn in_combat(sim: &Sim, i: usize) -> bool {
    sim.world.engaged.get(i).copied().unwrap_or(false) || matches!(sim.world.divisions[i].state, State::Attack(s) if s != AttackSub::Consolidate)
}

pub fn options_de(sim: &Sim, hq: u32, _p: &Profile, pic: &Picture) -> Vec<Choice> {
    let w = &sim.world;
    let mine: Vec<&ArmyView> = pic.armies.iter().collect();
    let worst = mine.iter().map(|a| threat(sim, Some(pic), a.hq)).fold(0.0, f64::max);
    let mut out = vec![Choice {
        kind: Kind::Hold, label: "Держаться на занятых рубежах".into(),
        contrib: contrib(&[(Motive::Hold, HOLD_HOLD), (Motive::Task, HOLD_TASK), (Motive::Save, HOLD_SAVE * worst)]),
        uncertainty: HOLD_UNC, losses: HOLD_LOSS, rule: "Truppenführung: оборона рубежа до последней возможности — по приказу старшего начальника",
    }];

    // отход армии: открытый фланг или охват своих, пока большинство армии не в кольце
    for a in &mine {
        let share = cut_share(sim, a.hq).unwrap_or(0.0);
        let flank = pic.open_flanks.contains(&a.hq);
        if in_pocket(sim, a.hq) || (!flank && share <= 0.0) { continue; }
        let k = WD_PER_CUT * share + if flank { WD_FLANK } else { 0.0 };
        out.push(Choice {
            kind: Kind::Withdraw { hq: a.hq }, label: format!("Отвести {} на рубеж в глубине", name(sim, a.hq)),
            contrib: contrib(&[(Motive::Save, WD_SAVE + k), (Motive::NoEncircle, WD_NOENC + k), (Motive::Hold, WD_HOLD), (Motive::Task, WD_TASK)]),
            uncertainty: WD_UNC, losses: WD_LOSS, rule: "Truppenführung: elastische Verteidigung — отход, чтобы не быть охваченным",
        });
    }

    // контратака: наступающий противник вблизи своих войск (вклинение) и свой резерв армии рядом
    let own: Vec<usize> = mine.iter().flat_map(|a| divisions_of(sim, a.hq)).collect();
    let wedges: Vec<XY> = (0..w.divisions.len()).filter(|&e| {
        let d = &w.divisions[e];
        d.side != w.hqs[hq as usize].side && matches!(d.state, State::Attack(_)) && own.iter().any(|&i| w.divisions[i].vars.pos.dist(d.vars.pos) <= sim.rules.contact_km)
    }).map(|e| w.divisions[e].vars.pos).collect();
    for a in &mine {
        let reserve: Vec<XY> = divisions_of(sim, a.hq).into_iter().filter(|&i| w.divisions[i].state == State::Reserve && !is_cut(sim, i)).map(|i| w.divisions[i].vars.pos).collect();
        let best = wedges.iter().filter_map(|&at| reserve.iter().map(|r| r.dist(at)).min_by(f64::total_cmp).filter(|&d| d <= COUNTER_KM).map(|d| (at, d)))
            .min_by(|x, y| x.1.total_cmp(&y.1));
        if let Some((at, _)) = best {
            out.push(Choice {
                kind: Kind::Counterattack { from: a.hq, at }, label: format!("Контратаковать резервом {} по вклинившемуся противнику", name(sim, a.hq)),
                contrib: contrib(&[(Motive::Destroy, CA_DESTROY), (Motive::Hold, CA_HOLD), (Motive::Preserve, CA_PRESERVE)]),
                uncertainty: CA_UNC, losses: CA_LOSS, rule: "Truppenführung: вклинение ликвидируется немедленной контратакой резерва",
            });
        }
    }

    // перегруппировка: с тихой армии (в текущий час нет боя) на угрожаемую
    let quiet = |a: &ArmyView| divisions_of(sim, a.hq).into_iter().all(|i| !in_combat(sim, i));
    for to in mine.iter().filter(|a| threat(sim, Some(pic), a.hq) > 0.0 && !in_pocket(sim, a.hq)) {
        let from = mine.iter().filter(|a| a.hq != to.hq && quiet(a) && !pic.open_flanks.contains(&a.hq)).max_by(|x, y| x.strength.total_cmp(&y.strength));
        if let Some(from) = from {
            out.push(Choice {
                kind: Kind::ShiftForces { from: from.hq, to: to.hq }, label: format!("Передать силы от {} к {}", name(sim, from.hq), name(sim, to.hq)),
                contrib: contrib(&[(Motive::Hold, SF_HOLD)]),
                uncertainty: SF_UNC, losses: SF_LOSS, rule: "Truppenführung: силы собираются на решающем участке за счёт спокойных",
            });
        }
    }

    // прорыв из кольца к своему штабу снаружи
    if in_pocket(sim, hq) {
        if let Some(from) = centroid(sim, &divisions_of(sim, hq)) {
            if let Some((_, toward)) = outside_hq(sim, hq, from) {
                out.push(Choice {
                    kind: Kind::Breakout { toward }, label: "Прорываться из окружения к своим".into(),
                    contrib: contrib(&[(Motive::Save, BO_SAVE), (Motive::Preserve, BO_PRESERVE), (Motive::Hold, BO_HOLD)]),
                    uncertainty: BO_UNC, losses: BO_LOSS, rule: "Truppenführung: окружённые прорываются на соединение со своими, пока кольцо не сомкнулось плотно",
                });
            }
        }
    }
    out
}

pub fn options_high(sim: &Sim, hq: u32, _p: &Profile) -> Vec<Choice> {
    let mut out = Vec::new();

    // неотвеченные запросы корпусов: по паре «разрешить / запретить»
    // запросы, дождавшиеся срока ответа (`permissionHours` — тот же час, когда отвечал прежний «держать»)
    let wait = sim.rules.command.de.permission_hours as u32;
    for (i, r) in sim.command.requests.iter().enumerate().filter(|(_, r)| r.answer.is_none() && sim.world.tick >= r.tick + wait) {
        let army = sim.world.hqs[r.hq as usize].parent;
        let t = army.map_or(0.0, |a| threat(sim, None, a));
        out.push(Choice {
            kind: Kind::Forbid { request: i }, label: format!("Запретить отход: {}", name(sim, r.hq)),
            contrib: contrib(&[(Motive::Hold, FB_HOLD), (Motive::Save, FB_SAVE + FB_SAVE_PER_THREAT * t)]),
            uncertainty: FB_UNC, losses: FB_LOSS, rule: "Приказ «держать» — политическая цель Ставки с начала операции; Truppenführung: решение принимает старший начальник",
        });
        out.push(Choice {
            kind: Kind::Permit { request: i }, label: format!("Разрешить отход: {}", name(sim, r.hq)),
            contrib: contrib(&[(Motive::Save, PM_SAVE + PM_SAVE_PER_THREAT * t), (Motive::Hold, PM_HOLD)]),
            uncertainty: PM_UNC, losses: PM_LOSS, rule: "Truppenführung: elastische Verteidigung — отход допустим, если рубеж не удержать",
        });
    }

    // окружённые армии и армии снаружи
    let armies = side_armies(sim, hq);
    let pocketed: Vec<u32> = armies.iter().copied().filter(|&a| in_pocket(sim, a)).collect();
    for &a in &pocketed {
        let Some(c) = centroid(sim, &divisions_of(sim, a)) else { continue };
        if let Some((by, _)) = outside_hq(sim, hq, c) {
            out.push(Choice {
                kind: Kind::Relief { army: a, by, toward: c }, label: format!("Выручить {} ударом снаружи", name(sim, a)),
                contrib: contrib(&[(Motive::Save, RL_SAVE), (Motive::Hold, RL_HOLD), (Motive::Preserve, RL_PRESERVE)]),
                uncertainty: RL_UNC, losses: RL_LOSS, rule: "Truppenführung: окружённым помогают встречным ударом извне",
            });
        }
    }

    // резерв ОКВ (штабы `okwReserve.hqs` правил командующих) — к самой угрожаемой армии
    let okw: Vec<u32> = (0..sim.world.hqs.len() as u32).filter(|&h| sim.rules.commanders.okw_reserve_hqs.contains(&sim.world.hqs[h as usize].id)).collect();
    let reserves: Vec<usize> = (0..sim.world.divisions.len()).filter(|&i| {
        let d = &sim.world.divisions[i];
        d.state == State::Reserve && (d.hq == hq || okw.iter().any(|&o| under(sim, d.hq, o)))
    }).collect();
    let target = armies.iter().copied().map(|a| (a, threat(sim, None, a))).filter(|x| x.1 > 0.0)
        .max_by(|x, y| x.1.total_cmp(&y.1).then(y.0.cmp(&x.0))).and_then(|(a, _)| centroid(sim, &divisions_of(sim, a)).map(|c| (a, c)));
    if let Some((army, to)) = target {
        let mut seen = Vec::new();
        for i in reserves.into_iter().filter(|&i| !is_cut(sim, i) && !under(sim, sim.world.divisions[i].hq, army)) {
            let h = sim.world.divisions[i].hq;
            if seen.contains(&h) { continue; }
            seen.push(h);
            out.push(Choice {
                kind: Kind::MoveReserve { hq: h, to }, label: format!("Двинуть резерв {} к угрожаемой армии", name(sim, h)),
                contrib: contrib(&[(Motive::Save, MR_SAVE), (Motive::Hold, MR_HOLD)]),
                uncertainty: MR_UNC, losses: MR_LOSS, rule: "Truppenführung: резерв старшего начальника вводится на решающем участке",
            });
        }
    }
    out
}

/// Свой штаб снаружи: армия с дивизиями, из которых ни одна не отрезана, ближайшая к `from`; цель — центр её дивизий.
pub(super) fn outside_hq(sim: &Sim, hq: u32, from: XY) -> Option<(u32, XY)> {
    side_armies(sim, hq).into_iter().filter(|&a| cut_share(sim, a) == Some(0.0))
        .filter_map(|a| centroid(sim, &divisions_of(sim, a)).map(|c| (a, c)))
        .min_by(|x, y| x.1.dist(from).total_cmp(&y.1.dist(from)))
}

/// Армии стороны штаба `hq` (все, не только подчинённые).
fn side_armies(sim: &Sim, hq: u32) -> Vec<u32> {
    let side = sim.world.hqs[hq as usize].side;
    (0..sim.world.hqs.len() as u32).filter(|&h| sim.world.hqs[h as usize].echelon == Echelon::Army && sim.world.hqs[h as usize].side == side).collect()
}

/// Угроза армии 0…1: доля отрезанных дивизий, при открытом фланге не меньше половины.
fn threat(sim: &Sim, pic: Option<&Picture>, army: u32) -> f64 {
    let flank = pic.is_some_and(|p| p.open_flanks.contains(&army));
    cut_share(sim, army).unwrap_or(0.0).max(if flank { 0.5 } else { 0.0 })
}

/// Ось армии: ось её задачи; нет — к объекту фронта; нет и его — к ближайшему противнику.
fn army_axis(sim: &Sim, p: &Profile, army: u32, c: XY) -> Option<XY> {
    if let Some(d) = sim.command.intent.get(army as usize).and_then(Option::as_ref) {
        if let (Some(a), Some(b)) = (d.axis.first(), d.axis.last()) { if a.dist(*b) > 1e-6 { return Some(XY::new(b.x - a.x, b.y - a.y)); } }
    }
    let side = sim.world.hqs[army as usize].side;
    let to = profile_objective_xy(sim, p).filter(|o| o.dist(c) > 1e-6).or_else(|| {
        sim.world.divisions.iter().filter(|d| d.side != side && !d.state.out()).map(|d| d.vars.pos).min_by(|a, b| a.dist(c).total_cmp(&b.dist(c)))
    })?;
    Some(XY::new(to.x - c.x, to.y - c.y))
}

/// Вариант «поставить задачу» армии вне истории (спецификация, раздел 2.2): ближайший объект плана фронта впереди в
/// полосе армии (к оси не больше 60°), ещё у противника (своих в пределах соприкосновения нет), не дальше `reachDays`
/// суточных переходов; нет такого — ближайший населённый пункт (центр кольца) или мост у точки суточного перехода по
/// оси (не дальше `GROUND_KM`), нет и их — сама точка. Пункт по местности — только в районе операции фронта: не
/// дальше `intent.leaveKm` от объекта плана (вне зон изменённого замысла) и впереди армии, к ближайшему противнику;
/// такого нет — «занять оборону» у ближайшего населённого пункта не дальше `DEFEND_KM` от центра армии, нет его — на месте.
pub fn assign(sim: &Sim, p: &Profile, army: u32) -> Option<Choice> {
    let w = &sim.world;
    let r = &sim.rules;
    let ds = divisions_of(sim, army);
    if ds.is_empty() { return None; }
    let c = place(sim, Target::Hq(army));
    let ax = army_axis(sim, p, army, c)?;
    let al = (ax.x * ax.x + ax.y * ax.y).sqrt();
    if al < 1e-9 { return None; }
    let rate = ds.iter().map(|&i| r.enemy_territory_km_day[w.divisions[i].params.mobility as usize]).sum::<f64>() / ds.len() as f64;
    let side = w.hqs[army as usize].side;
    let ours = |g: XY| w.divisions.iter().any(|d| d.side == side && !d.state.out() && d.vars.pos.dist(g) <= r.contact_km);
    let front = w.hqs[army as usize].parent.unwrap_or(army);
    let plan = intent::plan_objectives(sim, front).into_iter().filter(|&g| {
        let d = c.dist(g);
        d > r.contact_km && d <= r.intent.reach_days * rate && ((g.x - c.x) * ax.x + (g.y - c.y) * ax.y) / (d * al) >= AHEAD_COS && !ours(g) && !intent::intervene::banned(sim, army, g)
    }).min_by(|a, b| c.dist(*a).total_cmp(&c.dist(*b)));
    // район операции фронта: не дальше leaveKm от объекта его плана (вне зон изменённого замысла армии) и впереди
    // армии — к ближайшему противнику
    let objectives: Vec<XY> = intent::plan_objectives(sim, front).into_iter().filter(|&g| !intent::intervene::banned(sim, army, g)).collect();
    let enemy = w.divisions.iter().filter(|d| d.side != side && !d.state.out()).map(|d| d.vars.pos).min_by(|a, b| a.dist(c).total_cmp(&b.dist(c)));
    let admissible = |g: XY| !intent::intervene::banned(sim, army, g) && objectives.iter().any(|o| o.dist(g) <= r.intent.leave_km)
        && enemy.is_some_and(|e| (g.x - c.x) * (e.x - c.x) + (g.y - c.y) * (e.y - c.y) > 0.0);
    let pr = &sim.theatre.proj;
    let areas: Vec<(XY, String)> = sim.theatre.areas.iter().filter(|a| !a.ring.is_empty()).map(|a| {
        let v: Vec<XY> = a.ring.iter().map(|x| pr.to_xy(*x)).collect();
        let n = v.len() as f64;
        (XY::new(v.iter().map(|x| x.x).sum::<f64>() / n, v.iter().map(|x| x.y).sum::<f64>() / n), a.name.clone())
    }).collect();
    let (at, from_plan, defend, what) = match plan {
        Some(g) => (g, true, false, "объект плана фронта".to_string()),
        None => {
            let q = XY::new(c.x + ax.x / al * rate, c.y + ax.y / al * rate);
            let bridges = sim.theatre.bridges.iter().map(|b| (b.pos, b.name.clone()));
            let ground = areas.iter().cloned().chain(bridges).filter(|x| x.0.dist(q) <= GROUND_KM && admissible(x.0)).min_by(|a, b| a.0.dist(q).total_cmp(&b.0.dist(q)));
            match ground {
                Some((at, n)) => (at, false, false, n),
                None if admissible(q) => (q, false, false, "рубеж суточного перехода".to_string()),
                // в районе операции задачи нет — оборона у ближайшего населённого пункта не дальше DEFEND_KM (нет такого — на месте)
                None => {
                    let (at, n) = areas.iter().filter(|x| x.0.dist(c) <= DEFEND_KM && !intent::intervene::banned(sim, army, x.0)).min_by(|a, b| a.0.dist(c).total_cmp(&b.0.dist(c))).cloned()
                        .unwrap_or((c, "на месте".to_string()));
                    (at, false, true, format!("нет задачи в полосе фронта — оборона ({n})"))
                }
            }
        }
    };
    let rival = p.rival.as_deref().and_then(|id| sim.rules.commanders.profiles.iter().find(|q| q.id == id)).and_then(|rp| profile_objective_xy(sim, rp))
        .map_or(0.0, |o| if at.dist(o) < c.dist(o) { ASSIGN_RIVAL } else { 0.0 });
    Some(Choice {
        kind: Kind::Assign { army, at, from_plan, defend }, label: format!("Поставить {} задачу: {what}", name(sim, army)),
        contrib: contrib(&[(Motive::Task, ASSIGN_TASK), (Motive::Rival, rival), (Motive::Preserve, ASSIGN_PRESERVE)]),
        uncertainty: if from_plan { ASSIGN_UNC_PLAN } else { ASSIGN_UNC_GROUND }, losses: ASSIGN_LOSS,
        rule: if from_plan { RULE_ASSIGN_PLAN } else if defend { RULE_ASSIGN_DEFEND } else { RULE_ASSIGN_GROUND },
    })
}

fn contrib(parts: &[(Motive, f64)]) -> Motives {
    let mut m = [0.0; 7];
    for &(k, v) in parts { m[k as usize] = v.clamp(-1.0, 1.0); }
    Motives(m)
}

/// Армии нужна задача (директивы ей в пути нет): её нет, она выполнена (армия у цели в пределах соприкосновения) или потеряла смысл; неспособная
/// армия новой задачи не получает.
pub fn needs_task(sim: &Sim, army: u32) -> bool {
    // директива армии в пути — задача уже поставлена
    if sim.command.in_transit.iter().any(|(_, d)| d.to == Target::Hq(army)) { return false; }
    let Some(d) = sim.command.intent.get(army as usize).and_then(Option::as_ref) else { return true };
    let t = intent::of_directive(d.issued, d);
    if intent::done(sim, army, &t) { return true; }
    let chain = Chain { owner: army, tasks: Vec::new(), next: 0, start: None };
    !matches!(intent::sense(sim, &chain, &t), Ok(()) | Err(Reason::Unfit))
}

pub fn options_su(sim: &Sim, hq: u32, p: &Profile, pic: &Picture) -> Vec<Choice> {
    if !crate::commander::decide::for_strayed(sim, hq) { return plan_options(sim, hq, p, pic, false); }
    let off = strayed(sim, pic);
    if off.is_empty() { return Vec::new(); }
    let mut view = pic.clone();
    view.armies.retain(|a| off.contains(&a.hq));
    // задачу армии без задачи ставит штаб фронта каждый час (decide.rs, `staff`) — среди вариантов её нет
    plan_options(sim, hq, p, &view, true)
}

/// Варианты по картине `pic`; `strayed` — «история как замысел»: в картине только армии вне истории, без переноса
/// главного удара, котлы — только те, что замыкают эти армии.
fn plan_options(sim: &Sim, hq: u32, p: &Profile, pic: &Picture, strayed: bool) -> Vec<Choice> {
    let mut out = vec![Choice {
        kind: Kind::Continue, label: "Продолжать по плану".into(), contrib: contrib(&[(Motive::Task, CONT_TASK)]),
        uncertainty: CONT_UNC, losses: CONT_LOSS, rule: "ПУ-43: выполнять задачу, поставленную старшим начальником",
    }];

    // армии главного удара: по замыслу старшего, иначе первый эшелон
    let named: Vec<u32> = sim.command.intent.get(hq as usize).and_then(Option::as_ref).map(|d| d.main_blow.clone()).unwrap_or_default();
    // подвижные группы (до ввода и введённые) в главный удар не входят: их марш — не продвижение главного удара
    let tank = |a: &ArmyView| matches!(role(sim, a.hq), Role::Mobile | Role::Committed);
    let main: Vec<&ArmyView> = pic.armies.iter().filter(|a| !tank(a) && if named.is_empty() { role(sim, a.hq) == Role::First } else { named.contains(&a.hq) }).collect();
    let main_adv = main.iter().map(|a| a.advance_km).fold(0.0, f64::max);
    let broke = main.iter().any(|a| a.broke_through);
    let mobile: Vec<&ArmyView> = pic.armies.iter().filter(|a| role(sim, a.hq) == Role::Mobile).collect();

    // подвижная группа: ввод с глубины ввода вторых эшелонов (главная полоса прорвана) или по сроку ввода
    // (`tankCommitFallbackHours`, как у штаба фронта); без прорыва тактической зоны — неопределённее; ожидание — пока нет прорыва
    let deep = main_adv >= sim.rules.doctrine_su.commit_depth_km;
    let late = |m: &ArmyView| sim.world.tick.saturating_sub(sim.command.since(Target::Hq(m.hq))) as f64 >= sim.rules.doctrine_su.tank_commit_fallback_hours;
    let ready: Vec<&&ArmyView> = mobile.iter().filter(|m| deep || late(m)).collect();
    if !ready.is_empty() {
        let rival = if pic.rival.is_some() { COMMIT_RIVAL } else { 0.0 };
        for m in &ready {
            let (unc, loss, task, rule) = if broke { (COMMIT_UNC_BROKE, COMMIT_LOSS_BROKE, COMMIT_TASK + COMMIT_TASK_BROKE, RULE_COMMIT) }
                else if late(m) { (COMMIT_UNC_LATE, COMMIT_LOSS_OPEN, COMMIT_TASK, RULE_COMMIT_LATE) }
                else { (COMMIT_UNC_OPEN, COMMIT_LOSS_OPEN, COMMIT_TASK, RULE_COMMIT) };
            out.push(Choice {
                kind: Kind::CommitMobile { hq: m.hq }, label: format!("Ввести {} в прорыв", name(sim, m.hq)),
                contrib: contrib(&[(Motive::Task, task), (Motive::Rival, rival), (Motive::Preserve, COMMIT_PRESERVE)]),
                uncertainty: unc, losses: loss, rule,
            });
        }
        if !broke {
            let rival = match &pic.rival { Some(r) if pic.to_objective_km.is_some_and(|mine| r.to_objective_km < mine) => WAIT_RIVAL, _ => 0.0 };
            out.push(Choice {
                kind: Kind::WaitMobile, label: "Не вводить подвижную группу до прорыва".into(),
                contrib: contrib(&[(Motive::Preserve, WAIT_PRESERVE), (Motive::Task, WAIT_TASK), (Motive::Rival, rival)]),
                uncertainty: WAIT_UNC, losses: WAIT_LOSS, rule: "ПУ-43: ввод подвижных групп — после прорыва тактической зоны обороны",
            });
        }
    }

    // главный удар переносится на армии, вырвавшиеся вперёд
    if !strayed && !main.is_empty() {
        let to: Vec<u32> = pic.armies.iter().filter(|a| !tank(a) && !main.iter().any(|m| m.hq == a.hq) && a.advance_km > main_adv * SHIFT_RATIO && a.advance_km - main_adv >= SHIFT_MIN_LEAD_KM).map(|a| a.hq).collect();
        if !to.is_empty() {
            out.push(Choice {
                kind: Kind::ShiftMainBlow { to }, label: "Перенести главный удар на добившиеся успеха армии".into(),
                contrib: contrib(&[(Motive::Task, SHIFT_TASK), (Motive::Preserve, SHIFT_PRESERVE)]),
                uncertainty: SHIFT_UNC, losses: SHIFT_LOSS, rule: "ПУ-43: усилие наращивается на направлении, где достигнут успех",
            });
        }
    }

    // поворот к объекту соперника
    if let Some(rp) = p.rival.as_deref().and_then(|r| sim.rules.commanders.profiles.iter().find(|q| q.id == r)) {
        if p.objective.is_some() {
            if let Some(at) = profile_objective_xy(sim, rp).filter(|&at| task_goal(sim, hq).is_some_and(|g| g.dist(at) > sim.rules.commanders.options.turn_km)) {
                let near = |a: &ArmyView| divisions_of(sim, a.hq).into_iter().map(|i| sim.world.divisions[i].vars.pos.dist(at)).min_by(f64::total_cmp);
                let limit = sim.rules.commanders.options.turn_km;
                let best = pic.armies.iter().filter_map(|a| near(a).filter(|&d| d < limit).map(|d| (a, d)))
                    .min_by(|x, y| {
                        let not_tank = |a: &ArmyView| !matches!(role(sim, a.hq), Role::Mobile | Role::Committed);
                        not_tank(x.0).cmp(&not_tank(y.0)).then(x.1.total_cmp(&y.1))
                    });
                if let Some((a, _)) = best {
                    out.push(Choice {
                        kind: Kind::TurnToRival { hq: a.hq, at }, label: format!("Повернуть {} к объекту соперника", name(sim, a.hq)),
                        contrib: contrib(&[(Motive::Rival, TURN_RIVAL), (Motive::Task, TURN_TASK)]),
                        uncertainty: TURN_UNC, losses: TURN_LOSS, rule: "ПУ-43: смена направления усилий — по решению командующего с уведомлением старшего",
                    });
                }
            }
        }
    }

    // котлы с малым просветом
    for (i, k) in pic.pockets.iter().enumerate() {
        if strayed && !k.by.iter().any(|h| pic.armies.iter().any(|a| a.hq == *h)) { continue; }
        if k.gap_km < sim.rules.commanders.options.encircle_gap_km {
