            let open = in_sight.iter().any(|&e| {
                let p = w.divisions[e].vars.pos;
                if pos.iter().map(|q| q.dist(p)).fold(f64::INFINITY, f64::min) > recon { return false; }
                let d = c.dist(p);
                d > 1e-9 && ((p.x - c.x) * u.x + (p.y - c.y) * u.y) / d < 0.5 && !covered(p)
            });
