pub struct Profile {
    pub id: String,
    pub name: String,
    pub hqs: Vec<String>,
    pub traits: Traits,
    pub motives: Motives,
    /// Id профиля соперника (заданное состязание).
    pub rival: Option<String>,
    /// Id объекта из объектов сценария, к которому тянется командующий.
    pub objective: Option<String>,
}

/// Число узла `{ value, range }` по пути через точку; значение вне `range` — ошибка с путём.
fn num(c: &Value, path: &str) -> Result<f64, String> {
    let mut cur = c;
    for k in path.split('.') { cur = cur.get(k).ok_or_else(|| format!("правила командующих: нет поля {path}"))?; }
    let v = cur.get("value").and_then(Value::as_f64).ok_or_else(|| format!("правила командующих: {path} — не число"))?;
    if let Some(r) = cur.get("range").and_then(Value::as_array) {
        if let (Some(lo), Some(hi)) = (r.first().and_then(Value::as_f64), r.get(1).and_then(Value::as_f64)) {
            if v < lo || v > hi { return Err(format!("правила командующих: commanders.{path} = {v} вне пределов [{lo}; {hi}]")); }
        }
    }
    Ok(v)
}

/// Поле `commanders` хода; `None` — командующих нет.
pub fn describe(sim: &Sim) -> Option<Value> {
    if sim.commanders.list.is_empty() { return None; }
    let w = &sim.world;
    let pr = &sim.theatre.proj;
    let id = |h: u32| w.hqs[h as usize].id.clone();
    let out: Vec<Value> = sim.commanders.list.iter().map(|c| {
        let p = &sim.rules.commanders.profiles[c.profile];
        let mut traits = Map::new();
        for (k, _) in TRAITS {
            let node = sim.rules.commanders.raw.pointer(&format!("/profiles/{}/traits/{k}", p.id));
            let f = |key: &str| node.and_then(|n| n.get(key)).cloned().unwrap_or(Value::Null);
            traits.insert(k.into(), json!({ "value": f("value"), "range": f("range"), "source": f("source"), "confidence": f("confidence") }));
        }
        let snapshots: Vec<Value> = c.snapshots.iter().map(|s| json!({
            "tick": s.tick, "motives": motives(&s.motives), "mood": { "confidence": r3(s.mood.confidence), "stress": r3(s.mood.stress) }, "intent": s.intent,
            "picture": {
                "armies": s.picture.armies.iter().map(|a| json!({
                    "hq": id(a.hq), "advanceKm": r3(a.advance_km), "strength": r3(a.strength), "enemyEst": r3(a.enemy_est), "enemyTrue": r3(a.enemy_true),
                    "toObjectiveKm": a.to_objective_km.map(r3), "brokeThrough": a.broke_through,
                })).collect::<Vec<_>>(),
                "rival": s.picture.rival.as_ref().map(|r| json!({ "hq": id(r.hq), "toObjectiveKm": r3(r.to_objective_km), "asOf": r.as_of })),
                "openFlanks": s.picture.open_flanks.iter().map(|&h| id(h)).collect::<Vec<_>>(),
                "pockets": s.picture.pockets.iter().map(|k| json!({ "center": pr.to_lnglat(k.center), "enemyEst": r3(k.enemy_est), "gapKm": r3(k.gap_km) })).collect::<Vec<_>>(),
                "enemyReserves": s.picture.enemy_reserves.iter().map(|(at, n)| json!({ "at": pr.to_lnglat(*at), "strength": r3(*n) })).collect::<Vec<_>>(),
                "toObjectiveKm": s.picture.to_objective_km.map(r3),
            },
        })).collect();
        let decisions: Vec<Value> = c.decisions.iter().map(|d| json!({
            "tick": d.tick, "trigger": d.trigger, "chosen": d.chosen, "why": d.why,
            "options": d.options.iter().map(|o| option(sim, o)).collect::<Vec<_>>(),
        })).collect();
        json!({
            "hq": id(c.hq), "profile": p.id, "name": p.name, "side": w.hqs[c.hq as usize].side,
            "traits": traits, "baseMotives": motives(&p.motives), "rival": p.rival, "objective": p.objective,
            "snapshots": snapshots, "decisions": decisions,
        })
    }).collect();
    Some(Value::Array(out))
}

fn motives(m: &Motives) -> Value {
    let mut o = Map::new();
    for (i, k) in MOTIVES.iter().enumerate() { o.insert((*k).into(), json!(r3(m.0[i]))); }
    Value::Object(o)
}

fn option(sim: &Sim, o: &Scored) -> Value {
    let (name, at) = kind(&o.choice.kind);
    // деблокирование: выручаемая армия и армия, которая выручает (получатель директивы)
    let (army, by) = match &o.choice.kind {
        Kind::Relief { army, by, .. } => (Some(sim.world.hqs[*army as usize].id.clone()), Some(sim.world.hqs[*by as usize].id.clone())),
        Kind::Assign { army, .. } => (Some(sim.world.hqs[*army as usize].id.clone()), None),
        _ => (None, None),
    };
    let mut v = json!({
        "kind": name, "label": o.choice.label, "rule": o.choice.rule, "army": army, "by": by,
        "target": at.map(|p| sim.theatre.proj.to_lnglat(p)),
        "parts": motives(&o.parts), "penalty": r3(o.penalty), "bonus": r3(o.bonus), "total": r3(o.total),
        "mind": o.mind.as_ref().map(|m| json!({ "hours": m.hours, "advanceKm": r3(m.advance_km), "losses": r3(m.losses), "encircled": r3(m.encircled) })),
    });
    // задача армии вне истории: объект плана или пункт по местности
    if let Kind::Assign { from_plan, defend, .. } = &o.choice.kind {
        v["fromPlan"] = json!(from_plan);
        if *defend { v["defend"] = json!(true); }
    }
    v
}

/// Разграничительная линия директивы игрока: сосед (штаб, если назван) и ломаная.
pub struct BoundaryIn {
    #[serde(default)]
    pub neighbour: Option<String>,
    pub line: Vec<LngLat>,
}

/// Команда управления игрока на ход (до распоряжений и приказов): взять штаб, вернуть, ответ на запросы отхода,
/// подать историческую директиву.
pub enum CommandOp {
    Take { hq: String },
    Release { id: String },
    Permit { hq: String, yes: bool },
    Historical { id: String },
    /// Директива игрока с полной структурой (пункт управления).
    Directive { directive: PlayerDirective },
}

pub struct Game {
    pub mode: Mode,
    /// Поданные исторические директивы (id).
    pub issued: std::collections::HashSet<String>,
    /// Исторические директивы игрока, поданные на будущий час: (час, директива).
    pub pending: Vec<(u32, crate::command::directive::Directive)>,
    pub sim: Sim,
    pub meta: Meta,
    pub frames: Vec<Vec<Value>>,
    pub player: Side,
    /// Стороны под внешним управлением (игрок и, если есть, штаб противника на языковой модели вне ядра): их
    /// исторические приказы сняты, приказы им отдаёт `order`.
    pub free: Vec<Side>,
    /// Час, с которого командует игрок.
    pub takeover: u32,
    /// До какого часа можно вести игру (по умолчанию — конец сценария; игра может идти и дольше, до своего срока).
    pub limit: u32,
    /// Резервы стороны игрока, ждущие ввода: индекс дивизии → с какого часа готов (ввод по сценарию).
    pub reserves: BTreeMap<u32, u32>,
    /// Противник — штабы-агенты (верхняя инстанция — агент).
    pub enemy_agents: bool,
    /// Сыгранные ходы по порядку (`play_turn`): повтор с того же начала даёт тот же мир.
    pub log: Vec<TurnIn>,
    /// Снимки игры каждые `SNAP_EVERY` ходов (с хода 0): возврат к ходу — ближайший снимок и досчёт повтором журнала.
    pub snaps: Vec<GameSnap>,
    /// Команды, поданные между ходами (`between_op`): уйдут в `TurnIn::between` следующего хода.
    pub between: Vec<CommandOp>,
}

/// Ход: `hours` шагов (не дальше `limit`).
pub fn advance(&mut self, hours: u32) {
    let left = self.limit.saturating_sub(self.hour());
    for _ in 0..hours.min(left) {
        let now = self.hour();
        let due: Vec<_> = { let (d, rest): (Vec<_>, Vec<_>) = std::mem::take(&mut self.pending).into_iter().partition(|(at, _)| *at <= now); self.pending = rest; d };
        for (_, d) in due { crate::command::passing::issue(&mut self.sim, d, now); }
        self.sim.step();
        self.frames.push(trace::frame(&self.sim));
    }
}

/// Команда управления на ход.
pub fn command(&mut self, c: &CommandOp) -> Result<(), String> {
    if self.mode == Mode::Legacy { return Err("команды управления — в режимах «агенты» и «гибрид»".into()); }
    self.run_op(c)
}

/// Команда управления из JSON: неразборчивая — ошибка этой команды, а не всего хода.
pub fn command_json(&mut self, v: &Value) -> Result<(), String> {
    let c: CommandOp = serde_json::from_value(v.clone()).map_err(|e| format!("команда {v}: {e}"))?;
    self.command(&c)
}

/// Состояние управления стороны игрока: режим, кто решает за штабы, изъятые через голову дивизии, запросы на
/// отход, исторические директивы верхней инстанции (поданные — `issued`).
fn command_state(&self) -> Value {
    use crate::command::directive::Target;
    let w = &self.sim.world;
    let c = &self.sim.command;
    let mode = match self.mode { Mode::Legacy => "legacy", Mode::Agents => "agents", Mode::Hybrid => "hybrid", Mode::Commanders => "commanders", Mode::Intent => "intent" };
    let mine = |h: usize| w.hqs[h].side == self.player;
    let hqs: Vec<Value> = (0..w.hqs.len()).filter(|&h| mine(h) && c.control.len() > h)
        // ведомый: изъятый через голову или (история как замысел) взятый директивой игрока — у него есть «вернуть»
        .map(|h| serde_json::json!({ "id": w.hqs[h].id, "control": c.control[h], "led": c.led_hq[h] || self.sim.intent.led.get(h) == Some(&true) })).collect();
    let led: Vec<&str> = (0..w.divisions.len()).filter(|&i| c.led_div.get(i).copied().unwrap_or(false) && w.divisions[i].side == self.player).map(|i| w.divisions[i].id.as_str()).collect();
    let req = |r: &crate::command::control::Request| serde_json::json!({ "hq": w.hqs[r.hq as usize].id, "division": w.divisions[r.division as usize].id, "tick": r.tick, "answer": r.answer });
    let requests: Vec<Value> = c.requests.iter().filter(|r| mine(r.hq as usize)).map(req).collect();
    // запросы противника (журнал посредника): с часом ответа
    let enemy_requests: Vec<Value> = c.requests.iter().filter(|r| !mine(r.hq as usize))
        .map(|r| { let mut v = req(r); if r.answer.is_some() { v["answeredAt"] = serde_json::json!(r.answered_at); } v }).collect();
    let top = w.hqs.iter().position(|h| h.side == self.player && h.echelon == crate::model::Echelon::HighCommand);
    let target = |t: Target| match t { Target::Hq(h) => w.hqs[h as usize].id.clone(), Target::Division(i) => w.divisions[i as usize].id.clone() };
    let historical: Vec<Value> = self.sim.historical.iter().filter(|(_, d)| Some(d.from as usize) == top)
        .map(|(at, d)| serde_json::json!({ "id": d.id, "at": at, "to": target(d.to), "task": d.task, "form": d.form, "note": d.note, "issued": self.issued.contains(&d.id) })).collect();
    // директивы верховного командования противника (журнал посредника): от его штабов верхней инстанции
    let enemy_historical: Vec<Value> = self.sim.historical.iter()
        .filter(|(_, d)| !mine(d.from as usize) && w.hqs[d.from as usize].echelon == crate::model::Echelon::HighCommand)
        .map(|(at, d)| serde_json::json!({ "id": d.id, "at": at, "from": w.hqs[d.from as usize].id, "to": target(d.to), "task": d.task, "form": d.form, "note": d.note })).collect();
    serde_json::json!({ "mode": mode, "hqs": hqs, "led": led, "requests": requests, "enemyRequests": enemy_requests, "historical": historical, "enemyHistorical": enemy_historical })
}

  /// Директива игрока штабу или дивизии. Получатель ниже прямых подчинённых верхней инстанции — приказ через голову
  /// (ПУ-39 ст. 93): он изъят из замысла старшего, каждый пропущенный штаб получает извещение.
  pub fn directive(&mut self, p: &PlayerDirective) -> Result<(), String> {
      use crate::command::control::{DocKind, Document};
      use crate::command::directive::{Directive, Line, Target};
      if self.mode == Mode::Legacy { return Err("директивы — в режимах «агенты» и «гибрид»".into()); }
      let top = self.top()?;
      let w = &self.sim.world;
      let (to, parent) = if let Some(h) = w.hqs.iter().position(|h| h.id == p.to) {
          if w.hqs[h].side != self.player { return Err(format!("{} — не под нашим управлением", p.to)); }
          if h as u32 == top { return Err("верхней инстанции приказов не отдают".into()); }
          (Target::Hq(h as u32), w.hqs[h].parent)
      } else if let Some(i) = w.divisions.iter().position(|d| d.id == p.to) {
          if w.divisions[i].side != self.player { return Err(format!("{} — не под нашим управлением", p.to)); }
          if w.divisions[i].state.out() && w.divisions[i].state != crate::model::State::Pending { return Err(format!("{} выбыла", w.divisions[i].name)); }
          (Target::Division(i as u32), Some(w.divisions[i].hq))
      } else { return Err(format!("нет штаба или дивизии {}", p.to)); };
      // отдающий (пункт управления): верхняя инстанция или штаб, взятый игроком; получатель — в его подчинении
      let issuer = match p.from.as_deref() {
          None => top,
          Some(f) => {
              let k = w.hqs.iter().position(|h| h.id == f && h.side == self.player).ok_or_else(|| format!("нет штаба {f} стороны игрока"))? as u32;
              if k != top && self.sim.command.control[k as usize] != crate::command::control::Control::Player { return Err(format!("{} не под управлением игрока — сначала взять", w.hqs[k as usize].name)); }
              let mut x = match to { Target::Hq(h) => w.hqs[h as usize].parent, Target::Division(i) => Some(w.divisions[i as usize].hq) };
              let mut ok = false;
              for _ in 0..8 { match x { Some(q) if q == k => { ok = true; break; } Some(q) => x = w.hqs[q as usize].parent, None => break } }
              if !ok { return Err(format!("{} не в подчинении {}", p.to, w.hqs[k as usize].name)); }
              k
          }
      };
      let tick = self.hour();
      // история как замысел: директива штабу не под командованием игрока — он и его подчинённые с истории («под
      // командованием игрока»), решают его командующий и штаб по директиве игрока; диспетчер им больше не подаёт
      if let Target::Hq(h) = to {
          if self.mode == Mode::Intent && !crate::intent::player_over(&self.sim, h) {
              let n = self.sim.world.hqs.len();
              self.sim.intent.led.resize(n, false);
              self.sim.intent.led[h as usize] = true;
              crate::intent::take(&mut self.sim, h);
              let name = self.sim.world.hqs[h as usize].name.clone();
              self.sim.journal.push(crate::world::Event { tick, agent: u32::MAX, text: format!("{name} взят под управление игрока: директива вместо истории, решают его командующий и штаб") });
          }
      }
      // «гибрид»: своя директива штабу, которого ведёт сценарий, — история кончилась: его поддерево решают агенты
      if let Target::Hq(h) = to {
          use crate::command::control::Control;
          if self.sim.command.control[h as usize] == Control::Script {
              let w = &self.sim.world;
              let under = |mut k: usize| { for _ in 0..8 { if k == h as usize { return true; } match w.hqs[k].parent { Some(q) => k = q as usize, None => return false } } false };
              let sub: Vec<usize> = (0..w.hqs.len()).filter(|&k| under(k)).collect();
              for k in sub { if self.sim.command.control[k] == Control::Script { self.sim.command.control[k] = Control::Agent; self.sim.command.last_cycle[k] = tick; } }
              self.sim.documents.push(Document { tick, hq: h, kind: DocKind::Notice, to: Vec::new(), text: "директива игрока вместо исторической: штаб и его подчинённые сходят со сценария, решают агенты".into(), rule: None });
          }
      }
      // через голову: пропущенные штабы — от непосредственного начальника до штаба под отдающим
      let top = issuer;
      if parent != Some(top) {
          match to { Target::Hq(h) => self.sim.command.led_hq[h as usize] = true, Target::Division(i) => self.sim.command.led_div[i as usize] = true }
          let mut k = parent;
          let name = |sim: &Sim| match to { Target::Hq(h) => sim.world.hqs[h as usize].name.clone(), Target::Division(i) => sim.world.divisions[i as usize].name.clone() };
          let who = name(&self.sim);
          while let Some(h) = k {
              if h == top { break; }
              let boss = self.sim.world.hqs[top as usize].name.clone();
              self.sim.documents.push(Document { tick, hq: h, kind: DocKind::Notice, to: vec![p.to.clone()], text: format!("приказ через голову: {who} — ведёт {boss} (ПУ-39 ст. 93)"), rule: Some("ПУ-39 ст. 93".into()) });
              k = self.sim.world.hqs[h as usize].parent;
          }
          if let Some(b) = parent { self.sim.journal.push(crate::world::Event { tick, agent: u32::MAX, text: format!("{who} получил приказ через голову, доносит «{}»", self.sim.world.hqs[b as usize].name) }); }
      }
      let xy = |q: &LngLat| self.sim.theatre.proj.to_xy(*q);
      let hq_ix = |id: &str| self.sim.world.hqs.iter().position(|h| h.id == id && h.side == self.player).map(|k| k as u32).ok_or_else(|| format!("нет штаба {id} стороны игрока"));
      let main_blow = p.main_blow.iter().map(|x| hq_ix(x)).collect::<Result<Vec<_>, _>>()?;
      let reserve = p.reserve.iter().map(|x| hq_ix(x)).collect::<Result<Vec<_>, _>>()?;
      let junction = p.junction.as_deref().map(hq_ix).transpose()?;
      let boundaries = p.boundaries.iter().filter(|b| b.line.len() >= 2).map(|b| Ok((b.neighbour.as_deref().map(hq_ix).transpose()?, b.line.iter().map(xy).collect()))).collect::<Result<Vec<_>, String>>()?;
      let d = Directive {
          id: format!("игрок:{}:{}", p.to, tick), from: top, to, form: p.form, task: p.task,
          axis: p.axis.iter().map(xy).collect(),
          immediate: p.immediate.as_ref().map(|l| Line { pts: l.iter().map(xy).collect(), by: p.immediate_by }),
          subsequent: p.subsequent.as_ref().map(|l| Line { pts: l.iter().map(xy).collect(), by: p.subsequent_by }),
          boundaries, main_blow, reserve, junction, hasty: false, ready: false, rule: None, issued: 0,
          note: if p.note.is_empty() { "директива игрока".into() } else { p.note.clone() },
// … строки 522–534

/// Дивизии штаба (и подчинённых ему штабов), ещё участвующие в операции.
pub fn divisions_of(&self, hq: u32) -> Vec<u32> {
    let w = &self.sim.world;
    let under = |mut h: u32| -> bool {
        for _ in 0..8 {
            if h == hq { return true; }
            match w.hqs[h as usize].parent { Some(p) => h = p, None => return false }
        }
        false
    };
    w.divisions.iter().enumerate()
        .filter(|(_, d)| under(d.hq) && !matches!(d.state, crate::model::State::Destroyed | crate::model::State::Merged))
        .map(|(i, _)| i as u32).collect()
}

/// Противник — штабы-агенты: его штабы решают по своей логике ступеней, верхняя инстанция — агент: подаёт
/// исторические решения в их часы (уже наступившие — доведены, как приказы на начало) и отвечает на запросы отхода
/// по правилу; его приказы сценария при доставке пропускаются (штабы не на сценарии).
pub fn enemy_agents(&mut self) {
    use crate::command::control::Control;
    if self.enemy_agents { return; }
    let enemy = other_side(self.player);
    crate::command::control::agents_side(&mut self.sim, enemy);
    for (k, h) in self.sim.world.hqs.iter().enumerate() { if h.side == enemy && h.echelon == crate::model::Echelon::HighCommand { self.sim.command.control[k] = Control::Agent; } }
    self.sim.sources[crate::staff::side_idx(enemy)] = crate::staff::Source::Script;
    let now = self.hour();
    if self.mode == Mode::Commanders { crate::commander::enable(&mut self.sim, enemy); }
    for (at, mut d) in crate::command::control::historical_for(&mut self.sim, enemy, None, false) {
        // немецкие командующие: директивы Гитлера после начала не подаются (он — агент, решает сам)
        if self.mode == Mode::Commanders && enemy == Side::De && at > now { continue; }
        if at <= now { d.ready = true; crate::command::passing::issue(&mut self.sim, d, now); } else { self.pending.push((at, d)); }
    }
    self.enemy_agents = true;
}

/// Противник — на истории как замысле: штабы — агенты, верхняя инстанция — агент, командующие и цепочки его армий
/// (исторические директивы подаёт `intent::step`, не игра); его приказы сценария при доставке пропускаются.
pub fn enemy_intent(&mut self) {
    if self.enemy_agents { return; }
    if self.mode == Mode::Legacy {
        let tick = self.hour();
        self.sim.journal.push(crate::world::Event { tick, agent: u32::MAX, text: "история как замысел у противника — не в режиме «как сейчас»: пропущено".into() });
        return;
    }
    let enemy = other_side(self.player);
    // управление ровно как в прогоне: command_mode("intent") — командующие, цепочки, штабы по сценарию и армии-агенты
    let _ = crate::command::control::command_mode(&mut self.sim, "intent", enemy);
    self.sim.sources[crate::staff::side_idx(enemy)] = crate::staff::Source::Script;
    self.enemy_agents = true;
}

/// Историческая директива сценария от имени игрока: в свой час (не раньше текущего). До начала операции — уже
/// доведена до дивизий. В «гибриде» поддерево получателя ведут приказы сценария.
pub fn issue_historical(&mut self, id: &str) -> Result<(), String> {
    self.top()?;
    if !self.sim.historical.iter().any(|(_, d)| d.id == id) { return Err(format!("нет исторической директивы {id} стороны игрока")); }
    // приказы сценария, прошедшие до перевода поддерева на сценарий, не вернуть — в «гибриде» только до первого хода
    if self.mode == Mode::Hybrid && self.hour() > self.takeover { return Err("в «гибриде» исторические директивы подаются до первого хода".into()); }
    if !self.issued.insert(id.to_string()) { return Err(format!("директива {id} уже подана")); }
    let now = self.hour();
    let at_takeover = now == self.takeover;
    for (at, mut d) in crate::command::control::historical_for(&mut self.sim, self.player, Some(id), self.mode == Mode::Hybrid) {
        // поданная при передаче командования, уже действовавшая к этому часу — доведена (как приказы на начало сценария)
        if at_takeover && at <= now { d.ready = true; }
        if at <= now { crate::command::passing::issue(&mut self.sim, d, now); } else { self.pending.push((at, d)); }
    }
    Ok(())
}

/// Приказ игрока: доходит до дивизий штаба на ближайшем шаге (с задержкой уровня штаба). Возвращает число дивизий.
pub fn order(&mut self, o: &PlayerOrder) -> Result<usize, String> {
    let w = &self.sim.world;
    let (hq, to) = if let Some(h) = w.hqs.iter().position(|h| h.id == o.hq) {
        (h as u32, self.divisions_of(h as u32))
    } else if let Some(d) = w.divisions.iter().position(|d| d.id == o.hq) {
        if matches!(w.divisions[d].state, crate::model::State::Destroyed | crate::model::State::Merged) { return Err(format!("{} выбыла", w.divisions[d].name)); }
        (w.divisions[d].hq, vec![d as u32])
    } else {
        return Err(format!("нет штаба или дивизии {}", o.hq));
    };
    if !self.free.contains(&self.sim.world.hqs[hq as usize].side) { return Err(format!("{} — не под нашим управлением", o.hq)); }
    if w.hqs.iter().any(|h| h.id == o.hq && h.echelon == crate::model::Echelon::HighCommand) { return Err("верхней инстанции приказов не отдают".into()); }
    // в режимах штабов-агентов приказ игрока — директива; штаб противника на модели (вне ядра) — как раньше
    if self.mode != Mode::Legacy && self.sim.world.hqs[hq as usize].side == self.player {
        use crate::command::directive::{Form, Task};
        let task = match o.kind { OrderKind::Attack => Task::Attack, OrderKind::Defend | OrderKind::Hold => Task::Defend, OrderKind::Withdraw => Task::Withdraw, OrderKind::Move => Task::Move };
        let n = to.len();
        let (axis, immediate) = match o.target {
            None if matches!(task, Task::Attack | Task::Move | Task::Withdraw) => return Err("наступать, выдвигаться и отходить — с целью".into()),
            None => (vec![], None),
            Some(t) => {
                // рубеж через цель поперёк направления от центра войск — шириной их фронта, не меньше 6 км
                let pr = &self.sim.theatre.proj;
                let ps: Vec<crate::geo::XY> = to.iter().map(|&i| self.sim.world.divisions[i as usize].vars.pos).collect();
                let c = crate::geo::XY::new(ps.iter().map(|p| p.x).sum::<f64>() / ps.len() as f64, ps.iter().map(|p| p.y).sum::<f64>() / ps.len() as f64);
                let tx = pr.to_xy(t);
                let l = c.dist(tx).max(1e-6);
                let (ux, uy) = ((tx.x - c.x) / l, (tx.y - c.y) / l);
                let hw = ps.iter().map(|p| ((p.x - c.x) * -uy + (p.y - c.y) * ux).abs()).fold(3.0, f64::max);
                let a = pr.to_lnglat(crate::geo::XY::new(tx.x - uy * hw, tx.y + ux * hw));
                let b = pr.to_lnglat(crate::geo::XY::new(tx.x + uy * hw, tx.y - ux * hw));
                (vec![pr.to_lnglat(c), t], if to.len() > 1 { Some(vec![a, b]) } else { Some(vec![t]) })
            }
        };
        self.directive(&PlayerDirective { to: o.hq.clone(), task, form: o.form.unwrap_or(Form::Instruction), axis, immediate, subsequent: None, note: o.note.clone(), ..Default::default() })?;
        return Ok(n);
    }
    if to.is_empty() { return Err(format!("у штаба {} нет действующих дивизий", o.hq)); }
    let n = to.len();
    let target = o.target.map(|p| self.sim.theatre.proj.to_xy(p));
    let tick = self.hour();
    // в начало очереди: в очереди только приказы с часом не раньше текущего
    self.sim.script.insert(0, ScriptOrder {
        at: tick, hq, to, kind: o.kind, target, forced: false,
        note: if o.note.is_empty() { "приказ игрока".into() } else { o.note.clone() },
        follow: None, offset: Default::default(),
    });
    Ok(n)
}

/// Ответ игрока (верхней инстанции) на запросы отхода корпуса `hq`: да — дивизии отходят на следующий рубеж.
pub fn permit(&mut self, hq: &str, yes: bool) -> Result<(), String> {
    use crate::command::directive::{Directive, Form, Line, Target, Task};
    let h = self.sim.world.hqs.iter().position(|x| x.id == hq && x.side == self.player).ok_or_else(|| format!("нет штаба {hq} стороны игрока"))? as u32;
    let tick = self.hour();
    let open: Vec<usize> = (0..self.sim.command.requests.len()).filter(|&k| self.sim.command.requests[k].hq == h && self.sim.command.requests[k].answer.is_none()).collect();
    if open.is_empty() { return Err(format!("у {hq} нет запросов на отход")); }
    for k in open {
        self.sim.command.requests[k].answer = Some(yes);
        self.sim.command.requests[k].answered_at = tick;
        if !yes { continue; }
        let i = self.sim.command.requests[k].division;
        // рубеж, названный при запросе (доктрина), а не от нынешнего места
        let at = self.sim.command.requests[k].at;
        let d = Directive { id: format!("отход:{i}"), from: h, to: Target::Division(i), form: Form::Instruction, task: Task::Withdraw, axis: Vec::new(),
            immediate: Some(Line { pts: vec![at], by: None }), subsequent: None, boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(), junction: None,
            hasty: true, ready: false, rule: Some("разрешение верхней инстанции на отход".into()), issued: 0, note: "отход разрешён".into() };
        crate::command::passing::issue(&mut self.sim, d, tick);
    }
    Ok(())
}

/// Вернуть: изъятого через голову — в замысел старшего, взятый штаб — агенту (решает в свой следующий цикл).
pub fn release(&mut self, id: &str) -> Result<(), String> {
    use crate::command::control::{Control, DocKind, Document};
    let tick = self.hour();
    if let Some(h) = self.sim.world.hqs.iter().position(|x| x.id == id && x.side == self.player) {
        self.sim.command.led_hq[h] = false;
        if let Some(x) = self.sim.intent.led.get_mut(h) { *x = false; }
        // старший снова отдаст ему задачу в свой следующий цикл
        self.sim.command.sent.retain(|k, _| k.1 != crate::command::directive::Target::Hq(h as u32));
        // в истории как замысле взятую верхнюю инстанцию можно и вернуть (в прочих режимах она всегда у игрока)
        if self.sim.command.control[h] == Control::Player && (self.mode == Mode::Intent || self.sim.world.hqs[h].echelon != crate::model::Echelon::HighCommand) {
            self.sim.command.control[h] = Control::Agent;
            // замысел, пришедший, пока штаб был у игрока, остаётся новым (fresh)
            self.sim.command.last_cycle[h] = tick;
        }
        // история как замысел: поддерево снова «по истории», управление — как в режиме (фронты — по сценарию)
        if self.sim.intent.enabled[crate::staff::side_idx(self.player)] { crate::intent::release(&mut self.sim, h as u32); }
        self.sim.documents.push(Document { tick, hq: h as u32, kind: DocKind::Notice, to: Vec::new(), text: "штаб возвращён: решает агент по замыслу старшего".into(), rule: None });
        return Ok(());
    }
    if let Some(i) = self.sim.world.divisions.iter().position(|d| d.id == id && d.side == self.player) {
        self.sim.command.led_div[i] = false;
        self.sim.command.sent.retain(|k, _| k.1 != crate::command::directive::Target::Division(i as u32));
        return Ok(());
    }
    Err(format!("нет штаба или дивизии {id} стороны игрока"))
}

/// Исполнить команду управления (без проверки режима — как отдельные команды окна между ходами).
pub(crate) fn run_op(&mut self, c: &CommandOp) -> Result<(), String> {
    match c {
        CommandOp::Take { hq } => self.take(hq),
        CommandOp::Release { id } => self.release(id),
        CommandOp::Permit { hq, yes } => self.permit(hq, *yes),
        CommandOp::Historical { id } => self.issue_historical(id),
        CommandOp::Directive { directive } => self.directive(directive),
    }
}

/// Распоряжения штаба на ход; возвращает неисполненные с причиной.
pub fn staff(&mut self, s: &StaffIn) -> Vec<String> {
    let mut bad = Vec::new();
    let ix: std::collections::HashMap<String, u32> = self.sim.world.divisions.iter().enumerate().map(|(i, d)| (d.id.clone(), i as u32)).collect();
    self.sim.staff.supply = s.supply.iter().filter_map(|(id, k)| ix.get(id).map(|&i| (i, k.max(0.0)))).collect();
    let theatre = self.sim.theatre.clone();
    let proj = &theatre.proj;
    for b in &s.bridges { self.sim.staff.pontoons.push((proj.to_xy(b.at), self.player, b.from)); }
    for b in &s.demolish {
        match theatre.bridges.iter().position(|x| x.id == b.bridge) {
            Some(k) => { self.sim.staff.demolished.insert(k as u16, b.from); }
            None => bad.push(format!("подрыв: моста {} в театре нет", b.bridge)),
        }
    }
    for c in &s.commit {
        let Some(&i) = ix.get(&c.division) else { bad.push(format!("резерв {}: нет такой дивизии", c.division)); continue };
        if self.reserves.remove(&i).is_none() { bad.push(format!("резерв {}: не ждёт ввода", c.division)); continue; }
        let d = &mut self.sim.world.divisions[i as usize];
        d.enter = c.from.max(self.sim.world.tick);
        d.vars.pos = proj.to_xy(c.at);
    }
    self.sim.staff.sectors = s.sectors.iter().map(|x| Sectors {
        step: x.step.max(1), cols: x.cols, foreign: x.foreign,
        label: match &x.codes { Some(c) => c.bytes().map(|b| if b == b'.' { -1 } else { b as i16 - b'0' as i16 }).collect(), None => x.label.clone() },
        group: x.groups.iter().filter_map(|(id, g)| ix.get(id).map(|&i| (i, *g))).collect(),
    }).collect();
    bad
}

/// То же, со сторонами под внешним управлением `free` (игрок и штаб противника на модели вне ядра) и состоянием
/// дивизий на час передачи `takeover_state` (заменяет рассчитанное; в последнем кадре до передачи — уже оно).
pub fn start_free(sim: Sim, meta: Meta, takeover: u32, player: Side, free: &[Side], takeover_state: Option<&TakeoverIn>) -> Game {
    Game::start_mode(sim, meta, takeover, player, free, takeover_state, Mode::Legacy)
}

/// То же, в режиме игры `mode`. В режимах «агенты» и «гибрид» приказы сценария и артподготовки стороны игрока
/// остаются (приказы штабов-агентов и игрока при доставке пропускаются), резервы вводятся по сценарию.
pub fn start_mode(mut sim: Sim, meta: Meta, takeover: u32, player: Side, free: &[Side], takeover_state: Option<&TakeoverIn>, mode: Mode) -> Game {
    let takeover = takeover.min(meta.hours);
    // история как замысел: та же переигровка, что прогон `--command intent`, с часа 0 — управление ровно как в
    // прогоне (фронты и Ставка по сценарию, армии — агенты, командующие и цепочки) у стороны игрока и у противника,
    // если он не на модели вне ядра; к часу передачи у армий действующие распоряжения, игрок берёт штаб на этом часе
    if mode == Mode::Intent {
        for sd in [Side::Su, Side::De] {
            if sd != player && free.contains(&sd) { continue; }
            let _ = crate::command::control::command_mode(&mut sim, "intent", sd);
            if sd != player { sim.sources[crate::staff::side_idx(sd)] = crate::staff::Source::Script; }
        }
    }
    let mut frames = vec![trace::frame(&sim)];
    for _ in 0..takeover { sim.step(); frames.push(trace::frame(&sim)); }
    if let Some(st) = takeover_state {
        let w = &mut sim.world;
        let proj = &sim.theatre.proj;
        for d in w.divisions.iter_mut() {
            let Some(s) = st.divisions.get(&d.id) else { continue };
            // выбывшая (рассеяна, сведена) — факт о численности её не возвращает
            if matches!(d.state, crate::model::State::Destroyed | crate::model::State::Merged) { continue; }
            if let Some(p) = s.personnel { d.vars.personnel = p.max(0.0); }
            if let Some(t) = s.tanks { d.vars.tanks = t.max(0.0); }
            if let Some(g) = s.guns { d.vars.guns = g.max(0.0); }
            if let Some(p) = s.pos { d.vars.pos = proj.to_xy(p); d.route = None; }
            if let Some(h) = s.hq.as_deref().and_then(|h| w.hqs.iter().position(|x| x.id == h && x.side == d.side)) { d.hq = h as u32; }
        }
        if let Some(f) = frames.last_mut() { *f = trace::frame(&sim); }
    }
    // штабы-агенты: игрок — верхняя инстанция своей стороны, ниже — агенты; приказы сценария стороны остаются
    if mode != Mode::Legacy {
        if mode == Mode::Intent {
            // история как замысел включена до прокрутки (выше); взятый игроком штаб с поддеревом уходит с истории (take)
        } else {
            crate::command::control::agents_side(&mut sim, player);
            if mode == Mode::Commanders { crate::commander::enable(&mut sim, player); }
            // полосы армий следуют за войсками — в играх «агенты» и «командующие» (гибрид — нет)
            if matches!(mode, Mode::Agents | Mode::Commanders) { sim.command.follow_bands = true; }
        }
        // противник под внешним управлением (штаб на модели): его приказы сценария и артподготовки сняты, как раньше
        let other = |hq: u32, sim: &Sim| { let s = sim.world.hqs[hq as usize].side; s != player && free.contains(&s) };
        let keep: Vec<bool> = sim.script.iter().map(|o| !other(o.hq, &sim)).collect();
        let mut k = keep.iter();
        sim.script.retain(|_| *k.next().unwrap());
        let keep: Vec<bool> = sim.fires.iter().map(|f| !other(f.hq, &sim)).collect();
        let mut k = keep.iter();
        sim.fires.retain(|_| *k.next().unwrap());
        for &sd in free { sim.sources[crate::staff::side_idx(sd)] = crate::staff::Source::Script; }
        let limit = meta.hours;
        let enemy_intent = mode == Mode::Intent && !free.contains(&other_side(player));
        let mut g = Game { mode, issued: Default::default(), pending: Vec::new(), sim, meta, frames, player, free: free.to_vec(), takeover, limit, reserves: BTreeMap::new(), enemy_agents: enemy_intent, log: Vec::new(), snaps: Vec::new(), between: Vec::new() };
        // командующие и у противника, если он не на модели вне ядра: его штабы — агенты, верхняя инстанция — Гитлер/Ставка
        if mode == Mode::Commanders && !g.free.contains(&other_side(player)) { g.enemy_agents(); }
        return g;
    }
    let mine = |hq: u32, sim: &Sim| free.contains(&sim.world.hqs[hq as usize].side);
    let keep: Vec<bool> = sim.script.iter().map(|o| !mine(o.hq, &sim)).collect();
    let mut k = keep.iter();
    sim.script.retain(|_| *k.next().unwrap());
    let keep: Vec<bool> = sim.fires.iter().map(|f| !mine(f.hq, &sim)).collect();
    let mut k = keep.iter();
    sim.fires.retain(|_| *k.next().unwrap());
    // штабы сторон под внешним управлением сами больше не решают
    for &sd in free { sim.sources[crate::staff::side_idx(sd)] = crate::staff::Source::Script; }
    // резервы стороны игрока: ввод больше не по графику сценария — по его решению (commit)
    let mut reserves = BTreeMap::new();
    for (i, d) in sim.world.divisions.iter_mut().enumerate() {
        if d.side == player && d.state == crate::model::State::Pending && d.enter > takeover {
            reserves.insert(i as u32, d.enter);
            d.enter = u32::MAX;
        }
    }
    let limit = meta.hours;
    Game { mode: Mode::Legacy, issued: Default::default(), pending: Vec::new(), sim, meta, frames, player, free: free.to_vec(), takeover, limit, reserves, enemy_agents: false, log: Vec::new(), snaps: Vec::new(), between: Vec::new() }
}

/// Взять штаб под своё управление: его замысел старшего остаётся, сам он больше не решает.
pub fn take(&mut self, hq: &str) -> Result<(), String> {
    use crate::command::control::{Control, DocKind, Document};
    let h = self.sim.world.hqs.iter().position(|x| x.id == hq && x.side == self.player).ok_or_else(|| format!("нет штаба {hq} стороны игрока"))?;
    // в истории как замысле верхняя инстанция — по истории, её можно взять; в прочих режимах она и так у игрока
    if self.mode != Mode::Intent && self.sim.world.hqs[h].echelon == crate::model::Echelon::HighCommand { return Err("верхняя инстанция и так у игрока".into()); }
    self.sim.command.control[h] = Control::Player;
    // история как замысел: поддерево взятого штаба — «под командованием игрока»
    if self.sim.intent.enabled[crate::staff::side_idx(self.player)] { crate::intent::take(&mut self.sim, h as u32); }
    let tick = self.hour();
    self.sim.documents.push(Document { tick, hq: h as u32, kind: DocKind::Notice, to: Vec::new(), text: "штаб взят под управление игрока".into(), rule: None });
    Ok(())
}

/// Верхняя инстанция стороны игрока.
fn top(&self) -> Result<u32, String> {
    self.sim.world.hqs.iter().position(|h| h.side == self.player && h.echelon == crate::model::Echelon::HighCommand).map(|k| k as u32).ok_or_else(|| "у стороны нет верхней инстанции".into())
}

/// Ход игры в формате trace.json (кадры с начала сценария) и сведения об игре.
pub fn trace(&self) -> Value {
    let mut v = trace::describe(&self.sim, &self.meta, self.frames.clone());
    // территория сторон по клеткам театра (0 — ничья, 1 — советская, 2 — немецкая): для путей подвоза от баз
    v["control"] = serde_json::json!(self.sim.world.control.iter().map(|&c| (b'0' + c.min(9)) as char).collect::<String>());
    v["game"] = serde_json::json!({
        "player": self.player, "free": self.free,
        "reserves": self.reserves.iter().map(|(&i, &h)| serde_json::json!({ "id": self.sim.world.divisions[i as usize].id, "from": h })).collect::<Vec<_>>(),
        "takeover": self.takeover, "hour": self.hour(), "over": self.over(), "enemyAgents": self.enemy_agents,
        // сыгранных ходов и отпечаток игры (строкой: u64 не помещается в число JS)
        "turn": self.log.len(), "digest": format!("{:016x}", self.state_digest()),
    });
    v["command"] = self.command_state();
    v
}

/// Режим игры: «как сейчас» (приказы игрока размножаются по дивизиям штаба), «агенты» (игрок — верхняя инстанция,
/// ниже — штабы-агенты), «гибрид» (как «агенты», но исторические директивы, поданные без изменений, ведут приказы
/// сценария), «командующие» (как «агенты», плюс командующие у штабов с профилем обеих сторон; место командующего
/// игрок занимает командой `take` — тогда его штаб молчит).
pub enum Mode { Legacy, Agents, Hybrid, Commanders, Intent }

/// Приказ штабу (всем его дивизиям) или одной дивизии.
pub struct PlayerOrder {
    /// Штаб (фронт, армия, корпус) или дивизия.
    pub hq: String,
    pub kind: OrderKind,
    /// Цель; нет — на месте (у каждой дивизии своё).
    #[serde(default)]
    pub target: Option<LngLat>,
    #[serde(default)]
    pub note: String,
    /// Форма (режимы штабов-агентов): приказ — сутки на ступень, полная слаженность; нет — боевое распоряжение.
    #[serde(default)]
    pub form: Option<crate::command::directive::Form>,
}

/// Полосы объединений (как sectorMap этой модели): сетка меток и объединение каждой дивизии.
pub struct SectorsIn {
    pub step: usize,
    pub cols: usize,
    #[serde(default)]
    pub label: Vec<i16>,
    /// Метки строкой, по знаку на клетку ('0' + метка, '.' — вне полос) — компактнее label.
    #[serde(default)]
    pub codes: Option<String>,
    pub groups: Vec<(String, i16)>,
    pub foreign: f64,
}

/// Распоряжения штаба на ход.
pub struct StaffIn {
    /// Множитель подвоза по дивизиям (на ход; весь набор заменяет прежний).
    #[serde(default)]
    pub supply: Vec<(String, f64)>,
    #[serde(default)]
    pub bridges: Vec<AtHour>,
    /// Подрыв мостов театра (по id моста) с часа; с часа 0 — мост снят (наводки стороны игрока после передачи командования).
    #[serde(default)]
    pub demolish: Vec<Demolish>,
    #[serde(default)]
    pub commit: Vec<Commit>,
    /// Полосы по уровням (фронты, армии); пусто — без полос.
    #[serde(default)]
    pub sectors: Vec<SectorsIn>,
}

/// Состояние дивизий на час передачи командования (из базы знаний): заменяет рассчитанное к этому часу.
pub struct TakeoverIn {
    /// id дивизии → состояние; неизвестные id не учитываются.
    #[serde(default)]
    pub divisions: std::collections::HashMap<String, TakeoverDiv>,
}

/// Противник при режиме игры своей стороны: script — приказы сценария (без штаба), doctrine — по доктрине, llm — штаб на
/// модели вне ядра, agents — штабы-агенты, intent — история как замысел. В «истории как замысле» противник — тоже
/// история (или штаб на модели), у «командующих» — командующие и штабы-агенты (или штаб на модели); в «как сейчас»
/// истории у противника нет. Недопустимое сочетание — ошибка, а не подмена молча; без выбора — умолчание режима.
pub fn enemy_for(mode: Mode, enemy: Option<&str>) -> Result<&'static str, String> {
    let ok: &[&'static str] = match mode {
        Mode::Intent => &["intent", "llm"],
        Mode::Commanders => &["agents", "llm"],
        Mode::Legacy => &["script", "doctrine", "llm", "agents"],
        Mode::Agents | Mode::Hybrid => &["script", "doctrine", "llm", "agents", "intent"],
    };
    let Some(e) = enemy else { return Ok(ok[0]) };
    ok.iter().copied().find(|&x| x == e).ok_or_else(|| {
        let names: Vec<&str> = ok.iter().map(|&x| enemy_title(x)).collect();
        format!("противник «{}» в этом режиме игры недопустим; допустимы: {}", enemy_title(e), names.join(", "))
    })
}

/// Название противника — как в окне «Принять командование» (id ядра → русское имя; неизвестный остаётся как есть).
fn enemy_title(id: &str) -> &str {
    match id {
        "script" => "без штаба",
        "llm" => "штаб на модели",
        "agents" => "штабы-агенты",
        "intent" => "история как замысел",
        "doctrine" => "по доктрине",
        other => other,
    }
}

/// Команда управления между ходами: исполняется сразу (те же действия, что у команд хода), при успехе — в `between`,
/// с ходом — в журнал (при повторе исполняется первой).
pub fn between_op(&mut self, c: CommandOp) -> Result<(), String> {
    self.snap_if_due();
    self.run_op(&c)?;
    self.between.push(c);
    Ok(())
}

/// Ход: доктрина → команды управления → распоряжения штаба → приказы → `hours` часов расчёта; ход — в журнал.
/// Перед ходом — снимок (если ход кратен шагу снимков); при повторе журнала сначала исполняются команды, поданные
/// тогда между ходами (`t.between`); поданные сейчас (`self.between`) уже исполнены — уходят в запись хода.
pub fn play_turn(&mut self, mut t: TurnIn) -> TurnResult {
    self.snap_if_due();
    for c in &t.between { let _ = self.run_op(c); }
    t.between.extend(std::mem::take(&mut self.between));
    if let Some(d) = &t.doctrine { self.sim.doctrine_text = d.clone(); }
    let command_results: Vec<Option<String>> = t.command.iter().map(|c| self.command_json(c).err()).collect();
    let staff_errors = t.staff.as_ref().map(|s| self.staff(s)).unwrap_or_default();
    let applied: Vec<Value> = t.orders.iter().map(|o| match self.order(o) {
        Ok(n) => json!({ "hq": o.hq, "divisions": n }),
        Err(e) => json!({ "hq": o.hq, "error": e }),
    }).collect();
    self.advance(t.hours);
    self.log.push(t);
    TurnResult { applied, staff_errors, command_results }
}

/// Вернуться к ходу `keep + 1` (оставить `keep` сыгранных ходов): ближайший снимок не позже, досчёт повтором
/// записанных входов; команды между ходами, поданные после последнего хода, снимаются.
pub fn rewind(&mut self, keep: usize) -> Result<(), String> {
    let n = self.log.len();
    if keep > n { return Err(format!("сыграно ходов: {n}, к ходу {} вернуться нельзя", keep + 1)); }
    if keep == n && self.between.is_empty() { return Ok(()); }
    let at = self.snaps.iter().rposition(|s| s.turn <= keep).ok_or_else(|| format!("нет снимка игры до хода {}", keep + 1))?;
    self.snaps.truncate(at + 1);
    let s = &self.snaps[at];
    let mut sim = s.sim.snapshot();
    // связь с окном (ход расчёта, поток ответов модели) — у живого мира
    sim.on_progress = self.sim.on_progress.take();
    sim.on_stream = self.sim.on_stream.take();
    self.sim = sim;
    self.frames.truncate(s.frames);
    self.issued = s.issued.clone();
    self.pending = s.pending.clone();
    self.reserves = s.reserves.clone();
    self.enemy_agents = s.enemy_agents;
    self.limit = s.limit;
    let from = s.turn;
    let replay: Vec<TurnIn> = self.log.drain(from..).take(keep - from).collect();
    self.between.clear();
    for t in replay { self.play_turn(t); }
    Ok(())
}

/// Снимок перед первым действием хода (ход или команда между ходами), если ход кратен шагу и снимка ещё нет.
fn snap_if_due(&mut self) {
    let turn = self.log.len();
    if turn % self.snap_step() != 0 || self.snaps.last().is_some_and(|s| s.turn >= turn) { return; }
    self.snaps.push(GameSnap {
        turn, sim: self.sim.snapshot(), frames: self.frames.len(), issued: self.issued.clone(), pending: self.pending.clone(),
        reserves: self.reserves.clone(), enemy_agents: self.enemy_agents, limit: self.limit,
    });
    if self.snaps.len() > MAX_SNAPS {
        // каждый второй, кроме снимка хода 0: остаются чётные по порядку (0, 2·шаг, 4·шаг, …)
        let mut k = 0;
        self.snaps.retain(|_| { k += 1; (k - 1) % 2 == 0 });
    }
}

/// Шаг снимков: `SNAP_EVERY`, после прореживания — расстояние между первыми снимками.
fn snap_step(&self) -> usize {
    match self.snaps.as_slice() { [a, b, ..] => (b.turn - a.turn).max(1), _ => SNAP_EVERY }
}

/// Отпечаток игры (FNV-1a, как `Sim::digest`): мир, кадры, документы, командование (с директивами в пути и
/// замыслами штабов), распоряжения штаба, советские штабы по доктрине, «история как замысел», командующие,
/// поданные и ждущие директивы игрока, резервы.
pub fn state_digest(&self) -> u64 {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    let mut eat = |x: u64| { h ^= x; h = h.wrapping_mul(0x0100_0000_01b3); };
    // строка — байты и разделитель (соседние строки не сливаются)
    fn bytes(eat: &mut impl FnMut(u64), t: &str) { for b in t.bytes() { eat(b as u64); } eat(0x1ff); }
    let s = &self.sim;
    eat(s.digest());
    eat(self.frames.len() as u64);
    for d in &s.documents { eat(d.tick as u64); eat(d.hq as u64); eat(d.kind as u8 as u64); eat(d.text.len() as u64); }
    let c = &s.command;
    for &x in &c.control { eat(x as u8 as u64); }
    for &x in &c.led_hq { eat(x as u64); }
    for &x in &c.led_div { eat(x as u64); }
    for r in &c.requests { eat(r.tick as u64); eat(match r.answer { None => 0, Some(false) => 1, Some(true) => 2 }); }
    eat(c.sent.len() as u64);
    eat(s.historical.len() as u64);
    eat(c.in_transit.len() as u64);
    for (at, d) in &c.in_transit { eat(*at as u64); bytes(&mut eat, &d.id); }
    for x in &c.intent { match x { Some(d) => bytes(&mut eat, &d.id), None => eat(0) } }
    eat(s.staff.supply.len() as u64);
    eat(s.staff.pontoons.len() as u64);
    {
        let su = s.su_staff.lock().unwrap_or_else(|e| e.into_inner());
        eat(su.plan.iter().filter(|p| p.is_some()).count() as u64);
        for &e in &su.ech { eat(e as u8 as u64); }
        for &x in &su.since { eat(x as u64); }
        eat(su.replaced.iter().filter(|&&r| r).count() as u64);
    }
    let i = &s.intent;
    for x in &i.hq { eat(x.status as u8 as u64); eat(x.since as u64); }
    for ch in &i.chains { for t in &ch.tasks { eat(t.issued as u64); } }
    for &x in &i.led { eat(x as u64); }
    eat(i.log.len() as u64);
    eat(i.queue.len() as u64);
    eat(i.actions.len() as u64);
    eat(i.drops.len() as u64);
    for &e in &i.enabled { eat(e as u64); }
    for k in &s.commanders.list {
        eat(k.mood.confidence.to_bits());
        eat(k.mood.stress.to_bits());
        eat(k.intent_label.as_ref().map_or(0, |l| l.len() as u64));
        eat(k.decisions.len() as u64);
        eat(k.last as u64);
        match &k.intent { Some(x) => bytes(&mut eat, &format!("{x:?}")), None => eat(0) }
        eat(k.withdraw_at.len() as u64);
        eat(k.seen.intent.is_some() as u64);
        eat(k.seen.cut as u64);
        eat(k.seen.requests.len() as u64);
        eat(k.seen.broke.len() as u64);
        eat(k.seen.tasked.len() as u64);
    }
    eat(s.commanders.raised.len() as u64);
    for (at, d) in &self.pending { eat(*at as u64); bytes(&mut eat, &d.id); }
    let mut issued: Vec<&String> = self.issued.iter().collect();
    issued.sort();
    for id in issued { bytes(&mut eat, id); }
    for (&k, &v) in &self.reserves { eat(k as u64); eat(v as u64); }
    h
}

/// Ход в формате trace.json с итогом хода: приказы, ошибки распоряжений и команд, итог по командам.
pub fn turn_trace(&self, r: &TurnResult) -> Value {
    let mut t = self.trace();
    t["game"]["applied"] = json!(r.applied);
    t["game"]["staffErrors"] = json!(r.staff_errors);
    t["game"]["commandErrors"] = json!(r.command_results.iter().flatten().collect::<Vec<_>>());
    t["game"]["commandResults"] = json!(r.command_results);
    t
}

/// Снимок игры перед ходом `turn + 1`: мир без потерь (`Sim::snapshot`), число кадров (кадры только дописываются —
/// при возврате обрезаются), управление игрой. Команды между ходами в снимок не входят — они в журнале хода.
pub struct GameSnap {
    /// Сыграно ходов.
    pub turn: usize,
    pub sim: Sim,
    pub frames: usize,
    pub issued: HashSet<String>,
    pub pending: Vec<(u32, Directive)>,
    pub reserves: BTreeMap<u32, u32>,
    pub enemy_agents: bool,
    pub limit: u32,
}

/// Вход хода: команды управления, распоряжения штаба, приказы, длина хода в часах, доктрина из базы знаний на ход.
pub struct TurnIn {
    /// Команды управления (взять, вернуть, разрешить отход, исторические директивы, директивы) — строками JSON, как
    /// их подаёт окно: неразборчивая — ошибка этой команды, а не всего хода.
    #[serde(default)]
    pub command: Vec<Value>,
    #[serde(default)]
    pub staff: Option<StaffIn>,
    #[serde(default)]
    pub orders: Vec<PlayerOrder>,
    #[serde(default = "twelve")]
    pub hours: u32,
    /// Доктрина из базы знаний на этот ход: [советская сторона, немецкая]; нет — прежняя.
    #[serde(skip)]
    pub doctrine: Option<[Option<String>; 2]>,
    /// Команды, поданные между ходами (до команд хода).
    #[serde(skip)]
    pub between: Vec<CommandOp>,
}

/// Итог хода: по приказам (дивизий или ошибка), неисполненные распоряжения, по командам (null — исполнена).
pub struct TurnResult {
    pub applied: Vec<Value>,
    pub staff_errors: Vec<String>,
    pub command_results: Vec<Option<String>>,
}

pub struct Proj {
    pub lng0: f64,
    pub lat0: f64,
}

pub fn to_lnglat(&self, q: XY) -> LngLat {
    let lat = q.y / KM_LAT + self.lat0;
    [q.x / (KM_LNG_EQ * lat.to_radians().cos()) + self.lng0, lat]
}

pub fn to_xy(&self, p: LngLat) -> XY {
    XY::new((p[0] - self.lng0) * KM_LNG_EQ * p[1].to_radians().cos(), (p[1] - self.lat0) * KM_LAT)
}

pub struct XY {
    pub x: f64,
    pub y: f64,
}

pub fn toward(self, o: XY, km: f64) -> XY {
    let d = self.dist(o);
    if d <= km || d == 0.0 { return o; }
    XY::new(self.x + (o.x - self.x) * km / d, self.y + (o.y - self.y) * km / d)
}

/// Пересекаются ли отрезки ab и cd (касание считается пересечением).
pub fn segments_cross(a: XY, b: XY, c: XY, d: XY) -> bool {
    fn orient(p: XY, q: XY, r: XY) -> f64 { (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x) }
    let (d1, d2) = (orient(c, d, a), orient(c, d, b));
    let (d3, d4) = (orient(a, b, c), orient(a, b, d));
    (d1 * d2 <= 0.0) && (d3 * d4 <= 0.0) && !(d1 == 0.0 && d2 == 0.0 && d3 == 0.0 && d4 == 0.0)
}

pub struct Chain {
    /// Штаб-получатель: армия (фронт — для директив Ставки; армия-владелец — для немецких приказов).
    pub owner: u32,
    pub tasks: Vec<Task>,
    /// Следующая к подаче задача.
    pub next: usize,
    /// Центр живых дивизий получателя при построении цепочки — точка отсчёта направления армии.
    pub start: Option<XY>,
}

pub struct Task {
    pub at: u32,
    pub step: Step,
    /// Пункт или середина рубежа; нет — «на месте».
    pub goal: Option<XY>,
    pub kind: Goal,
    /// Задача подана (диспетчером или, немецкий приказ сценария, пропуском `admit` в свой час); пропущенная — нет.
    pub issued: bool,
}

/// Армия над штабом (он сам, если он армия или выше армии нет).
pub(crate) fn army_of(sim: &Sim, hq: u32) -> u32 {
    let w = &sim.world;
    let mut k = hq as usize;
    for _ in 0..8 {
        if w.hqs[k].echelon == Echelon::Army { return k as u32; }
        match w.hqs[k].parent { Some(p) => k = p as usize, None => break }
    }
    hq
}

/// Цепочки стороны: по возрастанию номера штаба-получателя, задачи — по часу (при равном — как в сценарии).
/// Директивы (Ставки и фронтов; у немцев — верхней инстанции) — получателю-штабу; немецкие приказы и отводы сценария —
/// армии-владельцу получающих дивизий.
pub fn build(sim: &Sim, side: Side) -> Vec<Chain> {
    let w = &sim.world;
    let mut by: std::collections::BTreeMap<u32, Vec<Task>> = Default::default();
    for (at, d) in &sim.historical {
        if d.id.ends_with(":journal") || w.hqs[d.from as usize].side != side { continue; }
        let Target::Hq(h) = d.to else { continue };
        by.entry(h).or_default().push(Task { at: *at, step: Step::Dir(d.clone()), goal: dir_goal(d), kind: dir_kind(d.task), issued: false });
    }
    if side == Side::De {
        let owners = |to: &[u32], fallback: Option<u32>| -> Vec<u32> {
            let mut v: Vec<u32> = to.iter().map(|&i| army_of(sim, w.divisions[i as usize].hq)).collect();
            if v.is_empty() { v.extend(fallback.map(|h| army_of(sim, h))); }
            v.sort_unstable();
            v.dedup();
            v
        };
        for o in sim.script.iter().filter(|o| w.hqs[o.hq as usize].side == Side::De) {
            for ow in owners(&o.to, Some(o.hq)) {
                by.entry(ow).or_default().push(Task { at: o.at, step: Step::Order(o.clone()), goal: o.target, kind: order_kind(o.kind), issued: false });
            }
        }
        for wd in &sim.withdrawals {
            // у отвода нет пункта: только доли войск по позициям — цель «на месте»; без названных дивизий отвод пропускается
            for ow in owners(&wd.to, None) {
                by.entry(ow).or_default().push(Task { at: wd.at, step: Step::Withdrawal(wd.clone()), goal: None, kind: Goal::Withdraw, issued: false });
            }
        }
    }
    by.into_iter().map(|(owner, mut tasks)| {
        tasks.sort_by_key(|t| t.at);
        let start = mid(&super::sense::live(sim, owner).iter().map(|&i| w.divisions[i].vars.pos).collect::<Vec<_>>());
        Chain { owner, tasks, next: 0, start }
    }).collect()
}

fn dir_goal(d: &Directive) -> Option<XY> {
    [&d.immediate, &d.subsequent].into_iter().flatten().find_map(|l| mid(&l.pts)).or_else(|| d.axis.last().copied())
}

fn dir_kind(t: DTask) -> Goal {
    match t { DTask::Attack => Goal::Attack, DTask::Move => Goal::Move, DTask::Withdraw => Goal::Withdraw, DTask::Defend | DTask::Delay | DTask::Reserve => Goal::Defend }
}

/// Задача из директивы (цель и вид — как у задачи цепочки): по ней судят о смысле и выполнении задачи, которую армия
/// держит.
pub fn of_directive(at: u32, d: &Directive) -> Task {
    Task { at, step: Step::Dir(d.clone()), goal: dir_goal(d), kind: dir_kind(d.task), issued: true }
}

fn order_kind(k: OrderKind) -> Goal {
    match k { OrderKind::Attack => Goal::Attack, OrderKind::Move => Goal::Move, OrderKind::Withdraw => Goal::Withdraw, OrderKind::Defend | OrderKind::Hold => Goal::Defend }
}

pub struct State {
    /// Режим включён: [советская сторона, немецкая].
    pub enabled: [bool; 2],
    pub chains: Vec<Chain>,
    /// По штабам мира.
    pub hq: Vec<HqState>,
    /// След эталона; нет — ухода и возврата по расстоянию нет. Общий у снимков (`Sim::snapshot`): не копируется.
    pub track: Option<std::sync::Arc<Track>>,
    /// Смены состояния: (час, штаб, состояние, причина).
    pub log: Vec<(u32, u32, Status, Option<Reason>)>,
    /// Файл сценария (след эталона — рядом с ним): задаёт `scenario::load_with`.
    pub scenario: Option<String>,
    /// Немецкие приказы сценария, поданные диспетчером не в свой час: в этом же шаге — в путь к дивизиям.
    pub queue: Vec<ScriptOrder>,
    /// Чистая история (запись следа эталона): все задачи — в свой час, без условий смысла, ухода и возврата.
    pub pure: bool,
    /// Действия вмешательства, ждущие своего часа (intervene.rs).
    pub actions: Vec<(u32, super::intervene::Action)>,
    /// Зоны изменённого замысла (`drop`).
    pub drops: Vec<super::intervene::DropZone>,
    /// По штабам мира: штаб ведёт игрок своими директивами (как старший) — штаб и его подчинённые с истории, решают
    /// его командующий и штаб по директиве игрока (игра, `Game::directive`).
    pub led: Vec<bool>,
}

/// Приказ сценария в свой час (шаг 0 мира): проходит к дивизиям армий, у которых он проходит `gate`; задача отмечается
/// поданной. None — не проходит никому. Штаб, отдающий приказ, под командованием игрока (взят или ведётся директивами
/// игрока — и через старшего, например взятую Ставку) — приказ не проходит, даже если он не входит ни в одну цепочку;
/// дивизиям под командованием игрока он тоже не доходит.
pub fn admit(sim: &mut Sim, mut o: ScriptOrder) -> Option<ScriptOrder> {
    if !sim.intent.enabled[side_idx(sim.world.hqs[o.hq as usize].side)] { return Some(o); }
    if player_over(sim, o.hq) { return None; }
    let hits = order_tasks(sim, &o);
    if !o.to.is_empty() {
        o.to.retain(|&d| !player_over(sim, sim.world.divisions[d as usize].hq));
        if o.to.is_empty() { return None; }
    }
    if hits.is_empty() { return Some(o); }
    let mut owners = Vec::new();
    for (ci, ti) in hits {
        if passes(sim, ci, ti) { sim.intent.chains[ci].tasks[ti].issued = true; owners.push(sim.intent.chains[ci].owner); }
    }
    if owners.is_empty() { return None; }
    if !o.to.is_empty() { o.to.retain(|&d| owners.contains(&army_of(sim, sim.world.divisions[d as usize].hq))); }
    Some(o)
}

fn back(sim: &mut Sim, owner: u32, tick: u32) {
    set(sim, owner, Status::History, None, tick);
    if sim.world.hqs[owner as usize].side == Side::De {
        for k in subtree(sim, owner) { if sim.command.control[k] == Control::Agent { sim.command.control[k] = Control::Script; } }
    }
}

/// Поле `intent` хода прогона: по штабу смены состояния с причиной; режим выключен — None.
pub fn describe(sim: &Sim) -> Option<Value> {
    if !sim.intent.any() { return None; }
    let mut by: std::collections::BTreeMap<u32, Vec<Value>> = Default::default();
    for (tick, h, s, r) in &sim.intent.log {
        by.entry(*h).or_default().push(json!({ "tick": tick, "status": s.label(), "reason": r.as_ref().map(reason_text) }));
    }
    Some(Value::Array(by.into_iter().map(|(h, changes)| json!({ "hq": sim.world.hqs[h as usize].id, "changes": changes })).collect()))
}

/// Подать наступившие задачи цепочки. Армия у следа (`near`) идёт как чистая история: задачи в свой час, без подачи
/// по выполнению и без пропусков; отошла от следа — подача по выполнению и пропуски, состояние
/// «со сдвигом» (причина — пропуск или задержка этого часа, иначе «армия в N км»).
fn dispatch(sim: &mut Sim, ci: usize, tick: u32, near: bool, km: Option<f64>) {
    let owner = sim.intent.chains[ci].owner;
    supersede(sim, ci, tick, near);
    let mut skipped: Option<Reason> = None;
    let mut why: Option<Reason> = None;
    let mut shifted = false;
    let mut issued_now = false;
    loop {
        let c = &sim.intent.chains[ci];
        let i = c.next;
        if i >= c.tasks.len() {
            // цепочка кончилась пропуском или (в час без новой задачи) у армии, отошедшей от следа, — решает
            // командующий; у следа — чистая история (новых задач нет, как в истории)
            if skipped.is_some() || (!near && !issued_now) { leave(sim, owner, Reason::ChainEnd, tick); return; }
            break;
        }
        let t = &c.tasks[i];
        // немецкий приказ, пропущенный в свой час в шаге 0 (`admit`)
        if t.issued { sim.intent.chains[ci].next += 1; continue; }
        let by_hour = t.at <= tick;
        let prev_done = !near && (0..i).rev().find(|&j| c.tasks[j].issued).is_some_and(|j| done(sim, owner, &c.tasks[j]));
        let catch_up = !near && skipped.is_some();
        if !(by_hour || prev_done || catch_up) { break; }
        // отвод с позиций — только в свой час
        if matches!(t.step, Step::Withdrawal(_)) && !by_hour { break; }
        match sense_now(sim, c, t, near) {
            // задача не в свой час (по выполнению или вдогонку) без смысла сейчас — ждёт своего часа: смысл будущей
            // задачи меряют по обстановке её часа (иначе «дальше двух переходов» отбросило бы всю цепочку)
            Err(_) if !by_hour => break,
            // неспособность задачу не отменяет: она ждёт, пока армия придёт в себя (или в свой час её отбросят прочие условия)
            Err(Reason::Unfit) => { why = Some(Reason::Unfit); shifted = true; break; }
            Err(r) => { sim.intent.chains[ci].next += 1; why = Some(r.clone()); skipped = Some(r); shifted = true; }
            Ok(()) => {
                issue(sim, ci, i, tick);
                issued_now = true;
                sim.intent.chains[ci].next += 1;
                if !by_hour || catch_up { shifted = true; }
                skipped = None;
            }
        }
    }
    if shifted || !near {
        let why = why.or_else(|| km.filter(|_| !near).map(|km| Reason::Strayed { km }));
        set(sim, owner, Status::Shifted, why, tick);
    } else {
        set(sim, owner, Status::History, None, tick);
    }
}

/// Включить режим у стороны: цепочки, след эталона (один раз), всем штабам — «по истории». Задачи до нынешнего часа
/// считаются отданными (принятие командования посреди операции: прежнее не подаётся повторно).
pub fn enable(sim: &mut Sim, side: Side) {
    let i = side_idx(side);
    if sim.intent.enabled[i] { return; }
    let tick = sim.world.tick;
    if !sim.intent.any() {
        sim.intent.hq = vec![HqState { status: Status::History, reason: None, since: tick }; sim.world.hqs.len()];
        let loaded = match sim.intent.scenario.as_deref() { Some(p) => super::track::load(p), None => Err("нет следа эталона".to_string()) };
        match loaded {
            Ok(t) => sim.intent.track = Some(std::sync::Arc::new(t)),
            Err(e) => sim.journal.push(Event { tick, agent: u32::MAX, text: format!("история как замысел: {e}") }),
        }
    }
    sim.intent.enabled[i] = true;
    let mut chains = build(sim, side);
    for c in chains.iter_mut() {
        for t in c.tasks.iter_mut().filter(|t| t.at < tick) { t.issued = true; }
        c.next = c.tasks.iter().take_while(|t| t.at < tick).count();
        sim.intent.log.push((tick, c.owner, Status::History, None));
    }
    sim.intent.chains.extend(chains);
}

/// Немецкий приказ сценария проходит, только если его армия на истории и задача имеет смысл (иначе отбрасывается —
/// его заменяет цепочка или командующий). Приказ вне цепочек (сторона без режима) проходит.
pub fn gate(sim: &Sim, o: &ScriptOrder) -> bool {
    if !sim.intent.enabled[side_idx(sim.world.hqs[o.hq as usize].side)] { return true; }
    if player_over(sim, o.hq) { return false; }
    let hits = order_tasks(sim, o);
    hits.is_empty() || hits.iter().any(|&(ci, ti)| passes(sim, ci, ti))
}

fn issue(sim: &mut Sim, ci: usize, i: usize, tick: u32) {
    let owner = sim.intent.chains[ci].owner;
    sim.intent.chains[ci].tasks[i].issued = true;
    let t = sim.intent.chains[ci].tasks[i].clone();
    match t.step {
        Step::Dir(mut d) => {
            let crate::command::directive::Target::Hq(h) = d.to else { return };
            // штаб по приказам сценария директиву не разбирает — её исполняют приказы сценария
            if sim.command.control[h as usize] != Control::Agent { return; }
            d.ready = t.at == 0 && tick == 0;
            let d = crate::command::control::with_axis(sim, d);
            crate::command::passing::issue(sim, d, tick);
        }
        Step::Order(mut o) => {
            if !o.to.is_empty() { o.to.retain(|&d| army_of(sim, sim.world.divisions[d as usize].hq) == owner); }
            o.at = tick;
            sim.intent.queue.push(o);
        }
        Step::Withdrawal(_) => {}
    }
}

pub(super) fn leave(sim: &mut Sim, owner: u32, reason: Reason, tick: u32) {
    set(sim, owner, Status::Own, Some(reason), tick);
    // немецкая армия — штабам-агентам (и командующим)
    if sim.world.hqs[owner as usize].side == Side::De {
        for k in subtree(sim, owner) { if sim.command.control[k] == Control::Script { sim.command.control[k] = Control::Agent; } }
    }
}

/// Штаб не на истории: сам он или его старший — «сам», или его (или старшего) ведёт игрок.
pub fn off_history(sim: &Sim, hq: u32) -> bool {
    if !sim.intent.any() { return false; }
    if player_over(sim, hq) { return true; }
    let mut k = hq as usize;
    for _ in 0..8 {
        if sim.intent.hq.get(k).is_some_and(|s| s.status == Status::Own) { return true; }
        match sim.world.hqs[k].parent { Some(p) => k = p as usize, None => return false }
    }
    false
}

/// Армия у следа эталона (не дальше `returnKm`) или следа для неё нет — правила приспособления не действуют.
fn on_track(sim: &Sim, owner: u32) -> bool {
    sim.intent.pure || stray_km(sim, owner, sim.world.tick).is_none_or(|km| km <= sim.rules.intent.return_km)
}

/// Задачи цепочек с этим приказом сценария: (цепочка, задача).
fn order_tasks(sim: &Sim, o: &ScriptOrder) -> Vec<(usize, usize)> {
    let mut v = Vec::new();
    for (ci, c) in sim.intent.chains.iter().enumerate() {
        for (ti, t) in c.tasks.iter().enumerate() { if matches!(&t.step, Step::Order(x) if same_order(x, o)) { v.push((ci, ti)); } }
    }
    v
}

fn passes(sim: &Sim, ci: usize, ti: usize) -> bool {
    let c = &sim.intent.chains[ci];
    !c.tasks[ti].issued && !superseded(sim, ci, ti) && !off_history(sim, c.owner) && sense_now(sim, c, &c.tasks[ti], on_track(sim, c.owner)).is_ok()
}

/// Штаб или кто-то над ним — под командованием игрока (взят или ведётся директивами игрока).
pub fn player_over(sim: &Sim, h: u32) -> bool {
    let w = &sim.world;
    let mut k = h as usize;
    for _ in 0..8 {
        if sim.command.control.get(k) == Some(&Control::Player) || sim.intent.led.get(k) == Some(&true) { return true; }
        match w.hqs[k].parent { Some(p) => k = p as usize, None => return false }
    }
    false
}

/// Возврат штаба `hq` игроком (игра, `Game::release`): штабы его поддерева, ушедшие с истории только из-за игрока, и
/// не под командованием игрока через другой штаб — снова «по истории» (смена записывается); управление — как в режиме:
/// у советской стороны Ставка и фронты — по приказам сценария, армии и ниже — агенты; у немецкой — по приказам
/// сценария. Армии с цепочкой дальше идут по обычным правилам (уход по расстоянию, подача, возврат).
pub fn release(sim: &mut Sim, hq: u32) {
    use crate::model::Echelon;
    let tick = sim.world.tick;
    for k in subtree(sim, hq) {
        if player_over(sim, k as u32) || sim.intent.hq.get(k).is_none_or(|s| s.reason != Some(Reason::Player)) { continue; }
        set(sim, k as u32, Status::History, None, tick);
        let h = &sim.world.hqs[k];
        let to = if h.side == Side::De || matches!(h.echelon, Echelon::HighCommand | Echelon::Front) { Control::Script } else { Control::Agent };
        if sim.command.control[k] != to {
            sim.command.control[k] = to;
            if to == Control::Agent { sim.command.last_cycle[k] = tick; }
        }
    }
}

/// Смысл задачи для подачи: в чистой истории и у армии у следа — всегда (что дивизии смогут, решает их состояние);
/// отошла от следа — все условия.
fn sense_now(sim: &Sim, c: &Chain, t: &super::chain::Task, on_track: bool) -> Result<(), Reason> {
    if sim.intent.pure || on_track { return Ok(()); }
    sense(sim, c, t)
}

pub(super) fn set(sim: &mut Sim, h: u32, status: Status, reason: Option<Reason>, tick: u32) {
    let s = &mut sim.intent.hq[h as usize];
    if s.status == status && s.reason == reason { return; }
    // «армия в N км»: расстояние меняется каждый час — смена записывается, только если сменилась причина
    if s.status == status && matches!((&s.reason, &reason), (Some(Reason::Strayed { .. }), Some(Reason::Strayed { .. }))) { s.reason = reason; return; }
    *s = HqState { status, reason: reason.clone(), since: tick };
    sim.intent.log.push((tick, h, status, reason));
}

/// Шаг диспетчера (фаза командования, до решений командующих и штабов).
pub fn step(sim: &mut Sim, tick: u32) {
    if !sim.intent.any() { return; }
    if !sim.intent.actions.is_empty() { super::intervene::due(sim, tick); }
    let r = sim.rules.intent.clone();
    for ci in 0..sim.intent.chains.len() {
        let owner = sim.intent.chains[ci].owner;
        if player_over(sim, owner) { set(sim, owner, Status::Own, Some(Reason::Player), tick); continue; }
        if sim.intent.pure { dispatch(sim, ci, tick, true, None); continue; }
        let km = stray_km(sim, owner, tick);
        if sim.intent.hq[owner as usize].status == Status::Own {
            if km.is_some_and(|km| km < r.return_km) { try_return(sim, ci, tick); }
            continue;
        }
        if let Some(km) = km.filter(|&km| km > r.leave_km) { leave(sim, owner, Reason::Strayed { km }, tick); continue; }
        let near = km.is_none_or(|km| km <= r.return_km);
        dispatch(sim, ci, tick, near, km);
    }
}

/// Расстояние центра живых дивизий армии от следа эталона на этот час; нет следа, армии в нём или живых — None.
fn stray_km(sim: &Sim, owner: u32, tick: u32) -> Option<f64> {
    let p = sim.intent.track.as_ref()?.at(&sim.world.hqs[owner as usize].id, tick)?;
    let c = mid(&live(sim, owner).iter().map(|&i| sim.world.divisions[i].vars.pos).collect::<Vec<_>>())?;
    Some(c.dist(sim.theatre.proj.to_xy(p)))
}

/// Штаб `h` и все его подчинённые.
pub(super) fn subtree(sim: &Sim, h: u32) -> Vec<usize> {
    let w = &sim.world;
    (0..w.hqs.len()).filter(|&k| { let mut x = k; for _ in 0..8 { if x == h as usize { return true; } match w.hqs[x].parent { Some(p) => x = p as usize, None => return false } } false }).collect()
}

/// Час более поздней задачи цепочки настал — прежние неподанные (задержанные) задачи устарели: курсор за ними. У армии,
/// отошедшей от следа, смена «со сдвигом» с причиной устаревшей задачи записывается всегда (отвод, оставшийся за
/// задержанной задачей, не пропадает молча); у армии у следа (`near`) — молча: она идёт как чистая история. Иначе
/// задержанная задача, поданная позже, перебила бы более позднюю.
fn supersede(sim: &mut Sim, ci: usize, tick: u32, near: bool) {
    let c = &sim.intent.chains[ci];
    let Some(h) = c.tasks[c.next.min(c.tasks.len())..].iter().map(|t| t.at).filter(|&at| at <= tick).max() else { return };
    let owner = c.owner;
    let mut k = c.next;
    let mut last = None;
    while k < c.tasks.len() && c.tasks[k].at < h {
        if !c.tasks[k].issued {
            let why = sense_now(sim, c, &c.tasks[k], near).err().or_else(|| sim.intent.hq[owner as usize].reason.clone());
            last = Some(why);
        }
        k += 1;
    }
    sim.intent.chains[ci].next = k;
    if near { return; }
    if let Some(why) = last {
        let s = &mut sim.intent.hq[owner as usize];
        *s = HqState { status: Status::Shifted, reason: why.clone(), since: tick };
        sim.intent.log.push((tick, owner, Status::Shifted, why));
    }
}

/// Задачу `ti` цепочки сменила более поздняя, чей час уже настал.
fn superseded(sim: &Sim, ci: usize, ti: usize) -> bool {
    let c = &sim.intent.chains[ci];
    let at = c.tasks[ti].at;
    c.tasks[ti + 1..].iter().any(|t| t.at > at && t.at <= sim.world.tick)
}

/// Штаб игрока со всеми подчинёнными — с истории («под командованием игрока»).
pub fn take(sim: &mut Sim, hq: u32) {
    let tick = sim.world.tick;
    for k in subtree(sim, hq) { set(sim, k as u32, Status::Own, Some(Reason::Player), tick); }
}

/// Возврат: задача на этот час (последняя с часом не позже нынешнего, не раньше курсора) имеет смысл — цепочка
/// продолжается с неё; задачи между курсором и ею не подаются.
fn try_return(sim: &mut Sim, ci: usize, tick: u32) {
    let c = &sim.intent.chains[ci];
    if c.next >= c.tasks.len() { return; }
    let k = (c.next..c.tasks.len()).take_while(|&j| c.tasks[j].at <= tick).last().unwrap_or(c.next);
    if sense_now(sim, c, &c.tasks[k], true).is_err() { return; }
    let owner = c.owner;
    sim.intent.chains[ci].next = k;
    back(sim, owner, tick);
    dispatch(sim, ci, tick, true, None);
}

/// Отвод сценария дивизии `d`: применяется, если у её армии задача отвода подана (или отвод вне цепочек).
pub fn withdrawal_ok(sim: &Sim, ev: &ScriptWithdraw, d: u32) -> bool {
    if !sim.intent.enabled[side_idx(sim.world.divisions[d as usize].side)] { return true; }
    let owner = army_of(sim, sim.world.divisions[d as usize].hq);
    let same = |w: &ScriptWithdraw| w.at == ev.at && w.to == ev.to && w.note == ev.note;
    match sim.intent.chains.iter().filter(|c| c.owner == owner).flat_map(|c| &c.tasks).find(|t| matches!(&t.step, Step::Withdrawal(w) if same(w))) {
        Some(t) => t.issued,
        None => true,
    }
}

/// Действие вмешательства, ждущее своего часа.
pub enum Action {
    Hold { hq: u32, hours: u32 },
    /// Конец удержания: управление поддерева — как было до него.
    Release { hq: u32, saved: Vec<(usize, Control)> },
    Permit { army: u32, km: f64 },
}

/// Зона изменённого замысла (`drop`): после часа `after` армии `army` задач с целью ближе `km` к `at` нет — ни из
/// истории, ни от командующего.
pub struct DropZone { pub army: u32, pub after: u32, pub at: XY, pub km: f64 }

/// Точка `g` — в зоне изменённого замысла армии на нынешний час.
pub fn banned(sim: &Sim, army: u32, g: XY) -> bool {
    sim.intent.drops.iter().any(|z| z.army == army && sim.world.tick >= z.after && g.dist(z.at) <= z.km)
}

fn defend(from: u32, to: Target, at: XY, rule: &str, note: &str) -> Directive {
    Directive {
        id: format!("вмешательство:держать:{}", match to { Target::Hq(h) => format!("h{h}"), Target::Division(i) => format!("d{i}") }),
        from, to, form: Form::Instruction, task: Task::Defend, axis: Vec::new(), immediate: Some(Line { pts: vec![at], by: None }), subsequent: None,
        boundaries: Vec::new(), main_blow: Vec::new(), reserve: Vec::new(), junction: None, hasty: false, ready: true,
        rule: Some(rule.into()), issued: 0, note: note.into(),
    }
}

/// Действия, чей час настал (шаг диспетчера).
pub fn due(sim: &mut Sim, tick: u32) {
    let (now, rest): (Vec<_>, Vec<_>) = std::mem::take(&mut sim.intent.actions).into_iter().partition(|(at, _)| *at <= tick);
    sim.intent.actions = rest;
    for (_, a) in now {
        match a {
            Action::Hold { hq, hours } => hold(sim, hq, hours, tick),
            Action::Release { hq, saved } => release(sim, hq, saved, tick),
            Action::Permit { army, km } => permit(sim, army, km, tick),
        }
    }
}

fn hold(sim: &mut Sim, hq: u32, hours: u32, tick: u32) {
    let sub = subtree(sim, hq);
    let saved: Vec<(usize, Control)> = sub.iter().map(|&k| (k, sim.command.control[k])).collect();
    for &k in &sub { sim.command.control[k] = Control::Player; }
    super::take(sim, hq);
    let rule = format!("вмешательство: держать рубеж {hours} ч");
    let armies: Vec<usize> = sub.iter().copied().filter(|&k| sim.world.hqs[k].echelon == Echelon::Army).collect();
    for k in armies {
        let d = defend(hq, Target::Hq(k as u32), place(sim, Target::Hq(k as u32)), &rule, "на месте");
        // замысел армии — сразу: директива без оси иначе не сменила бы замысел с осью (agent.rs)
        sim.command.intent[k] = Some(Directive { issued: tick, ..d.clone() });
        crate::command::passing::issue(sim, d, tick);
    }
    for i in live(sim, hq) {
        let (h, at) = (sim.world.divisions[i].hq, sim.world.divisions[i].vars.pos);
        crate::command::passing::issue(sim, defend(h, Target::Division(i as u32), at, &rule, "на месте"), tick);
    }
    sim.journal.push(Event { tick, agent: u32::MAX, text: format!("вмешательство: {} держит рубеж {hours} ч", sim.world.hqs[hq as usize].name) });
    sim.intent.actions.push((tick + hours, Action::Release { hq, saved }));
}

/// Час: число — шаг от начала, строка «ГГГГ-ММ-ДДTЧЧ:ММ» — по календарю сценария.
fn hour_of(sim: &Sim, v: &Value, k: &str) -> Result<u32, String> {
    match &v[k] {
        Value::Number(n) => n.as_u64().map(|n| n as u32).ok_or_else(|| format!("вмешательство: {k} — не час")),
        Value::String(s) => {
            let h = crate::time::parse_hours(s).ok_or_else(|| format!("вмешательство: {k} = {s} — не дата"))? - sim.start_hour;
            u32::try_from(h).map_err(|_| format!("вмешательство: {k} = {s} — раньше начала"))
        }
        _ => Err(format!("вмешательство: нет поля {k}")),
    }
}

fn hq_of(sim: &Sim, v: &Value, k: &str) -> Result<u32, String> {
    let id = v[k].as_str().ok_or_else(|| format!("вмешательство: нет поля {k}"))?;
    sim.world.hqs.iter().position(|h| h.id == id).map(|h| h as u32).ok_or_else(|| format!("вмешательство: нет штаба {id}"))
}

/// Применить вмешательство `case` (`{ "actions": [ … ] }`) к миру до первого шага.
pub fn intervene(sim: &mut Sim, case: &Value) -> Result<(), String> {
    let actions = case["actions"].as_array().ok_or("вмешательство: нет списка actions")?;
    for a in actions {
        let (kind, v) = a.as_object().and_then(|o| o.iter().next()).ok_or("вмешательство: пустое действие")?;
        match kind.as_str() {
            "hold" => {
                let (hq, at, hours) = (hq_of(sim, v, "hq")?, hour_of(sim, v, "from")?, hour_of(sim, v, "hours")?);
                sim.intent.actions.push((at, Action::Hold { hq, hours }));
            }
            "remove" => remove(sim, hq_of(sim, v, "hq")?),
            "drop" => {
                let to = hq_of(sim, v, "to")?;
                let after = hour_of(sim, v, "after")?;
                let near = v["near"].as_array().and_then(|p| Some([p.first()?.as_f64()?, p.get(1)?.as_f64()?])).ok_or("вмешательство: near — [долгота, широта]")?;
                let km = v["km"].as_f64().ok_or("вмешательство: нет поля km")?;
                let p = sim.theatre.proj.to_xy(near);
                let ci = sim.intent.chains.iter().position(|c| c.owner == to).ok_or_else(|| format!("вмешательство: у {} нет цепочки задач", sim.world.hqs[to as usize].id))?;
                let c = &mut sim.intent.chains[ci];
                let hit = |t: &super::chain::Task| t.at >= after && t.goal.is_some_and(|g| g.dist(p) <= km);
                let before = c.tasks[..c.next].iter().filter(|t| hit(t)).count();
                c.tasks.retain(|t| !hit(t));
                c.next -= before;
                sim.intent.drops.push(DropZone { army: to, after, at: p, km });
            }
            "permit" => {
                let army = hq_of(sim, v, "army")?;
                let h = &sim.world.hqs[army as usize];
                if h.side != Side::De || h.echelon != Echelon::Army { return Err(format!("вмешательство: {} — не немецкая армия", h.id)); }
                sim.intent.actions.push((hour_of(sim, v, "at")?, Action::Permit { army, km: v["km"].as_f64().unwrap_or(PERMIT_REAR_KM) }));
            }
            x => return Err(format!("вмешательство: hold | remove | drop | permit, а не {x}")),
        }
    }
    Ok(())
}

/// Разрешение на отход: дивизиям армии — отход к рубежу из её цепочки (следующая задача отвода с пунктом) или на
/// `km` в тыл; армии — тот же замысел от группы армий; запросы корпусов на отход — разрешены; армия — с
/// истории (дальше решают её штабы и командующий).
fn permit(sim: &mut Sim, army: u32, km: f64, tick: u32) {
    let goal = sim.intent.chains.iter().find(|c| c.owner == army)
        .and_then(|c| c.tasks[c.next.min(c.tasks.len())..].iter().find(|t| t.kind == super::chain::Goal::Withdraw && t.goal.is_some()).and_then(|t| t.goal));
    let rule = "вмешательство: разрешение верхней инстанции на отход";
    leave(sim, army, Reason::Intervention("разрешён отход".into()), tick);
    let divs = live(sim, army);
    let mut goals = Vec::new();
    for &i in &divs {
        let at = goal.unwrap_or_else(|| sim.behind(&sim.world, i, km));
        goals.push(at);
        let h = sim.world.divisions[i].hq;
        let d = Directive { id: format!("вмешательство:отход:{i}"), task: Task::Withdraw, ready: false, note: "отход по разрешению".into(), ..defend(army, Target::Division(i as u32), at, rule, "") };
        crate::command::passing::issue(sim, d, tick);
        sim.command.doc_until[i] = tick + 24;
        sim.command.requests.retain(|r| r.division != i as u32);
        sim.command.requests.push(Request { hq: h, tick, division: i as u32, at, answer: Some(true), answered_at: tick });
    }
    if let Some(c) = crate::command::agent::mid(&goals) {
        let from = sim.world.hqs[army as usize].parent.unwrap_or(army);
        let d = Directive { id: format!("вмешательство:отход:h{army}"), task: Task::Withdraw, note: "отход по разрешению".into(), ..defend(from, Target::Hq(army), c, rule, "") };
        crate::command::passing::issue(sim, d, tick);
    }
    let top = sim.world.hqs.iter().position(|h| h.side == Side::De && h.echelon == Echelon::HighCommand).unwrap_or(army as usize) as u32;
    sim.documents.push(Document { tick, hq: top, kind: DocKind::Notice, to: vec![sim.world.hqs[army as usize].id.clone()], text: "отход разрешён".into(), rule: Some(rule.into()) });
}

/// Конец удержания: управление — как было, поддерево снова «по истории» (дальше — по обычным правилам); у цепочки, чья
/// последняя наступившая задача подана до удержания, она подаётся снова — замысел после паузы.
fn release(sim: &mut Sim, hq: u32, saved: Vec<(usize, Control)>, tick: u32) {
    let sub: Vec<usize> = saved.iter().map(|&(k, _)| k).collect();
    for (k, c) in saved {
        sim.command.control[k] = c;
        if c == Control::Agent { sim.command.last_cycle[k] = tick; }
    }
    sim.command.sent.retain(|key, _| !matches!(key.1, Target::Hq(h) if sub.contains(&(h as usize))));
    // «оборонять на месте» снято: армии, ушедшей с истории, нужна задача
    for &k in &sub {
        if sim.command.intent[k].as_ref().is_some_and(|d| d.id.starts_with("вмешательство:держать")) { sim.command.intent[k] = None; }
    }
    for &k in &sub { set(sim, k as u32, Status::History, None, tick); }
    for c in sim.intent.chains.iter_mut().filter(|c| sub.contains(&(c.owner as usize))) {
        if c.tasks[c.next.min(c.tasks.len())..].iter().any(|t| t.at <= tick) { continue; }
        if let Some(j) = (0..c.next.min(c.tasks.len())).rev().find(|&j| c.tasks[j].issued) { c.tasks[j].issued = false; c.next = j; }
    }
    sim.journal.push(Event { tick, agent: u32::MAX, text: format!("вмешательство: {} — снова по замыслу", sim.world.hqs[hq as usize].name) });
}

/// Армия снята: её дивизии не введены в операцию (на карте их нет, в расчёте не участвуют), поддерево — «сам».
fn remove(sim: &mut Sim, hq: u32) {
    let tick = sim.world.tick;
    for i in live(sim, hq) {
        let d = &mut sim.world.divisions[i];
        d.state = State::Pending;
        d.enter = u32::MAX;
        let text = format!("{} выведена из операции (вмешательство: {} снята)", d.name, sim.world.hqs[hq as usize].name);
        sim.journal.push(Event { tick, agent: i as u32, text });
    }
    for k in subtree(sim, hq) { set(sim, k as u32, Status::Own, Some(Reason::Intervention("армия снята с операции".into())), tick); }
}

/// Объекты плана фронта `front` (спецификация, раздел 2.2): цели всех задач цепочек его армий, в любой час — план фронта
/// командующему известен; повторы ближе `PLAN_SAME_KM` — один объект.
pub fn plan_objectives(sim: &Sim, front: u32) -> Vec<XY> {
    let w = &sim.world;
    let under = |h: u32| { let mut k = h as usize; for _ in 0..8 { match w.hqs[k].parent { Some(p) if p == front => return true, Some(p) => k = p as usize, None => return false } } false };
    let mut out: Vec<XY> = Vec::new();
    for c in sim.intent.chains.iter().filter(|c| w.hqs[c.owner as usize].echelon == Echelon::Army && under(c.owner)) {
        for g in c.tasks.iter().filter_map(|t| t.goal) {
            if !out.iter().any(|p| p.dist(g) <= PLAN_SAME_KM) { out.push(g); }
        }
    }
    out
}

/// Почему задача не подана (или цепочка прекращена).
pub enum Reason { Taken, Behind, TooFar, OwnLost, RetreatCut, Unfit, Strayed { km: f64 }, ChainEnd, Player, /// Вмешательство (мерило 2): что изменено.
    Intervention(String) }

/// Направление армии: ось замысла, если он есть; иначе от центра живых дивизий при построении цепочки (`Chain::start`) к нынешнему, если
/// армия сдвинулась больше 2 км; иначе направления нет.
fn army_axis(sim: &Sim, owner: u32, start: Option<XY>, now: XY) -> Option<XY> {
    if let Some(Some(d)) = sim.command.intent.get(owner as usize) {
        if let (Some(a), Some(b)) = (d.axis.first(), d.axis.last()) { if a.dist(*b) > 1e-6 { return Some(XY::new(b.x - a.x, b.y - a.y)); } }
    }
    let s = start?;
    (s.dist(now) > 2.0).then(|| XY::new(now.x - s.x, now.y - s.y))
}

/// Задача выполнена: центр получателя у цели; оборона — только по часу.
pub fn done(sim: &Sim, owner: u32, t: &Task) -> bool {
    let Some(goal) = t.goal else { return false };
    match t.kind {
        Goal::Defend => false,
        _ => {
            let ds = live(sim, owner);
            let pts: Vec<XY> = ds.iter().map(|&i| sim.world.divisions[i].vars.pos).collect();
            mid(&pts).is_some_and(|c| c.dist(goal) <= sim.rules.contact_km)
        }
    }
}

/// Живые дивизии получателя (он и его подчинённые штабы).
pub(super) fn live(sim: &Sim, owner: u32) -> Vec<usize> {
    let w = &sim.world;
    let under = |mut k: usize| { for _ in 0..8 { if k == owner as usize { return true; } match w.hqs[k].parent { Some(p) => k = p as usize, None => return false } } false };
    (0..w.divisions.len()).filter(|&i| !w.divisions[i].state.out() && under(w.divisions[i].hq as usize)).collect()
}

pub fn reason_text(r: &Reason) -> String {
    match r {
        Reason::Taken => "объект уже взят".into(),
        Reason::Behind => "объект позади армии".into(),
        Reason::TooFar => "объект дальше двух переходов".into(),
        Reason::OwnLost => "рубеж потерян".into(),
        Reason::RetreatCut => "путь отхода перерезан".into(),
        Reason::Unfit => "армия не способна выполнять".into(),
        // вверх: со сдвигом (дальше returnKm) никогда не «15 км», при уходе (дальше leaveKm) — не «30 км»
        Reason::Strayed { km } => format!("армия в {} км от исторического места", km.ceil() as i64),
        Reason::ChainEnd => "цепочка кончилась".into(),
        Reason::Player => "под командованием игрока".into(),
        Reason::Intervention(s) => format!("вмешательство: {s}"),
    }
}

fn seg_dist(p: XY, a: XY, b: XY) -> f64 {
    let (dx, dy) = (b.x - a.x, b.y - a.y);
    let l2 = dx * dx + dy * dy;
    if l2 < 1e-9 { return p.dist(a); }
    let t = (((p.x - a.x) * dx + (p.y - a.y) * dy) / l2).clamp(0.0, 1.0);
    p.dist(XY::new(a.x + t * dx, a.y + t * dy))
}

/// Задача имеет смысл (`Ok`) или нет (причина).
/// Берут в расчёт любую свою дивизию (не только армии): «взят» и «рубеж потерян» — по обстановке на карте.
pub fn sense(sim: &Sim, chain: &Chain, t: &Task) -> Result<(), Reason> {
    let owner = chain.owner;
    let w = &sim.world;
    let r = &sim.rules;
    let me = w.hqs[owner as usize].side;
    let ds = live(sim, owner);
    if ds.is_empty() { return Err(Reason::Unfit); }
    let cut = ds.iter().filter(|&&i| w.divisions[i].cut_since.is_some()).count();
    let coh = ds.iter().map(|&i| w.divisions[i].vars.cohesion).sum::<f64>() / ds.len() as f64;
    if cut * 2 > ds.len() || coh <= r.intent.unfit_cohesion { return Err(Reason::Unfit); }
    let Some(goal) = t.goal else { return Ok(()) };
    let c = place(sim, Target::Hq(owner));
    let mine = |i: usize| w.divisions[i].side == me && !w.divisions[i].state.out();
    let foes = || (0..w.divisions.len()).filter(|&i| w.divisions[i].side != me && !w.divisions[i].state.out());
    match t.kind {
        Goal::Attack | Goal::Move => {
            if (0..w.divisions.len()).any(|i| mine(i) && w.divisions[i].vars.pos.dist(goal) <= r.contact_km) { return Err(Reason::Taken); }
            if let Some(ax) = army_axis(sim, owner, chain.start, c) {
                let (gx, gy) = (goal.x - c.x, goal.y - c.y);
                if gx * ax.x + gy * ax.y < 0.0 { return Err(Reason::Behind); }
            }
            let rate = ds.iter().map(|&i| r.enemy_territory_km_day[w.divisions[i].params.mobility as usize]).sum::<f64>() / ds.len() as f64;
            if c.dist(goal) > r.intent.reach_days * rate { return Err(Reason::TooFar); }
            Ok(())
        }
        Goal::Defend => {
            let own = (0..w.divisions.len()).filter(|&i| mine(i)).map(|i| w.divisions[i].vars.pos.dist(goal)).fold(f64::INFINITY, f64::min);
            let foe = foes().map(|i| w.divisions[i].vars.pos.dist(goal)).fold(f64::INFINITY, f64::min);
            if own > r.contact_km || foe < own { Err(Reason::OwnLost) } else { Ok(()) }
        }
        Goal::Withdraw => {
            if foes().any(|i| seg_dist(w.divisions[i].vars.pos, c, goal) <= r.contact_km) { Err(Reason::RetreatCut) } else { Ok(()) }
        }
    }
}

pub struct Track {
    pub fingerprint: String,
    /// Правила, по которым записан след (`RULES`): другой — след устарел.
    #[serde(default)]
    pub rules: String,
    pub hours: u32,
    /// id штаба армии → центр её живых дивизий по часам (None — живых нет).
    pub armies: BTreeMap<String, Vec<Option<LngLat>>>,
}

pub fn at(&self, hq_id: &str, tick: u32) -> Option<LngLat> {
    self.armies.get(hq_id)?.get(tick as usize).copied().flatten()
}

/// Центры армий по часам одного хода (trace.json).
fn centers(trace: &Value) -> BTreeMap<String, Vec<Option<LngLat>>> {
    let arr = |k: &str| trace[k].as_array().cloned().unwrap_or_default();
    let fields = arr("fields");
    let fi = |name: &str| fields.iter().position(|f| f == name);
    let (Some(ilng), Some(ilat), Some(ist)) = (fi("lng"), fi("lat"), fi("state")) else { return BTreeMap::new() };
    let hqs = arr("hqs");
    let hq_pos = |id: &str| hqs.iter().position(|h| h["id"] == id);
    let army_of = |mut i: usize| -> Option<usize> {
        for _ in 0..16 {
            if hqs[i]["echelon"] == "army" { return Some(i); }
            i = hq_pos(hqs[i]["parent"].as_str()?)?;
        }
        None
    };
    let army_idx: Vec<Option<usize>> = arr("divisions").iter().map(|d| d["hq"].as_str().and_then(hq_pos).and_then(army_of)).collect();
    let dead = ["небоеспособна", "сведена в другую дивизию", "не введена в операцию"];
    let mut out: BTreeMap<String, Vec<Option<LngLat>>> = BTreeMap::new();
    for h in hqs.iter().filter(|h| h["echelon"] == "army") { out.insert(h["id"].as_str().unwrap_or_default().to_string(), Vec::new()); }
    for frame in arr("frames") {
        let rows = frame.as_array().cloned().unwrap_or_default();
        let mut acc: BTreeMap<usize, (f64, f64, u32)> = BTreeMap::new();
        for (d, row) in rows.iter().enumerate() {
            let Some(Some(a)) = army_idx.get(d) else { continue };
            if dead.contains(&row[ist].as_str().unwrap_or("")) { continue; }
            let (Some(x), Some(y)) = (row[ilng].as_f64(), row[ilat].as_f64()) else { continue };
            let e = acc.entry(*a).or_default();
            *e = (e.0 + x, e.1 + y, e.2 + 1);
        }
        for (id, v) in out.iter_mut() {
            let a = hq_pos(id).unwrap();
            v.push(acc.get(&a).map(|&(x, y, n)| [x / n as f64, y / n as f64]));
        }
    }
    out
}

/// FNV-1a 64 от текста → 16 hex-знаков.
pub fn fingerprint(scenario_text: &str) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in scenario_text.bytes() { h ^= b as u64; h = h.wrapping_mul(0x100000001b3); }
    format!("{h:016x}")
}

/// След рядом со сценарием; Err — нет файла или отпечаток чужой (запись в журнал — на вызывающем, у кого есть Sim).
pub fn load(scenario_path: &str) -> Result<Track, String> {
    let text = std::fs::read_to_string(track_path(scenario_path)).map_err(|_| "нет следа эталона".to_string())?;
    let t: Track = serde_json::from_str(&text).map_err(|_| "нет следа эталона".to_string())?;
    let scen = std::fs::read_to_string(scenario_path).map_err(|_| "нет следа эталона".to_string())?;
    if t.fingerprint != fingerprint(&scen) || t.rules != RULES { return Err("след эталона устарел — уход по расстоянию выключен".into()); }
    Ok(t)
}

/// Среднее по ходам центров армий; час без живых дивизий в ходе в среднее не входит (во всех — None).
pub fn record(traces: &[Value]) -> Track {
    let per: Vec<_> = traces.iter().map(centers).collect();
    let mut armies: BTreeMap<String, Vec<Option<LngLat>>> = BTreeMap::new();
    let mut hours = 0usize;
    for c in &per {
        for (id, v) in c {
            hours = hours.max(v.len());
            let e = armies.entry(id.clone()).or_default();
            if e.len() < v.len() { e.resize(v.len(), None); }
        }
    }
    for (id, v) in armies.iter_mut() {
        for (t, slot) in v.iter_mut().enumerate() {
            let pts: Vec<LngLat> = per.iter().filter_map(|c| c.get(id).and_then(|s| s.get(t).copied().flatten())).collect();
            *slot = (!pts.is_empty()).then(|| [pts.iter().map(|p| p[0]).sum::<f64>() / pts.len() as f64, pts.iter().map(|p| p[1]).sum::<f64>() / pts.len() as f64]);
        }
    }
    Track { fingerprint: String::new(), rules: RULES.to_string(), hours: hours.saturating_sub(1) as u32, armies }
}

pub fn track_path(scenario_path: &str) -> String {
    format!("{}.intent-track.json", scenario_path.strip_suffix(".json").unwrap_or(scenario_path))
}

/// Корень репозитория: от папки крейта на два уровня вверх.
pub fn repo_root() -> String {
    let here = env!("CARGO_MANIFEST_DIR");
    std::path::Path::new(here).join("../..").canonicalize().map(|p| p.to_string_lossy().into_owned()).unwrap_or_else(|_| ".".into())
}

pub struct LlmConfig {
    /// Адрес сервера с /v1, например http://localhost:1234/v1.
    pub url: String,
    /// Модель (id из /v1/models).
    pub model: String,
    /// Сколько ждать очередной части ответа (поток) или всего ответа (без потока), с.
    pub timeout_s: u64,
    pub temperature: f64,
    pub reasoning: Reasoning,
    /// Потолок токенов ответа (вместе с размышлениями); 0 — без ограничения.
    pub max_tokens: u32,
    /// Одновременных запросов к серверу; 0 — определить замером (probe_parallel).
    pub parallel: usize,
    /// Штабы на модели решают в один час (иначе — вразнобой по часам, как штабы по доктрине): запросы одного часа
    /// уходят параллельно.
    pub sync: bool,
    /// Один запрос на армию: штаб армии решает за свои корпуса (быстрее, но корпус — уже не отдельный агент).
    pub by_army: bool,
}

pub fn describe(&self) -> Value {
    json!({ "url": self.url, "model": self.model, "reasoning": self.reasoning.id(), "maxTokens": self.max_tokens, "parallel": self.parallel, "sync": self.sync, "byArmy": self.by_army })
}

pub fn new(url: &str, model: &str) -> Self {
    LlmConfig {
        url: url.trim_end_matches('/').to_string(), model: model.to_string(), timeout_s: 300, temperature: 0.2,
        reasoning: Reasoning::Default, max_tokens: 0, parallel: 1, sync: false, by_army: false,
    }
}

/// Замер: сколько запросов сервер с этой моделью обслуживает одновременно с выгодой.
pub struct Probe {
    pub best: usize,
    /// (одновременных запросов, токенов в секунду всего, секунд на ступень).
    pub rows: Vec<(usize, f64, f64)>,
}

pub fn to_json(&self) -> Value {
    json!({ "best": self.best, "rows": self.rows.iter().map(|r| json!({ "parallel": r.0, "tokensPerSec": (r.1 * 10.0).round() / 10.0, "secs": (r.2 * 10.0).round() / 10.0 })).collect::<Vec<_>>() })
}

/// Уровень размышлений модели. Серверы понимают его по-разному, поэтому отправляется всё, что распространено:
/// `reasoning_effort` (OpenAI, LM Studio, Ollama), а для «выкл» ещё `chat_template_kwargs.enable_thinking = false`
/// (vLLM, llama.cpp), `think = false` (Ollama) и метка `/no_think` (Qwen3). Незнакомые поля серверы пропускают;
/// если сервер отверг запрос, он повторяется без этих полей.
pub enum Reasoning { Default, Off, Low, Medium, High }

pub fn id(self) -> &'static str {
    match self { Self::Default => "default", Self::Off => "off", Self::Low => "low", Self::Medium => "medium", Self::High => "high" }
}

pub fn parse(s: &str) -> Option<Self> {
    Some(match s { "default" | "" => Self::Default, "off" => Self::Off, "low" => Self::Low, "medium" => Self::Medium, "high" => Self::High, _ => return None })
}

/// Ответ модели.
pub struct Reply {
    /// Ответ без размышлений.
    pub text: String,
    /// Размышления модели (поле reasoning_content / reasoning или <think>…</think> в тексте).
    pub reasoning: String,
    /// Ответ оборван потолком токенов (finish_reason = length).
    pub truncated: bool,
    /// Токенов ответа (по usage сервера, вместе с размышлениями), если сервер их сообщил.
    pub tokens: Option<u64>,
    pub secs: f64,
}

pub fn finish(&mut self, out: &mut Vec<(Part, String)>) {
    if !self.pending.is_empty() { out.push((if self.inside { Part::Think } else { Part::Text }, std::mem::take(&mut self.pending))); }
}

pub fn push(&mut self, s: &str, out: &mut Vec<(Part, String)>) {
    self.pending.push_str(s);
    loop {
        let tag = if self.inside { "</think>" } else { "<think>" };
        let part = if self.inside { Part::Think } else { Part::Text };
        if let Some(k) = self.pending.find(tag) {
            if k > 0 { out.push((part, self.pending[..k].to_string())); }
            self.pending = self.pending[k + tag.len()..].to_string();
            self.inside = !self.inside;
            continue;
        }
        // хвост, который может оказаться началом метки, ждёт следующей части (метка — латиница, граница символа цела)
        let keep = (1..tag.len()).rev().find(|&n| self.pending.ends_with(&tag[..n])).unwrap_or(0);
        let cut = self.pending.len() - keep;
        if cut > 0 { out.push((part, self.pending[..cut].to_string())); self.pending = self.pending[cut..].to_string(); }
        break;
    }
}

fn agent(timeout_s: u64) -> ureq::Agent {
    ureq::AgentBuilder::new().timeout(Duration::from_secs(timeout_s)).build()
}

fn body(cfg: &LlmConfig, messages: &[(String, String)], extras: bool) -> Value {
    let mut msgs: Vec<Value> = messages.iter().map(|(r, c)| json!({ "role": r, "content": c })).collect();
    let mut b = json!({ "model": cfg.model, "temperature": cfg.temperature, "stream": true });
    if cfg.max_tokens > 0 { b["max_tokens"] = json!(cfg.max_tokens); }
    if extras {
        b["stream_options"] = json!({ "include_usage": true });
        match cfg.reasoning {
            Reasoning::Default => {}
            Reasoning::Off => {
                b["reasoning_effort"] = json!("low");
                b["chat_template_kwargs"] = json!({ "enable_thinking": false });
                b["think"] = json!(false);
                if let Some(last) = msgs.iter_mut().rev().find(|m| m["role"] == "user") {
                    last["content"] = json!(format!("{} /no_think", last["content"].as_str().unwrap_or("")));
                }
            }
            r => b["reasoning_effort"] = json!(r.id()),
        }
    }
    b["messages"] = json!(msgs);
    b
}

/// Запрос к чату: сообщения (роль, текст) → текст ответа.
pub fn chat(cfg: &LlmConfig, messages: &[(String, String)]) -> Result<String, String> {
    complete(cfg, messages).map(|r| r.text)
}

/// Запрос к чату с уровнем размышлений и потолком токенов из настроек.
pub fn complete(cfg: &LlmConfig, messages: &[(String, String)]) -> Result<Reply, String> {
    complete_stream(cfg, messages, &mut |_, _| {}, None)
}

/// Запрос к чату потоком: `on` получает размышления и ответ по мере прихода; `cancel` — остановка. Если сервер
/// ответил не потоком, а целиком, ответ разбирается так же. Ожидание каждой части — не дольше `timeout_s`.
pub fn complete_stream(cfg: &LlmConfig, messages: &[(String, String)], on: &mut dyn FnMut(Part, &str), cancel: Option<&AtomicBool>) -> Result<Reply, String> {
    let u = format!("{}/chat/completions", cfg.url);
    let t0 = Instant::now();
    let ag = ureq::AgentBuilder::new().timeout_connect(Duration::from_secs(15)).timeout_read(Duration::from_secs(cfg.timeout_s)).build();
    let send = |extras: bool| ag.post(&u).send_json(body(cfg, messages, extras));
    let resp = match send(true) {
        // сервер отверг незнакомые поля (размышления, учёт токенов в потоке) — без них
        Err(ureq::Error::Status(400 | 422, _)) => send(false),
        r => r,
    };
    let resp = resp.map_err(|e| format!("{u}: {e}"))?;
    let (mut text, mut reasoning) = (String::new(), String::new());
    let mut split = ThinkSplit::default();
    let mut parts: Vec<(Part, String)> = Vec::new();
    let mut emit = |parts: &mut Vec<(Part, String)>, text: &mut String, reasoning: &mut String| {
        for (p, s) in parts.drain(..) {
            match p { Part::Think => reasoning.push_str(&s), Part::Text => text.push_str(&s) }
            on(p, &s);
        }
    };
    let mut truncated = false;
    let mut tokens: Option<u64> = None;
    let mut chunks = 0u64;
    if resp.content_type() == "text/event-stream" {
        let rd = std::io::BufReader::new(resp.into_reader());
        for line in rd.lines() {
            if cancel.is_some_and(|c| c.load(Ordering::Relaxed)) { return Err("остановлено".into()); }
            let line = line.map_err(|e| format!("{u}: {e}"))?;
            let Some(data) = line.strip_prefix("data:").map(str::trim) else { continue };
            if data == "[DONE]" { break; }
            let Ok(v) = serde_json::from_str::<Value>(data) else { continue };
            if let Some(t) = v.pointer("/usage/completion_tokens").and_then(Value::as_u64) { tokens = Some(t); }
            let Some(c) = v.pointer("/choices/0") else { continue };
            if c.get("finish_reason").and_then(Value::as_str) == Some("length") { truncated = true; }
            let d = &c["delta"];
            for key in ["reasoning_content", "reasoning"] {
                if let Some(r) = d.get(key).and_then(Value::as_str).filter(|r| !r.is_empty()) { parts.push((Part::Think, r.to_string())); chunks += 1; }
            }
            if let Some(t) = d.get("content").and_then(Value::as_str).filter(|t| !t.is_empty()) { split.push(t, &mut parts); chunks += 1; }
            emit(&mut parts, &mut text, &mut reasoning);
        }
    } else {
        let v: Value = resp.into_json().map_err(|e| format!("{u}: {e}"))?;
        let c = &v["choices"][0];
        truncated = c.get("finish_reason").and_then(Value::as_str) == Some("length");
        tokens = v.pointer("/usage/completion_tokens").and_then(Value::as_u64);
        for key in ["reasoning_content", "reasoning"] {
            if let Some(r) = c["message"].get(key).and_then(Value::as_str).filter(|r| !r.is_empty()) { parts.push((Part::Think, r.to_string())); }
        }
        split.push(c["message"]["content"].as_str().unwrap_or(""), &mut parts);
    }
    split.finish(&mut parts);
    emit(&mut parts, &mut text, &mut reasoning);
    // шаблон уже открыл <think> в запросе: в ответе только закрывающая метка — всё до неё размышления
    if let Some(k) = text.find("</think>") { reasoning.push_str(&text[..k]); text = text[k + 8..].to_string(); }
    if text.trim().is_empty() && reasoning.is_empty() && !truncated { return Err("в ответе модели нет текста".into()); }
    Ok(Reply { text: text.trim().to_string(), reasoning, truncated, tokens: tokens.or((chunks > 0).then_some(chunks)), secs: t0.elapsed().as_secs_f64() })
}

/// JSON из ответа модели: без рассуждений <think>…</think> и обрамления ```json, от первой «{» до последней «}».
pub fn extract_json(s: &str) -> Option<Value> {
    let s = match (s.find("<think>"), s.rfind("</think>")) { (Some(_), Some(b)) => &s[b + 8..], _ => s };
    let (a, b) = (s.find('{')?, s.rfind('}')?);
    if b <= a { return None; }
    serde_json::from_str(&s[a..=b]).ok()
}

/// Модели сервера: id из /v1/models.
pub fn list_models(url: &str) -> Result<Vec<String>, String> {
    let u = format!("{}/models", url.trim_end_matches('/'));
    let v: Value = agent(15).get(&u).call().map_err(|e| format!("{u}: {e}"))?.into_json().map_err(|e| format!("{u}: {e}"))?;
    let mut ids: Vec<String> = v.get("data").and_then(Value::as_array).map(|a| a.iter().filter_map(|m| m.get("id").and_then(Value::as_str).map(String::from)).collect()).unwrap_or_default();
    ids.sort();
    Ok(ids)
}

/// Определение числа параллельных запросов замером: короткие одинаковые ответы на 1, 2, 4, 8… одновременных
/// запросах; суммарная скорость (токенов в секунду) растёт, пока сервер и чип справляются. Берётся ступень, после
/// которой прибавка меньше 20 %, или последняя без ошибок. Сначала — один запрос на разогрев (загрузка модели).
pub fn probe_parallel(cfg: &LlmConfig, max: usize) -> Result<Probe, String> {
    let mut c = cfg.clone();
    c.reasoning = Reasoning::Off;
    c.max_tokens = 96;
    c.temperature = 0.0;
    let msgs = vec![("user".to_string(), "Перечисли через запятую словами числа от одного до шестидесяти, без пояснений.".to_string())];
    complete(&c, &msgs)?;
    let mut rows: Vec<(usize, f64, f64)> = Vec::new();
    let mut n = 1;
    while n <= max.max(1) {
        let t0 = Instant::now();
        let res: Vec<Result<Reply, String>> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..n).map(|_| s.spawn(|| complete(&c, &msgs))).collect();
            hs.into_iter().map(|h| h.join().unwrap_or_else(|_| Err("поток упал".into()))).collect()
        });
        let secs = t0.elapsed().as_secs_f64();
        if res.iter().any(|r| r.is_err()) { break; }
        let toks: f64 = res.iter().flatten().map(|r| r.tokens.map(|t| t as f64).unwrap_or(r.text.chars().count() as f64 / 3.0)).sum();
        let tps = toks / secs.max(1e-6);
        let gain = rows.last().map(|r| tps / r.1.max(1e-9));
        rows.push((n, tps, secs));
        if matches!(gain, Some(g) if g < 1.2) { break; }
        n *= 2;
    }
    if rows.is_empty() { return Err("сервер не ответил на замер".into()); }
    // лучшая ступень — последняя, давшая прибавку не меньше 20 % к предыдущей
    let mut best = rows[0].0;
    for w in rows.windows(2) { if w[1].1 >= w[0].1 * 1.2 { best = w[1].0; } else { break; } }
    Ok(Probe { best, rows })
}

pub struct Division {
