pub fn at(&self, x: f64) -> f64 {
    let p = &self.0;
    if p.is_empty() { return 0.0; }
    if x <= p[0].0 { return p[0].1; }
    for w in p.windows(2) {
        if x <= w[1].0 { let t = (x - w[0].0) / (w[1].0 - w[0].0); return w[0].1 + t * (w[1].1 - w[0].1); }
    }
    p[p.len() - 1].1
}

