  const cellOf = (lng: number, lat: number) => { const c = Math.floor((lng - w) / dl), r = Math.floor((n - lat) / da); return c < 0 || r < 0 || c >= ov.cols || r >= ov.rows ? -1 : r * ov.cols + c; };
