      if (f === longest) l.style = { ...l.style, labels: [{ text: dm(snaps[b].time), at: [k === 0 ? 0.35 : k === bounds.length - 1 ? 0.65 : 0.5], offset: 6, style: tStyle(10, '#b3261e') }] };
