/** Убрать промежуточные точки на прямых участках. */
/** Начало пути длиной km (по ломаной). */
export function cutAt(t: Theatre, path: LngLat[], km: number): { trail: LngLat[]; km: number } {
  const out: LngLat[] = [path[0]];
  let left = km;
  for (let i = 1; i < path.length; i++) {
    const a = t.proj.toXY(path[i - 1]), b = t.proj.toXY(path[i]);
    const d = dist(a, b);
    if (d >= left) {
      const k = d > 0 ? left / d : 0;
      out.push(t.proj.toLL([a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k]));
      return { trail: out, km };
    }
    left -= d;
    out.push(path[i]);
  }
  return { trail: out, km: km - left };
}

/** Раскрыть RLE с произвольными однобуквенными кодами. */
export function decodeCodes(rle: string, n: number): string[] {
  const out: string[] = new Array(n);
  let i = 0, k = 0;
  for (const ch of rle) {
    if (ch >= '0' && ch <= '9') { k = k * 10 + (ch.charCodeAt(0) - 48); continue; }
    out.fill(ch, i, i + (k || 1));
    i += k || 1;
    k = 0;
  }
  if (i !== n) throw new Error(`растр: ${i} клеток вместо ${n}`);
  return out;
}

/** Раскрыть RLE растра в индексы TERRAIN_CLASSES. */
export function decodeGrid(g: TerrainGrid): Uint8Array {
  const out = new Uint8Array(g.cols * g.rows);
  let i = 0, n = 0;
  for (const ch of g.rle) {
    if (ch >= '0' && ch <= '9') { n = n * 10 + (ch.charCodeAt(0) - 48); continue; }
    const cls = TERRAIN_CODES[ch];
    if (!cls) throw new Error(`terrainGrid: неизвестный код «${ch}»`);
    const k = TERRAIN_CLASSES.indexOf(cls);
    out.fill(k, i, i + (n || 1));
    i += n || 1;
    n = 0;
  }
  if (i !== out.length) throw new Error(`terrainGrid: ${i} клеток вместо ${out.length}`);
  return out;
}

/** Сетка высот: «значение» или «значение*повторы» через запятую → метры. */
export function decodeHeights(g: NonNullable<TheatreData['heightGrid']>): Float32Array {
  const out = new Float32Array(g.cols * g.rows);
  let i = 0;
  for (const tok of g.rle.split(',')) {
    const [v, n] = tok.split('*');
    const h = g.base + Number(v) * g.stepM;
    out.fill(h, i, i + (n ? Number(n) : 1));
    i += n ? Number(n) : 1;
  }
  if (i !== out.length) throw new Error(`heightGrid: ${i} клеток вместо ${out.length}`);
  return out;
}

/** Сжать индексы TERRAIN_CLASSES в RLE (для сборщиков театров и тестов). */
export function encodeGrid(cells: ArrayLike<number>): string {
  const code = Object.fromEntries(Object.entries(TERRAIN_CODES).map(([k, v]) => [TERRAIN_CLASSES.indexOf(v), k]));
  let s = '';
  for (let i = 0; i < cells.length;) {
    let j = i;
    while (j < cells.length && cells[j] === cells[i]) j++;
    s += (j - i > 1 ? j - i : '') + code[cells[i]];
    i = j;
  }
  return s;
}

function pathKm(t: Theatre, path: LngLat[]): number {
  let s = 0;
  for (let i = 1; i < path.length; i++) s += dist(t.proj.toXY(path[i - 1]), t.proj.toXY(path[i]));
  return s;
}

function simplify(pts: LngLat[]): LngLat[] {
  if (pts.length < 3) return pts;
  const out = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    const a = out[out.length - 1], b = pts[i], c = pts[i + 1];
    const cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    if (Math.abs(cross) > 1e-12) out.push(b);
  }
  out.push(pts[pts.length - 1]);
  return out;
}

/** Путь до точки, ближайшей к pos (движение остановлено раньше — перед противником). */
export function trailTo(t: Theatre, trail: LngLat[], pos: LngLat): LngLat[] {
  const p = t.proj.toXY(pos);
  let best = 0, bd = Infinity;
  for (let i = 1; i < trail.length; i++) {
    const a = t.proj.toXY(trail[i - 1]), b = t.proj.toXY(trail[i]);
    const dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy || 1;
    const k = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L));
    const d = Math.hypot(a[0] + dx * k - p[0], a[1] + dy * k - p[1]);
    if (d < bd) { bd = d; best = i; }
  }
  return [...trail.slice(0, best), pos];
}

/**
 * Разграничительная линия между объединениями одной стороны (фронтами, армиями) или с союзником (авиация).
 * right / left — чья полоса справа и слева, если идти по линии от первого пункта к последнему. Действует
 * с from до until (следующая линия той же пары). За концами линии полосы не установлены.
 */
export interface Boundary {
  id: string;
  kind: 'front' | 'army' | 'air';
  side: string;
  right: string;
  left: string;
  title: string;
  from: string;
  until?: string | null;
  line: LngLat[];
  /** Названия пунктов (по точкам линии). */
  places?: string[];
  /** Чьи пункты включительно. */
  inclusive?: string | null;
  note?: string;
  /** Источник: документ, архивный шифр, достоверность A–C. */
  source?: string;
  reliability?: string;
  /**
   * Условие вступления в игре: в переигровке по истории линия действует по расписанию (from), в игре — когда
   * войска объединения group выйдут в радиус radiusKm от точки at (как в истории, когда директиву вызвало
   * именно это), через delayHours (по умолчанию 6 ч — на отдачу директивы). Не выполнено — действует прежняя линия.
   */
  trigger?: BoundaryTrigger;
  delayHours?: number;
  /** Кто установил: сценарий (история), модель-Ставка или игрок (линии армиям); когда отдано. */
  issuedBy?: 'scenario' | 'stavka' | 'player';
  issuedAt?: string;
}

export interface BoundaryTrigger {
  group: string;
  at: LngLat;
  radiusKm: number;
  /** Словами: «правофланговые части 1-го Украинского фронта в районе Ланквиц». */
  text: string;
}

export interface CombatFactor {
  name: string;
  value: number;
}

export interface Formation {
  id: string;
  name: string;
  side: string;
  echelon: Echelon;
  parent: string | null;
  type: string;
  position: LngLat;
  personnel: number;
  tanks: number;
  guns: number;
  /** Начальные значения — для укомплектованности. */
  initial: { personnel: number; tanks: number; guns: number };
  ammo: number;
  fuel: number;
  fatigue: number;
  posture: Posture;
  /** Часов в обороне на месте (для подготовленной обороны). */
  dugInHours: number;
  /** Действующий приказ (после задержки) и маршрут к цели. */
  order: Order | null;
  route: LngLat[] | null;
  /** Задача своего приказа выполнена, соединение идёт к цели вышестоящего (rules.followParentKm) — до нового приказа. */
  followsParent?: boolean;
  /** Выбывшие нарастающим итогом (убитые, раненые, пленные, рассеянные) — из хода агентной модели с полями потерь. */
  losses?: { personnel: number; tanks: number; guns: number };
  /** Уничтожено или распалось. */
  destroyed: boolean;
  /** С какого момента на театре (null — с начала). */
  enterAt: string | null;
  /** Отрезано от снабжения (окружено). */
  cutOff?: boolean;
  /** Сколько часов подряд подвоз не доходит. */
  cutHours?: number;
  /** Остаток складов (сутки), у гарнизонов крепостей (stockDays типа). */
  stock?: number;
  /** Оторвалось от тылов: путь подвоза есть, но длиннее предела — подвоза нет, но это не окружение. */
  outOfSupply?: boolean;
  /** Резерв Ставки, ещё не введённый в сражение: с какого момента может быть введён (enterAt — когда введут). */
  reserveFrom?: string;
  /** Будет выделено из другого формирования в момент enterAt (FormationDef.detachFrom); после выделения поле снимается. */
  detachFrom?: FormationDef['detachFrom'];
}

export interface FormationDef {
  id: string;
  name: string;
  side: string;
  echelon: Echelon;
  parent?: string | null;
  /** Тип из профиля стороны (для действующих формирований). */
  type?: string;
  /** Вид соединения для штатной численности (establishment.json): у дивизий агентной модели — kind сценария. */
  staffKind?: string;
  position?: LngLat;
  personnel?: number;
  tanks?: number;
  guns?: number;
  /** Запасы на начало: боекомплектов и заправок. */
  ammo?: number;
  fuel?: number;
  posture?: Posture;
  /** С какого момента формирование на театре (ввод из резерва, прибытие); до этого его нет на карте. */
  enterAt?: string | null;
  /**
   * Выделено из другого формирования в момент enterAt (корпус оставлен штурмовать крепость, передовой отряд армии):
   * появляется там, где стоит родитель, и забирает у него долю share его сил (людей, танков, орудий) или указанные
   * числа personnel / tanks / guns. Армия в модели — одна точка; так она может разделиться.
   */
  detachFrom?: { formation: string; share?: number; personnel?: number; tanks?: number; guns?: number };
  /** Откуда цифры и положение (для отчёта и справки). */
  note?: string;
}

export type JournalEntry =
  | { kind: 'order'; time: string; formation: string; order: Order; effective: boolean }
  /** path — пройденный путь (по дорогам и улицам), если он не прямой. */
  | { kind: 'move'; time: string; formation: string; from: LngLat; to: LngLat; km: number; path?: LngLat[]; regime?: Regime }
  | { kind: 'combat'; time: string; attackers: string[]; defenders: string[]; at: LngLat; ratio: number; factors: CombatFactor[];
      noise: number; advanceKm: number; attackerLoss: number; defenderLoss: number; outcome: 'breakthrough' | 'advance' | 'held' | 'repelled'; regime?: Regime }
  | { kind: 'supply'; time: string; formation: string; what: 'ammo' | 'fuel' | 'stock'; left: number }
  | { kind: 'encircled'; time: string; formation: string; cut: boolean }
  | { kind: 'destroyed'; time: string; formation: string }
  /** Котёл сдался (окружение без складов и боеприпасов). */
  | { kind: 'capitulated'; time: string; formation: string; personnel: number }
  /** Вырвались из котла приказом на прорыв (тяжёлое вооружение брошено). */
  | { kind: 'brokeOut'; time: string; formation: string; personnel: number }
  /** Выделено из другого формирования (корпус, передовой отряд). */
  | { kind: 'detached'; time: string; formation: string; from: string; personnel: number; tanks: number; guns: number }
  /** Разграничительная линия вступила в силу (директива, распоряжение). */
  | { kind: 'directive'; time: string; boundary: string; side: string; title: string; from: string; issuedBy: string }
  /** Пополнение по дате (Scenario.changes). */
  | { kind: 'reinforced'; time: string; formation: string; personnel: number; tanks: number; guns: number }
  /** Переподчинение по дате: from — прежний штаб. */
  | { kind: 'resubordinated'; time: string; formation: string; from: string | null; to: string }
  /** Изменение по дате не исполнено: change — индекс в Scenario.changes. */
  | { kind: 'change-skipped'; time: string; formation: string; change: number; reason: string };

export interface Order {
  id: string;
  formation: string;
  task: Task;
  /** Цель: точка, район (id из театра) или формирование противника ({ formation }). */
  target?: Target;
  /** С какого момента приказ отдан (исполнение — после задержки доведения). */
  issuedAt: string;
  /** Кто отдал: эксперт, модель, сценарий. */
  source: Controller;
  note?: string;
  /**
   * Срок по документу: источник, достоверность A/B/C, цитата и documented — документальный срок отдачи. issuedAt —
   * условный срок модели: приказ, дошедший в любой момент хода, действует на весь ход (rules.orderPartialTurn — иначе).
   */
  basis?: { reliability: 'A' | 'B' | 'C'; source: string; quote?: string; documented?: string };
  /** Форма (игра на агентной модели, командование по ступеням): приказ — сутки на ступень; нет — боевое распоряжение. */
  form?: 'order' | 'instruction';
}

export const REGIME_RU: Record<Regime, string> = {
  pocket: 'бой в котле', urban: 'бой в застройке', belt: 'бой в укреплённой полосе', river: 'бой за переправу', forest: 'бой в лесу и болоте',
  open: 'бой на открытой местности', march: 'марш', withdraw: 'отход', approach: 'выдвижение к противнику', pursuitMobile: 'преследование подвижными соединениями', pursuitFoot: 'преследование общевойсковыми армиями',
};

export interface Rules {
  id: string;
  /** Базовые правила, поверх которых пишутся поля этого файла (масштабный вариант). */
  extends?: string;
  /** Расстояние соприкосновения, км: ближе — бой. */
  contactKm: number;
  /** Темп продвижения наступающего, км/сутки, от соотношения сил. */
  advance: Table;
  /** Потери наступающего и обороняющегося, доля состава в сутки, от соотношения сил. */
  attackerLoss: Table;
  defenderLoss: Table;
  /** Поправки к силе обороняющегося. */
  defense: {
    /** За местность. */
    terrain: Partial<Record<TerrainClass, number>>;
    /** Подготовленная оборона: множитель после prepareHours в обороне на месте. */
    prepared: number;
    prepareHours: number;
    /** Укрепления района: множитель за каждый уровень. */
    fortificationPerLevel: number;
  };
  /** Боеприпасы < 0,5 боекомплекта — сила × этот множитель; горючего нет — подвижные части × fuelOut. */
  ammoShort: number;
  fuelOut: number;
  /** Усталость: сила × (1 − fatigue × fatigueEffect); прирост в бою и на марше, отдых — снижение (доля/сутки). */
  fatigueEffect: number;
  fatigueGain: { combat: number; march: number; rest: number };
  /** Разброс исхода боя: σ логнормального множителя к соотношению сил. */
  noise: number;
  /** Пересечение реки без моста: доп. часов на клетку для пеших; техника — только по мостам (если не bridgeless). */
  riverCrossHours: number;
  /**
   * Множитель темпа продвижения в бою по местности обороняющегося: город —
   * кварталами (сотни метров в сутки), лес и болото — медленнее открытой местности.
   */
  advanceTerrain?: Partial<Record<TerrainClass, number>>;
  /**
   * Преодоление укреплённой полосы противника вне боя (мины, рвы, заграждения):
   * часов на клетку за каждый уровень укреплённости, пока полоса не прорвана
   * (клетку не заняли войска стороны).
   */
  fortCrossHours?: number;
  /**
   * Предельный темп «прогрызания» укреплённой полосы, км/сутки, по уровню
   * укреплённости клеток обороняющихся (индекс — уровень 1..3): пока оборона
   * стоит в полосе, прорыва (выхода на оперативный простор) нет при любом перевесе.
   */
  fortAdvanceKm?: number[];
  /** Городской масштаб: части с приказом «держаться» (и окружённые) не отходят сами, но под натиском уступают кварталы с повышенными потерями. */
  holdGivesGround?: boolean;
  /** Обход крепостей подвижными соединениями (по умолчанию — да; в городском бою — нет: там гарнизоны и есть цель). */
  bypassStrongpoints?: boolean;
  /**
   * Территория как сплошная полоса: клетки переходят к стороне, только когда её войска проходят через них
   * (в радиусе radiusKm от пути и положения). По территории противника движение медленнее — заслоны,
   * разрушения, зачистка: к времени марша добавляется клетка / enemyKmPerDay[подвижность]. Подвоз — только
   * по своей территории. Нет поля — территория не ведётся (как раньше).
   */
  territory?: { radiusKm: number; enemyKmPerDay: Partial<Record<Mobility, number>>;
    /** Подвоз проходит и по чужой территории, где наши войска ближе этого (км) и ближе противника (по умолчанию — contactKm); 0 — только по своей. */
    supplyHoldKm?: number;
    /**
     * Закрепление земли за фронтом (каждый ход): клетка противника переходит к стороне, если там перевес влияния её
     * войск, войск противника нет ближе consolidateKm (по умолчанию 1,5 × contactKm; 0 — выключено), а своя земля
     * есть с трёх сторон из четырёх в пределах consolidateReachKm (по умолчанию 24 км).
     */
    consolidateKm?: number; consolidateReachKm?: number };
  /** Через сколько часов непрерывного разрыва подвоза формирование считается окружённым (по умолчанию 36). */
  encircleHours?: number;
  /**
   * Приказ действует с момента доведения, а не с начала хода: в ход, когда приказ дошёл, формирование движется
   * только оставшееся до конца хода время (иначе приказ в 18:00 действует с 05:00 того же хода, на сутки раньше).
   */
  orderPartialTurn?: boolean;
  /**
   * Подвоз как пропускная способность (если блок есть). Горючее подвижных частей на марше тратится по пройденному
   * пути (fuelPer100km запр. на 100 км — «расход горючего на 100 км» вермахта), а не по суткам; пополнение
   * замедляется с удалением от базы: пока путь подвоза не длиннее fullHours (один рейс автотранспорта в сутки), —
   * полное, дальше — fullHours / часы пути, до предела profile.supply.rangeHours.
   */
  // … строки 169–223

export interface Scenario {
  id: string;
  name: string;
  start: string;
  end: string;
  /** Длительность хода, часов. */
  turnHours: number;
  theatre: string;
  rules: string;
  sides: SideDef[];
  formations: FormationDef[];
  /** Приказы по сценарию (исторический план или заданные экспертом изменения). */
  orders: Order[];
  /** Источники снабжения сторон: точки или районы (станции, переправы, тыл). Нет — снабжение без подвоза.
   *  phases — склады, действующие с даты from (и до until, если узел потерян): добавляются к постоянным. */
  supply?: Record<string, { sources: (LngLat | string)[]; phases?: { from: string; until?: string; sources: (LngLat | string)[] }[] }>;
  /** Исторические разграничительные линии (директивы): где их нет или за их концами — полосы расчётные. */
  boundaries?: Boundary[];
  /**
   * Изменения по датам (из базы знаний): пополнения и переподчинение. Исполняется в первом ходе, начало которого
   * не раньше at; пополнение ещё не введённого формирования — при его вводе.
   */
  changes?: ScenarioChange[];
}

/** Изменение по дате: пополнение (прибавка к текущим и начальным силам) или переподчинение другому штабу. */
export type ScenarioChange =
  | { at: string; formation: string; kind: 'reinforce'; personnel?: number; tanks?: number; guns?: number }
  | { at: string; formation: string; kind: 'resubordinate'; parent: string };

export interface SideDef {
  id: string;
  name: string;
  profile: string;
  controller: Controller;
}

export interface SideProfile {
  id: string;
  name: string;
  /** Вклад в боевой потенциал: на 1000 человек, на танк/САУ, на орудие/миномёт. */
  weights: { personnel: number; tanks: number; guns: number };
  unitTypes: Record<string, UnitType>;
  /**
   * Сдаются ли окружённые (правила котла — rules.pocket). false — нет: в 1945 г. окружённые части Красной армии
   * держались до деблокирования; по умолчанию — да.
   */
  capitulates?: boolean;
  /** Темп марша вне дорог по местности, км/сутки; 0 — непроходимо. */
  offRoad: Record<Mobility, Record<TerrainClass, number>>;
  /** Темп марша по дороге, км/сутки. */
  road: Record<Mobility, number>;
  /** Расход в сутки по виду действий: боекомплектов и заправок. */
  consumption: Record<Posture, { ammo: number; fuel: number }>;
  /** Задержка доведения приказа до исполнения, часов, по ступени получателя. */
  orderDelayHours: Partial<Record<Echelon, number>>;
  /**
   * Подвоз: пополнение в сутки (боекомплектов, заправок) для формирований, до
   * которых подвоз от источников доходит по своей территории не дольше rangeHours;
   * запасы не выше maxAmmo / maxFuel.
   */
  supply?: { ammoPerDay: number; fuelPerDay: number; maxAmmo: number; maxFuel: number; rangeHours: number;
    /** Перенос базы снабжения: развёртывание на новом месте, часов, и темп переезда, км/сутки (по умолчанию 24 ч и 60 км/сут). */
    baseSetupHours?: number; baseMoveKmPerDay?: number };
  /** Инженерные войска: наводка переправы через большую и малую реку, часов; сколько переправ одновременно (понтонные парки). */
  engineering?: { bridgeHoursMajor: number; bridgeHoursMinor: number; parks: number };
}

export interface SimState {
  scenario: string;
  time: string;
  turn: number;
  formations: Formation[];
  /** Приказы, ещё не дошедшие до исполнителя. */
  pending: Order[];
  rngState: number;
  /** seed прогона (для разброса путей: постоянный на весь прогон). */
  seed?: number;
  journal: JournalEntry[];
  /** С какой записи журнала начинается последний ход (журнал копится за всю операцию). */
  journalFrom?: number;
  /** Клетки укреплённых полос, уже занятые противником их владельца (прорваны). */
  breached?: number[];
  /** Переправы, наведённые сапёрами в ходе расчёта (где тылом не управляет штаб): через большие реки, с какого часа. */
  crossings?: { id: string; side: string; at: LngLat; openFrom: string; name: string }[];
  /** Территория: индекс стороны (по scenario.sides), владеющей клеткой; −1 — ничья. Меняется, только когда через клетку проходят войска. */
  territory?: number[];
  /** Тыл стороны под управлением штаба (игра): базы снабжения и приоритет подвоза. Нет — источники из сценария. */
  logistics?: Record<string, Logistics>;
  /** Поправки посредника на ближайший ход (снимаются после хода). */
  umpire?: UmpireMod[];
  /**
   * Директивы в игре: conditional — линии сценария с условием вступают в силу по обстановке (activated — когда
   * вступили), а не по расписанию. Нет — по расписанию (переигровка по истории).
   */
  directives?: { conditional: boolean; activated: Record<string, string> };
  /** Линии, установленные в ходе игры: модель-Ставка (между фронтами) и игрок (между армиями). */
  boundaries?: Boundary[];
  /** Исполненные изменения по датам — индексы в Scenario.changes. */
  changesDone?: number[];
}

/** Распоряжения штаба помимо приказов войскам: тыл, инженерные, резервы. */
export type StaffAction =
  | { kind: 'base'; side: string; base: string; to: LngLat; toName?: string; issuedAt: string }
  | { kind: 'priority'; side: string; formations: string[]; issuedAt: string }
  | { kind: 'bridge'; side: string; at: LngLat; issuedAt: string; /** штаб, который наводит, — его свободными парками; нет — общим запасом стороны */ by?: string }
  /** Придать штабу понтонные парки (старший — подчинённому: Ставка фронту, фронт армии, армия корпусу). */
  | { kind: 'parks'; side: string; hq: string; n: number; issuedAt: string }
  /** Подорвать мост или переправу у точки (на своей территории): через 2 ч не действует. */
  | { kind: 'demolish'; side: string; at: LngLat; issuedAt: string }
  | { kind: 'commit'; side: string; formation: string; at: LngLat; atName?: string; issuedAt: string }
  /** Разграничительная линия между двумя армиями одного фронта (игрок): вступает в силу с задержкой доведения армиям. */
  | { kind: 'boundary'; side: string; a: string; b: string; line: LngLat[]; places?: string[]; issuedAt: string }
  /** Директива о разграничительной линии между фронтами (модель-Ставка): вступает в силу через delayHours. */
  | { kind: 'directive'; side: string; a: string; b: string; line: LngLat[]; places?: string[]; delayHours: number; reason?: string; issuedAt: string };

export interface TerrainGrid {
  /** [запад, юг, восток, север], градусы. */
  bbox: [number, number, number, number];
  cols: number;
  rows: number;
  /** RLE: число повторов (необязательно, по умолчанию 1) и код класса. */
  rle: string;
  /** Откуда растр и как получен. */
  source?: string;
}

export interface TheatreData {
  id: string;
  name: string;
  /** Ледостав: в эти даты большие реки преодолимы для всех родов войск (по льду и с наводкой), с задержкой riverCrossHours. */
  frozen?: { from: string; until: string; note?: string };
  /** [запад, юг, восток, север], градусы. */
  bbox: [number, number, number, number];
  /** Шаг сетки проходимости, км. */
  cellKm: number;
  defaultTerrain: TerrainClass;
  /**
   * Растр местности (например, из карты земного покрова): сетка в градусах,
   * строки с севера на юг, клетки — буквы TERRAIN_CODES, сжатые RLE («12o3f»).
   * Берётся по центру каждой клетки театра; контуры terrain ложатся поверх.
   */
  terrainGrid?: TerrainGrid;
  /**
   * Растр дорог (например, распознанных по исторической карте): та же схема,
   * что у terrainGrid, коды «n» — нет дороги, «r» — дорога, «h» — шоссе.
   * Дополняет линии roads.
   */
  roadGrid?: TerrainGrid;
  /**
   * Сетка высот (Copernicus DEM, средняя высота клетки): высота = base + значение × stepM, м; строки с севера на
   * юг; rle — «значение» или «значение*повторы» через запятую. Нет — превышение в бою не учитывается.
   */
  heightGrid?: { bbox: [number, number, number, number]; cols: number; rows: number; stepM: number; base: number; rle: string; source?: string };
  /** Контуры местности; позже в списке — поверх. */
  terrain: { class: TerrainClass; ring: LngLat[] }[];
  roads: { kind: 'highway' | 'road' | 'rail'; line: LngLat[]; name?: string }[];
  rivers: { name: string; line: LngLat[]; major: boolean }[];
  /** Мосты и переправы: openFrom — с какого момента действует (наведённая переправа), destroyedAt — с какого разрушен. */
  /** side — чья переправа (наведённая стороной): при передаче командования её будущие наводки снимаются. */
  bridges: { id: string; at: LngLat; name?: string; openFrom?: string | null; destroyedAt?: string | null; side?: string; kind?: string; /** штаб, который навёл (его понтонные парки) */ by?: string }[];
  /** Именованные районы (для приказов и учёта контроля). */
  areas: { id: string; name: string; ring: LngLat[] }[];
  /** Рубежи и позиции: линия и уровень укреплённости (1–3). */
  /** depthKm — глубина полосы (по умолчанию — одна клетка); side — чья полоса. */
  lines: { id: string; name: string; line: LngLat[]; fortification?: number; side?: string; depthKm?: number }[];
  /**
   * Препятствия на дорогах (из сведений об инфраструктуре: разрушена, завалена, заминирована): в радиусе от точки
   * дорога в эти сроки не даёт дорожного темпа — движение как вне дорог. kind rail — сведение (подвоз по железной
   * дороге не моделируется).
   */
  obstacles?: { id: string; at: LngLat; radiusKm: number; kind: 'road' | 'rail'; from?: string | null; until?: string | null; note?: string }[];
  /** Откуда взяты слои (лицензии, даты), для справки и отчёта. */
  sources?: string[];
}

/**
 * Поправка посредника (модель-посредник с опорой на базу знаний): нюанс, который арбитр сам не учитывает
 * (видимость, внезапность, взаимодействие родов войск, заграждения, качество войск…). Действует один ход на
 * бои, где участвует любое из формирований; множитель ограничен UMPIRE_LIMITS. Записывается в игру —
 * переигровка точна.
 */
export interface UmpireMod {
  formations: string[];
  factor: UmpireFactor;
  mult: number;
  reason: string;
  /** На что опирается: записи базы знаний (id) или «обстановка». */
  basis: string[];
}

export interface UnitType {
  id: string;
  name: string;
  mobility: Mobility;
  /** Качество войск: выучка, слаженность, управление (1 — норма эпохи). */
  quality: number;
  /**
   * Ширина полосы обороны, км: обороняющийся связывает боем наступающих в
   * пределах половины этой ширины (а не только в радиусе соприкосновения).
   */
  frontageKm?: number;
  /** Узел обороны (крепость): подвижные соединения, чья цель дальше него, обходят его, а не штурмуют. */
  bypassable?: boolean;
  /**
   * Запасы на складах (сутки боя): окружённое формирование этого типа (гарнизон крепости) получает подвоз с них, пока
   * они не кончились; в осаде без боя расходуются вдвое медленнее. Нет поля — складов нет.
   */
  stockDays?: number;
}

export interface ZoneGrid {
  /** [запад, юг, восток, север] — углы картинки. */
  bbox: [number, number, number, number];
  cols: number;
  rows: number;
  /** Строки сверху вниз (с севера), в строке — с запада; −100..100. */
  v: number[] | Int8Array;
}

export interface ZoneInput {
  /** Свои соединения на карте: место и вес (сила, обычно (численность/10 тыс.)^0,3). */
  own: { at: LngLat; w: number }[];
  /** Обнаруженный разведкой противник. */
  enemy: { at: LngLat; w: number }[];
  /** Территория (SimState.territory): владелец клетки театра — индекс стороны; own / enemy — индексы сторон. */
  territory?: { owner: ArrayLike<number>; own: number; enemy: number };
  /**
   * Поле зрения разведки, км от своих соединений: на земле противника в его пределах — его цвет и без обнаруженных
   * войск (земля за фронтом видна); дальше — только у обнаруженных. Infinity — туман войны снят.
   */
  recon?: number;
  /** Спорные места: бои за ход, отрезанные соединения — там без цвета. */
  contested?: LngLat[];
  /** Радиус влияния соединения, км (σ). По умолчанию — 10 клеток театра, от 2 до 20 км. */
  sigmaKm?: number;
}

/** Расстояние до границы своей и чужой территории, км (двухпроходная фаска по сетке); границы нет — Infinity. */
function frontDistance(own: Int8Array, cols: number, rows: number, step: number): Float64Array {
  const N = cols * rows, D = new Float64Array(N).fill(Infinity);
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const i = r * cols + c, o = own[i];
    if (!o) continue;
    const nb = [[c + 1, r], [c - 1, r], [c, r + 1], [c, r - 1]];
    if (nb.some(([x, y]) => x >= 0 && y >= 0 && x < cols && y < rows && own[y * cols + x] === -o)) D[i] = 0;
  }
  const d1 = step, d2 = step * Math.SQRT2;
  const relax = (i: number, j: number, d: number) => { if (D[j] + d < D[i]) D[i] = D[j] + d; };
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const i = r * cols + c;
    if (c > 0) relax(i, i - 1, d1);
    if (r > 0) { relax(i, i - cols, d1); if (c > 0) relax(i, i - cols - 1, d2); if (c < cols - 1) relax(i, i - cols + 1, d2); }
  }
  for (let r = rows - 1; r >= 0; r--) for (let c = cols - 1; c >= 0; c--) {
    const i = r * cols + c;
    if (c < cols - 1) relax(i, i + 1, d1);
    if (r < rows - 1) { relax(i, i + cols, d1); if (c < cols - 1) relax(i, i + cols + 1, d2); if (c > 0) relax(i, i + cols - 1, d2); }
  }
  return D;
}

export function influenceZones(T: Theatre, inp: ZoneInput): ZoneGrid {
  const [w, s, e, n] = T.data.bbox;
  const sigma = inp.sigmaKm ?? Math.min(20, Math.max(2, T.cellKm * 10));
  const latC = (s + n) / 2;
  const wKm = dist(T.proj.toXY([w, latC]), T.proj.toXY([e, latC])), hKm = dist(T.proj.toXY([w, s]), T.proj.toXY([w, n]));
  const step = Math.max(T.cellKm, Math.max(wKm, hKm) / MAX_SIDE);
  const cols = Math.max(2, Math.ceil(wKm / step)), rows = Math.max(2, Math.ceil(hKm / step));
  const yN = mercY(n), yS = mercY(s);
  const N = cols * rows;
  const X = new Float64Array(N), Y = new Float64Array(N);
  const lngOf = (c: number) => w + ((c + 0.5) / cols) * (e - w);
  const latR = Array.from({ length: rows }, (_, r) => latOf(yN - ((r + 0.5) / rows) * (yN - yS)));
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const p = T.proj.toXY([lngOf(c), latR[r]]);
    X[r * cols + c] = p[0]; Y[r * cols + c] = p[1];
  }
  const colOf = (ll: LngLat) => Math.floor(((ll[0] - w) / (e - w)) * cols);
  const rowOf = (ll: LngLat) => Math.floor(((yN - mercY(ll[1])) / (yN - yS)) * rows);
  /** Обойти клетки в пределах reach км от точки. */
  const around = (ll: LngLat, reach: number, f: (i: number, d: number) => void) => {
    const c0 = colOf(ll), r0 = rowOf(ll), k = Math.ceil(reach / step) + 1;
    const p = T.proj.toXY(ll);
    for (let r = Math.max(0, r0 - k); r <= Math.min(rows - 1, r0 + k); r++) for (let c = Math.max(0, c0 - k); c <= Math.min(cols - 1, c0 + k); c++) {
      const i = r * cols + c, d = Math.hypot(X[i] - p[0], Y[i] - p[1]);
      if (d <= reach) f(i, d);
    }
  };
  const field = (units: ZoneInput['own']) => {
    const F = new Float64Array(N);
    for (const u of units) around(u.at, sigma * 3, (i, d) => { F[i] += u.w * Math.exp(-(d * d) / (2 * sigma * sigma)); });
    return F;
  };
  const A = field(inp.own), B = field(inp.enemy);

  // спорные места — без цвета
  const calm = new Float64Array(N).fill(1);
  const cr = Math.max(T.cellKm, sigma / 3.5);
  for (const at of inp.contested ?? []) around(at, cr * 3, (i, d) => { calm[i] *= 1 - Math.exp(-(d * d) / (2 * cr * cr)); });
  const sat = (x: number) => 1 - Math.exp(-x / K);
  const v = new Array<number>(N).fill(0);
  const put = (i: number, x: number) => { const y = x * calm[i]; v[i] = Math.abs(y) < MIN ? 0 : Math.round(Math.max(-1, Math.min(1, y)) * ZONE_MAX); };

  const t = inp.territory;
  if (!t) {
    // территория не ведётся — по перевесу влияния: цвет сильной стороны, тем бледнее, чем ближе влияние сторон
    for (let i = 0; i < N; i++) {
      const a = sat(A[i]), b = sat(B[i]);
      put(i, a + b > 0 ? Math.sign(a - b) * Math.max(a, b) * Math.sqrt(Math.abs(a - b) / (a + b)) : 0);
    }
    return { bbox: [w, s, e, n], cols, rows, v };
  }
  // территория: сторона — по свою сторону расчётной линии фронта; у самой линии — узкий шов без цвета; в глубину —
  // бледнее (у своих войск — ярче); земля противника — только в поле зрения своей разведки (recon) или у обнаруженных
  const side = new Int8Array(N);
  for (let i = 0; i < N; i++) {
    const k = T.indexOf(T.proj.toLL([X[i], Y[i]]));
    const o = k < 0 ? -1 : t.owner[k];
    side[i] = o === t.own ? 1 : o === t.enemy ? -1 : 0;
  }
  const D = frontDistance(side, cols, rows, step);
  const seen = new Uint8Array(N);
  if (inp.recon === Infinity) seen.fill(1);
  else if (inp.recon) for (const u of inp.own) around(u.at, inp.recon, (i) => { seen[i] = 1; });
  const deep = sigma * 2, seam = Math.max(T.cellKm, sigma / 5);
  for (let i = 0; i < N; i++) {
    if (!side[i]) continue;
    const d = D[i], near = Number.isFinite(d) ? FLOOR * Math.exp(-(d * d) / (2 * deep * deep)) : 0;
    const edge = Number.isFinite(d) ? 1 - Math.exp(-(d * d) / (2 * seam * seam)) : 1;
    const a = sat(A[i]), b = sat(B[i]);
    // своя земля: свои войска или близость к фронту; противник рядом (котёл, вклинение) — бледнее
    if (side[i] === 1) put(i, Math.max(a, near) * (1 - CROSS * b) * edge);
    else put(i, -Math.max(b, seen[i] ? near : 0) * (1 - CROSS * a) * edge);
  }
  return { bbox: [w, s, e, n], cols, rows, v };
}

/**
 * Зоны влияния для стороны side по состоянию игры: свои — все соединения на карте, противник — обнаруженный
 * разведкой (reveal — все: посредник снял туман войны), территория — если правила её ведут; спорные места —
 * contested (бои хода) и отрезанные свои соединения.
 */
export function sideZones(ctx: SimContext, state: SimState, side: string, o: { reveal?: boolean; contested?: LngLat[] } = {}): ZoneGrid {
  const T = ctx.theatre;
  const live = state.formations.filter((f) => onMap(f, state.time));
  const own = live.filter((f) => f.side === side), foe = live.filter((f) => f.side !== side);
  const seen = o.reveal ? null : detected(T, own.map((f) => ({ id: f.id, at: f.position })), foe.map((f) => ({ id: f.id, at: f.position })), detectKm(ctx));
  const sides = ctx.scenario.sides.map((x) => x.id);
  const enemySide = sides.find((x) => x !== side);
  return influenceZones(T, {
    own: own.map((f) => ({ at: f.position, w: weight(f.personnel) })),
    enemy: foe.filter((f) => !seen || seen.has(f.id)).map((f) => ({ at: f.position, w: weight(f.personnel) })),
    ...(state.territory && enemySide ? { territory: { owner: state.territory, own: sides.indexOf(side), enemy: sides.indexOf(enemySide) } } : {}),
    recon: o.reveal ? Infinity : detectKm(ctx),
    contested: [...(o.contested ?? []), ...own.filter((f) => f.cutOff).map((f) => f.position)],
  });
}

/**
 * Зоны влияния для стороны side по снимку переигровки: свои — живые соединения стороны, противник — все остальные
 * живые (туман войны снят: переигровку смотрит сторонний наблюдатель), территория — из снимка; спорные места —
 * отрезанные соединения стороны.
 */
export function snapshotZones(ctx: SimContext, sn: Snapshot, side: string): ZoneGrid {
  const live = sn.units.filter((u) => !u.destroyed);
  const own = live.filter((u) => ctx.scenario.formations.find((f) => f.id === u.id)?.side === side);
  const foe = live.filter((u) => !own.includes(u));
  const sides = ctx.scenario.sides.map((x) => x.id);
  const enemySide = sides.find((x) => x !== side);
  return influenceZones(ctx.theatre, {
    own: own.map((u) => ({ at: u.at, w: weight(u.personnel) })),
    enemy: foe.map((u) => ({ at: u.at, w: weight(u.personnel) })),
    ...(sn.territory && enemySide ? { territory: { owner: sn.territory, own: sides.indexOf(side), enemy: sides.indexOf(enemySide) } } : {}),
    recon: Infinity,
    contested: own.filter((u) => u.cutOff).map((u) => u.at),
  });
}

/** Значение зоны в точке (−1..1); вне сетки — 0. */
export function zoneAt(z: ZoneGrid, ll: LngLat): number {
  const [w, s, e, n] = z.bbox;
  const c = Math.floor(((ll[0] - w) / (e - w)) * z.cols), r = Math.floor(((mercY(n) - mercY(ll[1])) / (mercY(n) - mercY(s))) * z.rows);
  if (c < 0 || r < 0 || c >= z.cols || r >= z.rows) return 0;
  return z.v[r * z.cols + c] / ZONE_MAX;
}

Бой в городе считается на отдельной карте (клетка 250 м, ход 12 ч) с правилами, наследующими
откалиброванные с поправками:

- дистанция соприкосновения — 1,5 км вместо 6;
- «держаться» — не отходить по своей воле, но под натиском уступать кварталы;
- крепости не обходятся: в городе гарнизоны и есть цель;
- темп и потери подобраны отдельно по дням до 28.04 (проверка — 29.04–2.05).

Гарнизон города (~60 000) распределён по секторам обороны A–H и Z по долям из Le Tissier.
Советские корпуса — с оценочной численностью (C).
